app.MapPost("/api/v1/admin/input/visual", async (
    VisualInputRequest request,
    RuntimeInstanceCatalog catalog,
    IHttpClientFactory clientFactory,
    StructureProcessSupervisor supervisor,
    AdminInputRestartGate recoveryGate,
    IConfiguration configuration,
    SimulationState state,
    InputIngressRuntime ingress,
    CancellationToken ct) =>
{
    if (request is null)
    {
        return Results.BadRequest(new { Error = "Request payload missing." });
    }

    var pattern = string.IsNullOrWhiteSpace(request.Pattern) ? "Drift Grating" : request.Pattern.Trim();
    var intensity = Math.Clamp(request.Intensity.GetValueOrDefault(1.0f), 0.2f, 3.0f);
    var burstCount = Math.Clamp(request.BurstCount.GetValueOrDefault(24), 4, 64);
    var targetStructure = string.IsNullOrWhiteSpace(request.TargetStructure)
        ? StructureId.V1
        : Enum.TryParse<StructureId>(request.TargetStructure, ignoreCase: true, out var parsedTarget)
            ? parsedTarget
            : StructureId.V1;
    var sourceStructure = string.IsNullOrWhiteSpace(request.SourceStructure)
        ? StructureId.Thalamus
        : Enum.TryParse<StructureId>(request.SourceStructure, ignoreCase: true, out var parsedSource)
            ? parsedSource
            : StructureId.Thalamus;
    var inputSource = AdminInputSource.Normalize(request.InputSource);
    var requestedHemisphereHint = NormalizeHemisphereHint(request.Hemisphere);
    if (!ingress.TryEnter(AdminInputIngressKind.Video, out var ingressLease, out var ingressSnapshot))
    {
        state.AppendOutputLog(
            $"Visual input throttled by ingress gate: pattern={pattern}, source={sourceStructure}, target={targetStructure}, inputSource={inputSource}.");
        return Results.Json(new
        {
            Error = "Visual input is temporarily throttled due to ingress backpressure.",
            InputSource = inputSource,
            Ingress = ingressSnapshot
        }, statusCode: StatusCodes.Status429TooManyRequests);
    }
    using var _ = ingressLease;

    if (AdminInputSource.IsAvatarSource(inputSource) && !state.IsAvatarVisionEnabled())
    {
        var blockedVisualAttention = state.GetVisualAttentionRuntime();
        state.AppendOutputLog(
            $"Visual input blocked by avatar vision gate: pattern={pattern}, source={sourceStructure}, target={targetStructure}, inputSource={inputSource}.");
        return Results.Ok(new
        {
            Pattern = pattern,
            Source = sourceStructure.ToString(),
            Target = targetStructure.ToString(),
            Intensity = intensity,
            BurstCount = burstCount,
            TargetInstances = 0,
            GeneratedSpikes = 0,
            DeliveredSpikes = 0,
            RecoveryAttempted = false,
            RecoveryRestarted = 0,
            RecoveryHealthy = 0,
            RecoveryRetriedInstances = 0,
            AttentionFocusField = blockedVisualAttention.FocusedField,
            AttentionFocusHemisphere = blockedVisualAttention.FocusedHemisphere,
            AttentionFocusConfidence = blockedVisualAttention.FocusConfidence,
            AttentionAppliedHemisphere = requestedHemisphereHint ?? "both",
            BlockedByInputGate = true,
            InputSource = inputSource,
            Errors = Array.Empty<string>()
        });
    }

    var hasAttentionSignal = request.LeftFieldSaliency is not null || request.RightFieldSaliency is not null;
    var visualAttention = hasAttentionSignal
        ? state.RegisterVisualAttentionObservation(request.LeftFieldSaliency, request.RightFieldSaliency)
        : state.GetVisualAttentionRuntime();
    var visualObservation = Math.Clamp(
        (intensity / 3.0f * 0.58f) +
        (visualAttention.FocusConfidence * 0.24f) +
        (((request.LeftFieldSaliency ?? 0f) + (request.RightFieldSaliency ?? 0f)) * 0.09f),
        0f,
        1f);
    var predictivePerception = state.ObservePredictivePerception(
        "visual",
        $"{inputSource}:{pattern}",
        visualObservation,
        Math.Clamp(0.52f + (visualAttention.FocusConfidence * 0.34f), 0f, 1f),
        inputSource);
    var useAttentionRouting = request.UseAttentionRouting.GetValueOrDefault(true);
    var hemisphereHint = requestedHemisphereHint;
    if (hemisphereHint is null && useAttentionRouting)
    {
        hemisphereHint = ResolveVisualAttentionTargetHemisphere(visualAttention);
    }

    var knownTargetInstances = catalog.GetByStructureWithKnownFallback(targetStructure, hemisphereHint);
    var liveTargetInstances = catalog.GetByStructure(targetStructure, hemisphereHint);
    if (knownTargetInstances.Count == 0)
    {
        return Results.NotFound(new
        {
            Error = $"No active service instances found for {targetStructure} ({(hemisphereHint ?? "both")})."
        });
    }

    if (liveTargetInstances.Count == 0)
    {
        return Results.Ok(new
        {
            Pattern = pattern,
            Source = sourceStructure.ToString(),
            Target = targetStructure.ToString(),
            Intensity = intensity,
            BurstCount = burstCount,
            TargetInstances = liveTargetInstances.Count,
            KnownTargetInstances = knownTargetInstances.Count,
            LiveTargetInstances = liveTargetInstances.Count,
            GeneratedSpikes = 0,
            DeliveredSpikes = 0,
            RecoveryAttempted = false,
            RecoveryRestarted = 0,
            RecoveryHealthy = 0,
            RecoveryRetriedInstances = 0,
            AttentionFocusField = visualAttention.FocusedField,
            AttentionFocusHemisphere = visualAttention.FocusedHemisphere,
            AttentionFocusConfidence = visualAttention.FocusConfidence,
            PredictiveSurprise = predictivePerception.Surprise,
            AttentionAppliedHemisphere = hemisphereHint ?? "both",
            InputSource = inputSource,
            Errors = new[]
            {
                $"No live service instances currently available for {targetStructure} ({(hemisphereHint ?? "both")})."
            }
        });
    }

    if (state.GetSleepMemoryRuntime().IsSleeping)
    {
        return Results.Ok(new
        {
            Pattern = pattern,
            Source = sourceStructure.ToString(),
            Target = targetStructure.ToString(),
            Intensity = intensity,
            BurstCount = burstCount,
            TargetInstances = liveTargetInstances.Count,
            KnownTargetInstances = knownTargetInstances.Count,
            LiveTargetInstances = liveTargetInstances.Count,
            GeneratedSpikes = 0,
            DeliveredSpikes = 0,
            RecoveryAttempted = false,
            RecoveryRestarted = 0,
            RecoveryHealthy = 0,
            RecoveryRetriedInstances = 0,
            AttentionFocusField = visualAttention.FocusedField,
            AttentionFocusHemisphere = visualAttention.FocusedHemisphere,
            AttentionFocusConfidence = visualAttention.FocusConfidence,
            PredictiveSurprise = predictivePerception.Surprise,
            AttentionAppliedHemisphere = hemisphereHint ?? "both",
            PausedDueToSleep = true,
            SleepState = "sleeping",
            Errors = Array.Empty<string>()
        });
    }

    var tick = state.Tick;
    var timestampMs = state.SimulationClockMs;
    var neuromod = state.GlobalNeuromodState;
    var initialDispatch = await DispatchStimulusToInstancesAsync(
        liveTargetInstances,
        instance =>
        {
            var hemisphere = instance.HemisphereNormalized;
            return BuildVisualStimulusSpikes(
                tick,
                timestampMs,
                sourceStructure,
                targetStructure,
                hemisphere,
                pattern,
                intensity,
                burstCount,
                neuromod);
        },
        clientFactory,
        state,
        tick,
        timestampMs,
        ct);

    var generatedSpikes = initialDispatch.GeneratedSpikes;
    var deliveredSpikes = initialDispatch.DeliveredSpikes;
    var errors = new List<string>(initialDispatch.Errors);
    var recoveryAttempted = false;
    var recoveryRestarted = 0;
    var recoveryHealthy = 0;
    var recoveryRetried = 0;

    var recoveryEnabled = configuration.GetValue<bool>("AdminInputRecovery:Enabled", true);
    if (recoveryEnabled &&
        ShouldAttemptSensoryInputRecovery(targetStructure) &&
        deliveredSpikes <= 0 &&
        errors.Count > 0)
    {
        var restartCooldownMs = Math.Clamp(configuration.GetValue<int>("AdminInputRecovery:RestartCooldownMs", 8000), 500, 60000);
        var restartCandidates = recoveryGate.SelectRestartCandidates(liveTargetInstances, restartCooldownMs);
        if (restartCandidates.Count > 0)
        {
            recoveryAttempted = true;
            var restartResult = await supervisor.RestartServicesAsync(restartCandidates, ct);
            recoveryRestarted = restartResult.Restarted;
            recoveryHealthy = restartResult.Healthy;
            state.AppendOutputLog(
                $"Visual input recovery: restarted={restartResult.Restarted}/{restartResult.Requested}, healthy={restartResult.Healthy}, target={targetStructure}.");

            var healthyKeys = restartResult.Items
                .Where(i => i.Healthy)
                .Select(i => i.InstanceKey)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            var retryTargets = healthyKeys.Count > 0
                ? liveTargetInstances.Where(i => healthyKeys.Contains(i.InstanceKey)).ToList()
                : liveTargetInstances;
            if (retryTargets.Count > 0)
            {
                recoveryRetried = retryTargets.Count;
                var retryDispatch = await DispatchStimulusToInstancesAsync(
                    retryTargets,
                    instance =>
                    {
                        var hemisphere = instance.HemisphereNormalized;
                        return BuildVisualStimulusSpikes(
                            tick,
                            timestampMs,
                            sourceStructure,
                            targetStructure,
                            hemisphere,
                            pattern,
                            intensity,
                            burstCount,
                            neuromod);
                    },
                    clientFactory,
                    state,
                    tick,
                    timestampMs,
                    ct);

                generatedSpikes += retryDispatch.GeneratedSpikes;
                deliveredSpikes += retryDispatch.DeliveredSpikes;
                if (retryDispatch.Errors.Count > 0)
                {
                    errors.AddRange(retryDispatch.Errors.Select(e => $"retry:{e}"));
                }
            }
        }
        else if (liveTargetInstances.Count == 0)
        {
            errors.Add($"recovery-skipped:{targetStructure}: no live instances available for synchronous restart");
        }
    }

    state.AppendOutputLog(
        $"Visual input injected: pattern={pattern}, source={sourceStructure}, target={targetStructure}, inputSource={inputSource}, generated={generatedSpikes}, delivered={deliveredSpikes}, liveInstances={liveTargetInstances.Count}, knownInstances={knownTargetInstances.Count}, errors={errors.Count}, recovery={recoveryAttempted}, focus={visualAttention.FocusedField}/{visualAttention.FocusedHemisphere}.");
    if (deliveredSpikes > 0)
    {
        state.AppendSpikeLog(
            $"Visual input {pattern}: delivered {deliveredSpikes}/{generatedSpikes} spikes to {targetStructure}.");
    }

    return Results.Ok(new
    {
        Pattern = pattern,
        Source = sourceStructure.ToString(),
        Target = targetStructure.ToString(),
        Intensity = intensity,
        BurstCount = burstCount,
        TargetInstances = liveTargetInstances.Count,
        KnownTargetInstances = knownTargetInstances.Count,
        LiveTargetInstances = liveTargetInstances.Count,
        GeneratedSpikes = generatedSpikes,
        DeliveredSpikes = deliveredSpikes,
        RecoveryAttempted = recoveryAttempted,
        RecoveryRestarted = recoveryRestarted,
        RecoveryHealthy = recoveryHealthy,
        RecoveryRetriedInstances = recoveryRetried,
        AttentionFocusField = visualAttention.FocusedField,
        AttentionFocusHemisphere = visualAttention.FocusedHemisphere,
        AttentionFocusConfidence = visualAttention.FocusConfidence,
        PredictiveSurprise = predictivePerception.Surprise,
        PredictiveCue = predictivePerception.LastCue,
        AttentionAppliedHemisphere = hemisphereHint ?? "both",
        InputSource = inputSource,
        Errors = errors
    });
});
app.MapPost("/api/v1/admin/input/object", async (
    ObjectInputRequest request,
    RuntimeInstanceCatalog catalog,
    IHttpClientFactory clientFactory,
    SimulationState state,
    InputIngressRuntime ingress,
    CancellationToken ct) =>
{
    if (request is null)
    {
        return Results.BadRequest(new { Error = "Request payload missing." });
    }

    var label = string.IsNullOrWhiteSpace(request.Label) ? "unknown_object" : request.Label.Trim();
    if (label.Length > 96)
    {
        label = label[..96];
    }

    var objectKey = NormalizeObjectKey(request.ObjectId, label);
    var salience = Math.Clamp(request.Salience.GetValueOrDefault(0.72f), 0.05f, 1.0f);
    var confidence = Math.Clamp(request.Confidence.GetValueOrDefault(0.64f), 0.05f, 1.0f);
    var intensity = Math.Clamp(request.Intensity.GetValueOrDefault(0.90f + (salience * 0.60f)), 0.2f, 3.5f);
    var burstCount = Math.Clamp(request.BurstCount.GetValueOrDefault(20), 4, 128);
    var encodeMemory = request.EncodeMemory.GetValueOrDefault(true);
    var inputSource = AdminInputSource.Normalize(request.InputSource);
    if (!ingress.TryEnter(AdminInputIngressKind.Video, out var ingressLease, out var ingressSnapshot))
    {
        state.AppendOutputLog(
            $"Object input throttled by ingress gate: key={objectKey}, label={label}, inputSource={inputSource}.");
        return Results.Json(new
        {
            Error = "Object input is temporarily throttled due to ingress backpressure.",
            InputSource = inputSource,
            Ingress = ingressSnapshot
        }, statusCode: StatusCodes.Status429TooManyRequests);
    }
    using var _ = ingressLease;

    if (AdminInputSource.IsAvatarSource(inputSource) && !state.IsAvatarVisionEnabled())
    {
        state.AppendOutputLog(
            $"Object input blocked by avatar vision gate: key={objectKey}, label={label}, inputSource={inputSource}.");
        return Results.Ok(new
        {
            ObjectId = objectKey,
            Label = label,
            Salience = salience,
            Confidence = confidence,
            Intensity = intensity,
            BurstCount = burstCount,
            Hemisphere = "both",
            RouteStages = 0,
            GeneratedSpikes = 0,
            DeliveredSpikes = 0,
            Targets = Array.Empty<object>(),
            Memory = (ObjectMemoryTrace?)null,
            BlockedByInputGate = true,
            InputSource = inputSource,
            Errors = Array.Empty<string>()
        });
    }

    var hemisphereHint = NormalizeHemisphereHint(request.Hemisphere);
    if (hemisphereHint is null)
    {
        hemisphereHint = ResolveVisualAttentionTargetHemisphere(state.GetVisualAttentionRuntime());
    }
    var objectPredictivePerception = state.ObservePredictivePerception(
        "visual",
        $"object:{label}",
        Math.Clamp((salience * 0.54f) + (confidence * 0.24f) + (intensity / 3.5f * 0.22f), 0f, 1f),
        confidence,
        inputSource);

    var route = BuildObjectPathwayRoute(hemisphereHint);
    var targetSummaries = new List<object>(route.Count);
    var errors = new List<string>();
    var generatedTotal = 0;
    var deliveredTotal = 0;
    var routeStage = 0;
    var tick = state.Tick;
    var timestampMs = state.SimulationClockMs;
    var neuromod = state.GlobalNeuromodState;

    foreach (var stage in route)
    {
        var knownInstances = catalog.GetByStructureWithKnownFallback(stage.Target, hemisphereHint);
        var liveInstances = catalog.GetByStructure(stage.Target, hemisphereHint);
        if (knownInstances.Count == 0)
        {
            errors.Add($"{stage.Target}: no active instances for hemisphere {(hemisphereHint ?? "both")}");
            targetSummaries.Add(new
            {
                source = stage.Source.ToString(),
                target = stage.Target.ToString(),
                knownInstances = 0,
                liveInstances = 0,
                instances = 0,
                generated = 0,
                delivered = 0
            });
            routeStage++;
            continue;
        }

        if (liveInstances.Count == 0)
        {
            errors.Add($"{stage.Target}: no live instances for hemisphere {(hemisphereHint ?? "both")}");
            targetSummaries.Add(new
            {
                source = stage.Source.ToString(),
                target = stage.Target.ToString(),
                knownInstances = knownInstances.Count,
                liveInstances = 0,
                instances = 0,
                generated = 0,
                delivered = 0
            });
            routeStage++;
            continue;
        }

        var stageSeed = routeStage;
        var dispatch = await DispatchStimulusToInstancesAsync(
            liveInstances,
            instance =>
            {
                var hemisphere = instance.HemisphereNormalized;
                return BuildObjectStimulusSpikes(
                    tick,
                    timestampMs,
                    stage.Source,
                    stage.Target,
                    hemisphere,
                    objectKey,
                    label,
                    intensity,
                    salience,
                    confidence,
                    burstCount,
                    stageSeed,
                    neuromod);
            },
            clientFactory,
            state,
            tick,
            timestampMs,
            ct);

        generatedTotal += dispatch.GeneratedSpikes;
        deliveredTotal += dispatch.DeliveredSpikes;
        if (dispatch.Errors.Count > 0)
        {
            errors.AddRange(dispatch.Errors.Select(e => $"{stage.Target}:{e}"));
        }

        targetSummaries.Add(new
        {
            source = stage.Source.ToString(),
            target = stage.Target.ToString(),
            knownInstances = knownInstances.Count,
            liveInstances = liveInstances.Count,
            instances = liveInstances.Count,
            generated = dispatch.GeneratedSpikes,
            delivered = dispatch.DeliveredSpikes
        });
        routeStage++;
    }

    ObjectMemoryTrace? memoryTrace = null;
    if (encodeMemory && deliveredTotal > 0)
    {
        memoryTrace = state.RegisterObjectObservation(
            objectKey,
            label,
            hemisphereHint ?? "M",
            salience,
            confidence,
            intensity,
            deliveredTotal);
    }

    state.AppendOutputLog(
        $"Object input injected: key={objectKey}, label={label}, inputSource={inputSource}, routeStages={route.Count}, generated={generatedTotal}, delivered={deliveredTotal}, errors={errors.Count}, salience={salience:0.00}, confidence={confidence:0.00}.");
    if (deliveredTotal > 0)
    {
        state.AppendSpikeLog(
            $"Object input {label}: delivered {deliveredTotal}/{generatedTotal} spikes via ventral route.");
    }

    return Results.Ok(new
    {
        ObjectId = objectKey,
        Label = label,
        Salience = salience,
        Confidence = confidence,
        Intensity = intensity,
        BurstCount = burstCount,
        Hemisphere = hemisphereHint ?? "both",
        RouteStages = route.Count,
        GeneratedSpikes = generatedTotal,
        DeliveredSpikes = deliveredTotal,
        Targets = targetSummaries,
        Memory = memoryTrace,
        PredictiveSurprise = objectPredictivePerception.Surprise,
        PredictiveCue = objectPredictivePerception.LastCue,
        InputSource = inputSource,
        Errors = errors
    });
});
