    return Results.Ok(backoff.GetSnapshot(max));
});
app.MapGet("/api/v1/admin/language/dialogue", (DialogueTurnManager dialogue) => Results.Ok(dialogue.GetSnapshot()));
app.MapPost("/api/v1/admin/language/dialogue/reset", (DialogueTurnManager dialogue, SimulationState state) =>
{
    dialogue.Reset();
    state.AppendOutputLog("Dialogue turn manager reset.");
    return Results.Ok(new
    {
        Reset = true,
        Dialogue = dialogue.GetSnapshot()
    });
});
app.MapPost("/api/v1/admin/input/language", async (
    LanguageInputRequest request,
    RuntimeInstanceCatalog catalog,
    IHttpClientFactory clientFactory,
    PhoneticLanguageEngine phonetics,
    LanguageBackoffPolicy backoffPolicy,
    DialogueTurnManager dialogueTurns,
    SimulationState state,
    InputIngressRuntime ingress,
    CancellationToken ct) =>
{
    if (!ingress.TryEnter(AdminInputIngressKind.Sensory, out var ingressLease, out var ingressSnapshot))
    {
        state.AppendOutputLog("Language input throttled by ingress gate.");
        return Results.Json(new
        {
            Error = "Language input is temporarily throttled due to ingress backpressure.",
            Ingress = ingressSnapshot
        }, statusCode: StatusCodes.Status429TooManyRequests);
    }
    using var _ = ingressLease;

    var mode = NormalizeLanguageMode(request?.Mode);
    if (request is null ||
        (string.IsNullOrWhiteSpace(request.Text) && !string.Equals(mode, "emergent", StringComparison.OrdinalIgnoreCase)))
    {
        return Results.BadRequest(new { Error = "Provide non-empty language text input, or use mode='emergent'." });
    }

    var text = request.Text?.Trim() ?? string.Empty;
    if (text.Length > 512)
    {
        text = text[..512];
    }

    var defaultNoveltyBias = mode switch
    {
        "emergent" => 0.72f,
        "english" => 0.0f,
        _ => 0.35f
    };
    var noveltyBias = Math.Clamp(
        request.NoveltyBias.GetValueOrDefault(defaultNoveltyBias),
        0.0f,
        1.0f);
    var intensity = Math.Clamp(request.Intensity.GetValueOrDefault(1.0f), 0.2f, 3.0f);
    var burstPerToken = Math.Clamp(request.BurstPerToken.GetValueOrDefault(8), 2, 48);

    if (state.GetSleepMemoryRuntime().IsSleeping)
    {
        var pausedDialogue = dialogueTurns.ObservePaused(text, mode, state.Tick, "sleeping");
        return Results.Ok(new
        {
            Text = text,
            Mode = mode,
            TokenCount = 0,
            SourceTokenCount = 0,
            NoveltyBias = noveltyBias,
            Intensity = intensity,
            BurstPerToken = burstPerToken,
            TargetInstances = 0,
            GeneratedUtterance = text,
            SurfaceTokens = Array.Empty<string>(),
            PhonemeTokens = Array.Empty<string>(),
            CreatedLexemes = 0,
            ReusedLexemes = 0,
            GeneratedSpikes = 0,
            DeliveredSpikes = 0,
            Grammar = (EnglishGrammarAnalysis?)null,
            LanguageIntent = state.GetLanguageIntentSnapshot(),
            BrainNarration = state.GetBrainNarrationSnapshot(),
            TeachingLoop = state.GetBiologicalTeachingLoopSnapshot(),
            Backoff = backoffPolicy.GetSnapshot(12),
            Dialogue = pausedDialogue,
            DeliveredByTarget = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase),
            PausedDueToSleep = true,
            SleepState = "sleeping",
            Errors = Array.Empty<string>()
        });
    }

    var semanticTokens = TokenizeLanguageInput(text);
    var requestedTokenCount = Math.Clamp(request.TokenCount.GetValueOrDefault(6), 1, 24);
    if (semanticTokens.Length == 0 && string.Equals(mode, "emergent", StringComparison.OrdinalIgnoreCase))
    {
        semanticTokens = phonetics.CreateEmergentSemanticSeeds(requestedTokenCount, state.Tick);
    }

    if (semanticTokens.Length == 0)
    {
        return Results.BadRequest(new { Error = "Language input did not contain valid lexical tokens." });
    }

    var lexicalization = string.Equals(mode, "english", StringComparison.OrdinalIgnoreCase)
        ? EnglishLanguageLexicon.Lexicalize(semanticTokens)
        : phonetics.Lexicalize(semanticTokens, mode, state.Tick, noveltyBias);
    var tokens = lexicalization.SurfaceTokens.ToArray();
    if (tokens.Length == 0)
    {
        return Results.BadRequest(new { Error = "Unable to generate emergent phonetic tokens for language routing." });
    }

    var englishGrammar = string.Equals(mode, "english", StringComparison.OrdinalIgnoreCase)
        ? EnglishLanguageLexicon.AnalyzeGrammar(tokens)
        : null;
    var brainTokens = englishGrammar is null
        ? tokens
        : EnglishLanguageLexicon.BuildBrainTokens(tokens, englishGrammar).ToArray();

    var tick = state.Tick;
    var languageIntent = englishGrammar is null
        ? state.GetLanguageIntentSnapshot()
        : state.ObserveLanguageIntent(englishGrammar, tokens, tick);
    var dialogueTurn = dialogueTurns.ObserveInput(mode, text, brainTokens, englishGrammar, languageIntent, tick);
    var teachingEvent = DetectBiologicalTeachingEvent(text, tokens, englishGrammar, languageIntent);
    var teachingLoop = state.ObserveBiologicalTeachingEvent(teachingEvent, englishGrammar, tokens, tick);
    var hemisphereHint = NormalizeHemisphereHint(request.Hemisphere);
    var plan = GetLanguageStimulusPlan(mode);
    var errors = new List<string>();

    var targets = new List<(LanguageStimulusTarget Target, ServiceInstance Instance, string Hemisphere, LanguageBackoffEdgeHandle Edge)>();
    foreach (var target in plan)
    {
        var resolution = backoffPolicy.Resolve(mode, target, catalog, hemisphereHint, tick);
        if (!resolution.Resolved || resolution.Target is null)
        {
            var reason = string.IsNullOrWhiteSpace(resolution.FailureReason) ? "no candidate instances available" : resolution.FailureReason;
            errors.Add($"route {target.SourceStructure}->{target.TargetStructure}: {reason}");
            continue;
        }

        foreach (var instance in resolution.Instances)
        {
            var hemisphere = instance.HemisphereNormalized;
            targets.Add((resolution.Target, instance, hemisphere, resolution.Edge));
        }
    }

    if (targets.Count == 0)
    {
        var failedDialogue = dialogueTurns.RecordDelivery(dialogueTurn, 0, 0, errors, tick);
        return Results.NotFound(new
        {
            Error = $"No active service instances found for language route targets (mode={mode}, hemisphere={(hemisphereHint ?? "auto")}).",
            Dialogue = failedDialogue,
            TeachingLoop = teachingLoop
        });
    }

    var timestampMs = state.SimulationClockMs;
    var neuromod = state.GlobalNeuromodState;
    var generatedSpikes = 0;
    var deliveredSpikes = 0;
    var deliveredByTarget = new ConcurrentDictionary<string, int>(StringComparer.OrdinalIgnoreCase);

    var dispatchTasks = targets.Select(async targetDispatch =>
    {
        var spikes = BuildLanguageStimulusSpikes(
            tick,
            timestampMs,
            targetDispatch.Target,
            targetDispatch.Hemisphere,
            mode,
            brainTokens,
            intensity,
            burstPerToken,
            neuromod);

        Interlocked.Add(ref generatedSpikes, spikes.Count);

        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct);
        timeout.CancelAfter(TimeSpan.FromMilliseconds(900));
        try
        {
            var client = clientFactory.CreateClient("dnne");
            client.BaseAddress = targetDispatch.Instance.Endpoint;
            client.Timeout = Timeout.InfiniteTimeSpan;

            var accepted = await DispatchStimulusSpikesAsync(client, spikes, timeout.Token);
            accepted = Math.Clamp(accepted, 0, spikes.Count);
            if (accepted <= 0)
            {
                return;
            }

            Interlocked.Add(ref deliveredSpikes, accepted);
            deliveredByTarget.AddOrUpdate(
                targetDispatch.Target.TargetStructure.ToString(),
                accepted,
                (_, prev) => prev + accepted);
            backoffPolicy.RecordDispatchResult(targetDispatch.Edge, accepted, null, tick);

            state.RecordDispatchedSpikes(
                tick,
                timestampMs,
                targetDispatch.Hemisphere,
                targetDispatch.Hemisphere,
                targetDispatch.Instance.InstanceKey,
                spikes,
                accepted);
        }
        catch (Exception ex)
        {
            backoffPolicy.RecordDispatchResult(targetDispatch.Edge, 0, ex, tick);
            lock (errors)
            {
                errors.Add($"{targetDispatch.Instance.InstanceKey}: {ex.GetType().Name}: {ex.Message}");
            }
        }
    });

    await Task.WhenAll(dispatchTasks);

    var motorIntentResult = englishGrammar is null
        ? LanguageMotorIntentDispatchResult.Empty
        : await DispatchLanguageIntentMotorSpikesAsync(
            languageIntent,
            catalog,
            clientFactory,
            state,
            tick,
            timestampMs,
            neuromod,
            ct);
    if (motorIntentResult.Errors.Count > 0)
    {
        errors.AddRange(motorIntentResult.Errors);
    }
    generatedSpikes += motorIntentResult.GeneratedSpikes;
    deliveredSpikes += motorIntentResult.DeliveredSpikes;
    var dialogue = dialogueTurns.RecordDelivery(dialogueTurn, generatedSpikes, deliveredSpikes, errors, tick);

    var summaryText = lexicalization.Utterance.Length <= 72 ? lexicalization.Utterance : $"{lexicalization.Utterance[..72]}...";
    var grammarSummary = englishGrammar is null
        ? string.Empty
        : $", grammar={englishGrammar.Intent}/{englishGrammar.Mood}";
    state.AppendOutputLog(
        $"Language input injected: mode={mode}, tokens={tokens.Length}, brainTokens={brainTokens.Length}{grammarSummary}, generated={generatedSpikes}, delivered={deliveredSpikes}, targets={targets.Count}, errors={errors.Count}, utterance=\"{summaryText}\".");
    if (teachingEvent.Active)
    {
        state.AppendOutputLog(
            $"Biological teaching loop observed: kind={teachingEvent.Kind}, concept={teachingEvent.ConceptKey}, reward={teachingEvent.Reward:0.00}, evidence=\"{teachingEvent.Evidence}\".");
    }
    if (deliveredSpikes > 0)
    {
        state.AppendSpikeLog(
            $"Language input {mode}: delivered {deliveredSpikes}/{generatedSpikes} spikes across {deliveredByTarget.Count} targets ({lexicalization.Utterance}).");
    }

    return Results.Ok(new
    {
        Text = text,
        Mode = mode,
        TokenCount = tokens.Length,
        BrainTokenCount = brainTokens.Length,
        SourceTokenCount = semanticTokens.Length,
        NoveltyBias = noveltyBias,
        Intensity = intensity,
        BurstPerToken = burstPerToken,
        TargetInstances = targets.Count,
        GeneratedUtterance = lexicalization.Utterance,
        SurfaceTokens = lexicalization.SurfaceTokens,
        PhonemeTokens = lexicalization.PhonemeTokens,
        Grammar = englishGrammar,
        LanguageIntent = languageIntent,
        BrainNarration = state.GetBrainNarrationSnapshot(),
        TeachingLoop = teachingLoop,
        Dialogue = dialogue,
        MotorIntentTargets = motorIntentResult.TargetInstances,
        MotorIntentGeneratedSpikes = motorIntentResult.GeneratedSpikes,
        MotorIntentDeliveredSpikes = motorIntentResult.DeliveredSpikes,
        CreatedLexemes = lexicalization.CreatedLexemes,
        ReusedLexemes = lexicalization.ReusedLexemes,
        GeneratedSpikes = generatedSpikes,
        DeliveredSpikes = deliveredSpikes,
        Backoff = backoffPolicy.GetSnapshot(12),
        DeliveredByTarget = deliveredByTarget.OrderBy(kv => kv.Key).ToDictionary(kv => kv.Key, kv => kv.Value, StringComparer.OrdinalIgnoreCase),
        PausedDueToSleep = false,
        SleepState = "awake",
        Errors = errors
    });
});
app.MapPost("/api/v1/admin/restart-service", async (
    RestartServiceRequest request,
    SimulationState state,
    RuntimeInstanceCatalog catalog,
    StructureProcessSupervisor supervisor,
    CancellationToken ct) =>
{
    var targetInstances = new List<ServiceInstance>();

    if (!string.IsNullOrWhiteSpace(request.InstanceKey))
    {
        if (!catalog.TryGetByInstanceKey(request.InstanceKey.Trim(), out var instance))
        {
            return Results.NotFound(new
            {
                Error = $"Unknown service instance '{request.InstanceKey}'."
            });
        }

        targetInstances.Add(instance);
    }
    else
    {
        if (string.IsNullOrWhiteSpace(request.StructureId) ||
            !Enum.TryParse<StructureId>(request.StructureId, ignoreCase: true, out var structureId))
        {
            return Results.BadRequest(new
            {
                Error = "Provide a valid structureId or instanceKey."
            });
        }

        var hemisphereHint = NormalizeHemisphereHint(request.Hemisphere);
        targetInstances.AddRange(catalog.GetByStructureWithKnownFallback(structureId, hemisphereHint));
        if (targetInstances.Count == 0)
        {
            return Results.NotFound(new
            {
                Error = $"No service instances registered for structure '{structureId}'."
            });
        }
    }

    var result = await supervisor.RestartServicesAsync(targetInstances, ct);
    state.AppendOutputLog($"Restart service request: requested={result.Requested}, restarted={result.Restarted}, healthy={result.Healthy}.");
    return Results.Ok(result);
});
app.MapGet("/api/v1/admin/network/export", (SimulationState state, SnapshotStore store) =>
{
    var document = state.ExportNetworkState(store.GetLatest());
    return Results.Ok(document);
});
app.MapPost("/api/v1/admin/network/import", async (
    NetworkStateDocument document,
    SimulationState state,
    SnapshotStore store,
    CancellationToken ct) =>
{
    if (document is null)
    {
        return Results.BadRequest(new { Error = "Request payload missing." });
    }

    if (!state.TryImportNetworkState(document, out var importReport, out var error))
    {
        return Results.BadRequest(new { Error = error ?? "Unable to import network state." });
    }

    if (document.LatestSnapshot is not null)
    {
        await store.ClearAsync(ct);
        await store.AppendAsync(document.LatestSnapshot, ct);
        state.MarkSnapshot(document.LatestSnapshot);
    }

    var importedEngrams = document.EngramBank?.Count ?? 0;
    state.AppendOutputLog(
        $"Network state imported: tick={state.Tick}, simMs={state.SimulationClockMs:0.0}, engrams={importedEngrams}, schema={document.SchemaVersion}, migrated={importReport.Migrated}.");
    return Results.Ok(new
    {
        Imported = true,
        document.SchemaVersion,
        state.Tick,
        state.SimulationClockMs,
        Engrams = importedEngrams,
        ImportReport = importReport
    });
});

app.Run();

static bool ParseBooleanQuery(HttpRequest request, string key, bool defaultValue)
{
    if (!request.Query.TryGetValue(key, out var values))
    {
        return defaultValue;
    }

    var value = values.ToString();
    if (string.IsNullOrWhiteSpace(value))
    {
        return defaultValue;
    }

    if (value.Equals("1", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("true", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("yes", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("on", StringComparison.OrdinalIgnoreCase))
    {
        return true;
    }

    if (value.Equals("0", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("false", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("no", StringComparison.OrdinalIgnoreCase) ||
        value.Equals("off", StringComparison.OrdinalIgnoreCase))
    {
        return false;
    }

    return defaultValue;
}

static int ParseIntQuery(HttpRequest request, string key, int defaultValue, int min, int max)
{
    if (!request.Query.TryGetValue(key, out var values))
    {
        return defaultValue;
    }

    var raw = values.ToString();
    if (!int.TryParse(raw, out var parsed))
    {
        return defaultValue;
    }

    return Math.Clamp(parsed, min, max);
}

static List<SpikeMessage> BuildVisualStimulusSpikes(
    long tick,
    double timestampMs,
    StructureId sourceStructure,
    StructureId targetStructure,
    string hemisphere,
    string pattern,
    float intensity,
    int burstCount,
    NeuromodState neuromod)
{
    var patternLabel = string.IsNullOrWhiteSpace(pattern) ? "stimulus" : pattern;
    var patternSeed = Math.Abs(patternLabel.GetHashCode(StringComparison.Ordinal));
    var spikes = new List<SpikeMessage>(burstCount);
    for (var i = 0; i < burstCount; i++)
    {
        var orientation = (patternSeed + i) % 12;
        var channel = (patternSeed + (i * 7)) % 32;
        var vesicle = Math.Clamp((0.75f + (orientation * 0.03f)) * intensity, 0.05f, 6.0f);
        var reuptake = Math.Clamp(4.0f + (channel * 0.08f), 2.0f, 12.0f);
        var spikeType = patternLabel.Equals("Flash", StringComparison.OrdinalIgnoreCase)
            ? SpikeTypeEnum.BURST
            : SpikeTypeEnum.ACTION_POTENTIAL;
        spikes.Add(new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = timestampMs,
            SourceStructure = sourceStructure,
            TargetStructure = targetStructure,
            SourceNeuronId = $"{hemisphere}:visual_{tick}_{orientation}_{i}",
            TargetNeuronId = $"{hemisphere}:v1_orient_{orientation}_cell_{channel}",
            SynapseId = Guid.NewGuid(),
            Neurotransmitter = NTEnum.GLUTAMATE,
            VesicleQuanta = vesicle,
            ReuptakeRate = reuptake,
            SpikeType = spikeType,
            IsFeedback = false,
            ModulationContext = NeuromodState.Clamp(neuromod)
        });
    }

    return spikes;
}

static string NormalizeObjectKey(string? objectId, string label)
{
    var candidate = string.IsNullOrWhiteSpace(objectId) ? label : objectId;
    var normalized = Regex.Replace(candidate.Trim().ToLowerInvariant(), @"[^a-z0-9_]+", "_");
    normalized = normalized.Trim('_');
    return string.IsNullOrWhiteSpace(normalized) ? "object_unknown" : normalized;
}

static IReadOnlyList<ObjectPathwayStage> BuildObjectPathwayRoute(string? hemisphereHint)
{
    var route = new List<ObjectPathwayStage>(4)
    {
        new(StructureId.V2, StructureId.V4),
        new(StructureId.V4, StructureId.TemporalAssociation),
        new(StructureId.TemporalAssociation, StructureId.PerirhinalCortex),
        new(StructureId.TemporalAssociation, StructureId.ParahippocampalCortex)
    };

    if (string.Equals(hemisphereHint, "M", StringComparison.OrdinalIgnoreCase))
    {
        route.Add(new ObjectPathwayStage(StructureId.PerirhinalCortex, StructureId.CorpusCallosum));
    }

    return route;
}

static List<SpikeMessage> BuildObjectStimulusSpikes(
    long tick,
    double timestampMs,
    StructureId sourceStructure,
    StructureId targetStructure,
    string hemisphere,
    string objectKey,
    string label,
    float intensity,
    float salience,
    float confidence,
    int burstCount,
    int stageSeed,
    NeuromodState neuromod)
{
    var seed = Math.Abs(HashCode.Combine(objectKey, label, stageSeed));
    var salienceScale = Math.Clamp(0.60f + (salience * 0.70f), 0.40f, 1.70f);
    var confidenceScale = Math.Clamp(0.55f + (confidence * 0.65f), 0.30f, 1.40f);
    var effectiveIntensity = Math.Clamp(intensity * salienceScale * confidenceScale, 0.1f, 4.0f);
    var spikes = new List<SpikeMessage>(burstCount);

    for (var i = 0; i < burstCount; i++)
    {
        var featureChannel = (seed + (i * 13)) % 64;
        var objectCell = (seed + (i * 7)) % 48;
        var vesicle = Math.Clamp((0.55f + (featureChannel * 0.012f)) * effectiveIntensity, 0.03f, 6.0f);
        var reuptake = Math.Clamp(3.2f + (objectCell * 0.10f), 1.8f, 16.0f);
        var spikeType = i % 6 == 0 ? SpikeTypeEnum.BURST : SpikeTypeEnum.ACTION_POTENTIAL;
        spikes.Add(new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = timestampMs,
            SourceStructure = sourceStructure,
            TargetStructure = targetStructure,
            SourceNeuronId = $"{hemisphere}:{objectKey}:src_{tick}_{featureChannel}_{i}",
            TargetNeuronId = $"{hemisphere}:{objectKey}:obj_{stageSeed}_{objectCell}_{featureChannel}",
            SynapseId = Guid.NewGuid(),
            Neurotransmitter = NTEnum.GLUTAMATE,
            VesicleQuanta = vesicle,
            ReuptakeRate = reuptake,
            SpikeType = spikeType,
            IsFeedback = false,
            ModulationContext = NeuromodState.Clamp(neuromod)
        });
    }

    return spikes;
}

static List<SpikeMessage> BuildAuditoryStimulusSpikes(
    long tick,
    double timestampMs,
    StructureId sourceStructure,
    StructureId targetStructure,
    string hemisphere,
    string pattern,
    float intensity,
    int burstCount,
    NeuromodState neuromod)
{
    var patternLabel = string.IsNullOrWhiteSpace(pattern) ? "auditory" : pattern;
    var patternSeed = Math.Abs(patternLabel.GetHashCode(StringComparison.Ordinal));
    var spikes = new List<SpikeMessage>(burstCount);
    for (var i = 0; i < burstCount; i++)
    {
        var frequencyBand = (patternSeed + (i * 3)) % 24;
        var channel = (patternSeed + (i * 11)) % 48;
        var vesicle = Math.Clamp((0.65f + (frequencyBand * 0.025f)) * intensity, 0.05f, 6.0f);
        var reuptake = Math.Clamp(3.0f + (channel * 0.06f), 1.6f, 10.0f);
        var spikeType = patternLabel.Contains("Burst", StringComparison.OrdinalIgnoreCase)
            ? SpikeTypeEnum.BURST
            : SpikeTypeEnum.ACTION_POTENTIAL;
        spikes.Add(new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = timestampMs,
            SourceStructure = sourceStructure,
            TargetStructure = targetStructure,
            SourceNeuronId = $"{hemisphere}:auditory_{tick}_{frequencyBand}_{i}",
            TargetNeuronId = $"{hemisphere}:a1_tonotopic_{frequencyBand}_cell_{channel}",
            SynapseId = Guid.NewGuid(),
            Neurotransmitter = NTEnum.GLUTAMATE,
            VesicleQuanta = vesicle,
            ReuptakeRate = reuptake,
            SpikeType = spikeType,
            IsFeedback = false,
            ModulationContext = NeuromodState.Clamp(neuromod)
        });
    }

    return spikes;
}

static List<SpikeMessage> BuildCollisionStimulusSpikes(
    long tick,
    double timestampMs,
    StructureId sourceStructure,
    StructureId targetStructure,
    string hemisphere,
    string pattern,
    float intensity,
    int burstCount,
    bool isFeedback,
    NeuromodState neuromod)
{
    var patternLabel = string.IsNullOrWhiteSpace(pattern) ? "collision" : pattern.Trim();
    var patternToken = Regex.Replace(patternLabel, "[^A-Za-z0-9]+", "_");
    if (string.IsNullOrWhiteSpace(patternToken))
    {
        patternToken = "collision";
    }

    var patternSeed = Math.Abs(patternLabel.GetHashCode(StringComparison.Ordinal));
    var spikes = new List<SpikeMessage>(burstCount);
    for (var i = 0; i < burstCount; i++)
    {
        var sector = (patternSeed + i) % 8;
        var lane = (patternSeed + (i * 5)) % 40;
        var vesicle = Math.Clamp((0.95f + (sector * 0.06f)) * intensity, 0.08f, 8.0f);
        var reuptake = Math.Clamp(2.4f + (lane * 0.11f), 1.6f, 14.0f);
        var spikeType = i % 6 == 0 ? SpikeTypeEnum.BURST : SpikeTypeEnum.ACTION_POTENTIAL;
        spikes.Add(new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = timestampMs,
            SourceStructure = sourceStructure,
            TargetStructure = targetStructure,
            SourceNeuronId = $"{hemisphere}:collision_{patternToken}_{tick}_{sector}_{i}",
            TargetNeuronId = $"{hemisphere}:sc_orient_{sector}_cell_{lane}",
            SynapseId = Guid.NewGuid(),
            Neurotransmitter = NTEnum.GLUTAMATE,
            VesicleQuanta = vesicle,
            ReuptakeRate = reuptake,
            SpikeType = spikeType,
            IsFeedback = isFeedback,
            ModulationContext = NeuromodState.Clamp(neuromod)
        });
    }

    return spikes;
}

static List<SpikeMessage> BuildLanguageStimulusSpikes(
    long tick,
    double timestampMs,
    LanguageStimulusTarget target,
    string hemisphere,
    string mode,
    IReadOnlyList<string> tokens,
    float intensity,
    int burstPerToken,
    NeuromodState neuromod)
{
    var spikes = new List<SpikeMessage>(tokens.Count * burstPerToken);
    var modeGain = ComputeLanguageModeNeuromodGain(mode, neuromod);
    for (var tokenIndex = 0; tokenIndex < tokens.Count; tokenIndex++)
    {
        var token = tokens[tokenIndex];
        var tokenHash = Math.Abs(token.GetHashCode(StringComparison.Ordinal));
        for (var i = 0; i < burstPerToken; i++)
        {
            var channel = (tokenHash + (i * 17) + (tokenIndex * 7)) % 96;
            var syllableHint = (token.Length + i) % 8;
            var vesicle = Math.Clamp((0.52f + (token.Length * 0.03f) + (syllableHint * 0.015f)) * intensity * target.Gain * modeGain, 0.05f, 6.0f);
            var reuptake = ResolveLanguageReuptakeRate(mode, channel);
            var spikeType = ResolveLanguageSpikeType(mode, token, i);

            spikes.Add(new SpikeMessage
            {
                MessageId = Guid.NewGuid(),
                TimestampMs = timestampMs,
                SourceStructure = target.SourceStructure,
                TargetStructure = target.TargetStructure,
                SourceNeuronId = $"{hemisphere}:lang_{mode}_{tick}_{tokenIndex}_{i}",
                TargetNeuronId = BuildLanguageTargetNeuronId(hemisphere, target.TargetNeuronPrefix, mode, token, tokenIndex, channel),
                SynapseId = Guid.NewGuid(),
                Neurotransmitter = NTEnum.GLUTAMATE,
                VesicleQuanta = vesicle,
                ReuptakeRate = reuptake,
                SpikeType = spikeType,
                IsFeedback = false,
                ModulationContext = NeuromodState.Clamp(neuromod)
            });
        }
    }

    return spikes;
}

static async Task<LanguageMotorIntentDispatchResult> DispatchLanguageIntentMotorSpikesAsync(
    LanguageIntentRuntime intent,
    RuntimeInstanceCatalog catalog,
    IHttpClientFactory clientFactory,
    SimulationState state,
    long tick,
    double timestampMs,
    NeuromodState neuromod,
    CancellationToken cancellationToken)
{
    if (!intent.Active || string.Equals(intent.MotorDirective, "motor_idle", StringComparison.OrdinalIgnoreCase))
    {
        return LanguageMotorIntentDispatchResult.Empty;
    }

    var motorStructures = new[]
    {
        StructureId.PremotorCortex,
        StructureId.Sma,
        StructureId.M1,
        StructureId.MotorThalamus
    };
    var instances = motorStructures
        .SelectMany(structure => catalog.GetByStructure(structure, null))
        .GroupBy(instance => instance.InstanceKey, StringComparer.OrdinalIgnoreCase)
        .Select(group => group.First())
        .ToArray();
    if (instances.Length == 0)
    {
        return new LanguageMotorIntentDispatchResult(
            0,
            0,
            0,
            ["No live motor structures available for English command intent."]);
    }

    var errors = new ConcurrentBag<string>();
    var generated = 0;
    var delivered = 0;
    var tasks = instances.Select(async instance =>
    {
        var hemisphere = string.IsNullOrWhiteSpace(instance.Hemisphere)
            ? "M"
            : instance.Hemisphere.ToUpperInvariant();
        var spikes = BuildLanguageIntentMotorSpikes(
            tick,
            timestampMs,
            instance.StructureId,
            hemisphere,
            intent,
            neuromod);
        Interlocked.Add(ref generated, spikes.Count);

        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(TimeSpan.FromMilliseconds(700));
        try
        {
            var client = clientFactory.CreateClient("dnne");
            client.BaseAddress = instance.Endpoint;
            client.Timeout = Timeout.InfiniteTimeSpan;
            var accepted = await DispatchStimulusSpikesAsync(client, spikes, timeout.Token);
            accepted = Math.Clamp(accepted, 0, spikes.Count);
            if (accepted <= 0)
            {
                return;
            }

            Interlocked.Add(ref delivered, accepted);
            state.RecordDispatchedSpikes(
                tick,
                timestampMs,
                hemisphere,
                hemisphere,
                instance.InstanceKey,
                spikes,
                accepted);
        }
        catch (Exception ex)
        {
            errors.Add($"{instance.InstanceKey}: motor intent dispatch failed ({ex.GetType().Name}: {ex.Message})");
        }
    });

    await Task.WhenAll(tasks);
    if (delivered > 0)
    {
        state.AppendSpikeLog(
            $"English motor intent {intent.CommandKey}: delivered {delivered}/{generated} motor spikes ({intent.MotorDirective}).");
    }

    return new LanguageMotorIntentDispatchResult(
        generated,
        delivered,
        instances.Length,
        errors.ToArray());
}

static List<SpikeMessage> BuildLanguageIntentMotorSpikes(
    long tick,
    double timestampMs,
    StructureId motorStructure,
    string hemisphere,
    LanguageIntentRuntime intent,
    NeuromodState neuromod)
{
    var burstCount = Math.Clamp((int)Math.Round(6.0 + (intent.Strength * 8.0)), 4, 22);
    var spikes = new List<SpikeMessage>(burstCount);
    var clampedNeuromod = NeuromodState.Clamp(neuromod);
    for (var i = 0; i < burstCount; i++)
    {
        var channel = Math.Abs(HashCode.Combine(intent.CommandKey, motorStructure, hemisphere, i)) % 64;
        var vesicle = Math.Clamp((0.72f + (channel * 0.012f)) * Math.Clamp(intent.Strength, 0.2f, 2.0f), 0.05f, 8.0f);
        spikes.Add(new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = timestampMs,
            SourceStructure = motorStructure,
            TargetStructure = motorStructure,
            SourceNeuronId = $"{hemisphere}:{intent.MotorDirective}_{tick}_{channel}_{i}",
            TargetNeuronId = $"{hemisphere}:{intent.MotorDirective}_pool_{channel}",
            SynapseId = Guid.NewGuid(),
            Neurotransmitter = string.Equals(intent.MotorDirective, "motor_stop", StringComparison.OrdinalIgnoreCase)
                ? NTEnum.GABA
                : NTEnum.GLUTAMATE,
            VesicleQuanta = vesicle,
            ReuptakeRate = Math.Clamp(2.2f + (channel * 0.08f), 1.5f, 12.0f),
            SpikeType = i % 5 == 0 ? SpikeTypeEnum.BURST : SpikeTypeEnum.ACTION_POTENTIAL,
            IsFeedback = false,
            ModulationContext = clampedNeuromod
        });
    }

    return spikes;
}

static float ComputeLanguageModeNeuromodGain(string mode, NeuromodState neuromod)
{
    var m = string.IsNullOrWhiteSpace(mode) ? "repetition" : mode.Trim().ToLowerInvariant();
    var gain = m switch
    {
        "comprehension" => 0.85f + (0.35f * neuromod.AcetylcholineLevel) + (0.15f * neuromod.NorepinephrineLevel),
        "production" => 0.88f + (0.28f * neuromod.DopamineLevel) + (0.14f * neuromod.NorepinephrineLevel),
        "prosody" => 0.86f + (0.24f * neuromod.SerotoninLevel) + (0.18f * neuromod.NorepinephrineLevel) + (0.12f * neuromod.DopamineLevel),
        "emergent" => 0.84f + (0.26f * neuromod.DopamineLevel) + (0.20f * neuromod.AcetylcholineLevel) + (0.16f * neuromod.NorepinephrineLevel),
        "english" => 0.92f + (0.32f * neuromod.AcetylcholineLevel) + (0.12f * neuromod.NorepinephrineLevel) + (0.08f * neuromod.DopamineLevel),
        _ => 0.90f + (0.20f * neuromod.AcetylcholineLevel) + (0.12f * neuromod.DopamineLevel)
    };
    return Math.Clamp(gain, 0.55f, 1.75f);
}

static SpikeTypeEnum ResolveLanguageSpikeType(string mode, string token, int burstIndex)
{
    if (mode.Equals("prosody", StringComparison.OrdinalIgnoreCase))
    {
        return burstIndex % 3 == 0 ? SpikeTypeEnum.GRADED : SpikeTypeEnum.ACTION_POTENTIAL;
    }

    if (mode.Equals("english", StringComparison.OrdinalIgnoreCase))
    {
        return burstIndex % 4 == 0 || token.Length >= 7
            ? SpikeTypeEnum.BURST
            : SpikeTypeEnum.ACTION_POTENTIAL;
    }

    return mode.Equals("repetition", StringComparison.OrdinalIgnoreCase) || token.Length >= 8
        ? SpikeTypeEnum.BURST
        : SpikeTypeEnum.ACTION_POTENTIAL;
}

static float ResolveLanguageReuptakeRate(string mode, int channel)
{
    var baseRate = mode.Equals("prosody", StringComparison.OrdinalIgnoreCase)
        ? 3.2f
        : mode.Equals("english", StringComparison.OrdinalIgnoreCase) ? 2.6f : 2.8f;
    return Math.Clamp(baseRate + (channel * 0.05f), 1.4f, 10.0f);
}

static string BuildLanguageTargetNeuronId(string hemisphere, string prefix, string mode, string token, int tokenIndex, int channel)
{
    if (!mode.Equals("english", StringComparison.OrdinalIgnoreCase))
    {
        return $"{hemisphere}:{prefix}_tok_{tokenIndex}_cell_{channel}";
    }

    var classKey = EnglishLanguageLexicon.ResolveSemanticClassForTarget(token);
    return $"{hemisphere}:{prefix}_{classKey}_tok_{tokenIndex}_cell_{channel}";
}

static string[] TokenizeLanguageInput(string text)
{
    if (string.IsNullOrWhiteSpace(text))
    {
        return Array.Empty<string>();
    }

    var tokens = Regex.Split(text.ToLowerInvariant(), @"[^a-z0-9']+")
        .Where(t => !string.IsNullOrWhiteSpace(t))
        .Take(24)
        .ToArray();
    return tokens;
}

static BiologicalTeachingEvent DetectBiologicalTeachingEvent(
    string text,
    IReadOnlyList<string> surfaceTokens,
    EnglishGrammarAnalysis? grammar,
    LanguageIntentRuntime languageIntent)
{
    var tokens = surfaceTokens.Count > 0 ? surfaceTokens.Select(t => t.ToLowerInvariant()).ToArray() : TokenizeLanguageInput(text);
    if (tokens.Length == 0)
    {
        return BiologicalTeachingEvent.Inactive;
    }

    var lower = (text ?? string.Empty).Trim().ToLowerInvariant();
    var positive = tokens.Any(t => t is "yes" or "good" or "correct" or "right" or "excellent" or "great" or "done");
    var negative = tokens.Any(t => t is "no" or "wrong" or "incorrect" or "bad" or "stop" or "again");
    var remember = tokens.Any(t => t is "remember" or "learn" or "store" or "teach");
    var label = ExtractTeachingLabel(tokens, grammar);
    var isLabel = !string.IsNullOrWhiteSpace(label) &&
                  (tokens.Contains("is") || tokens.Contains("means") || tokens.Contains("called"));

    if (!positive && !negative && !remember && !isLabel)
    {
        return BiologicalTeachingEvent.Inactive;
    }

    var kind = negative
        ? "correction"
        : positive
            ? "reward"
            : remember
                ? "remember"
                : "label";
    var category = kind is "reward" or "correction"
        ? "feedback"
        : ClassifyTeachingCategory(lower);
    var resolvedLabel = kind switch
    {
        "reward" or "correction" when languageIntent.Active => languageIntent.CommandKey,
        "reward" => "recent action",
        "correction" => "recent action",
        _ => string.IsNullOrWhiteSpace(label) ? string.Join(" ", tokens.Take(4)) : label
    };
    var goalKey = kind switch
    {
        "reward" or "correction" when languageIntent.Active => languageIntent.CommandKey,
        "reward" or "correction" => "FollowFeedback",
        _ => ResolveTeachingGoal(category)
    };
    var actionKey = kind switch
    {
        "reward" or "correction" when languageIntent.Active => languageIntent.MotorDirective,
        "reward" or "correction" => "adjust_recent_action",
        _ => ResolveTeachingAction(category)
    };
    var reward = kind switch
    {
        "reward" => 0.70f,
        "correction" => -0.48f,
        "remember" => 0.26f,
        _ => 0.18f
    };
    var success = kind switch
    {
        "reward" => 0.84f,
        "correction" => 0.18f,
        _ => 0.62f
    };
    var threat = category == "threat" || kind == "correction" ? 0.30f : 0.0f;
    var valence = Math.Clamp(reward - threat, -1.0f, 1.0f);
    var salience = kind is "reward" or "correction" ? 0.72f : 0.62f;
    var confidence = remember || isLabel ? 0.76f : 0.66f;
    var meaning = kind switch
    {
        "reward" => $"Positive teaching feedback was associated with {resolvedLabel}.",
        "correction" => $"Corrective teaching feedback was associated with {resolvedLabel}.",
        "remember" => $"The user asked the system to remember {resolvedLabel}.",
        _ => $"The user labeled {resolvedLabel} as {category}."
    };

    return new BiologicalTeachingEvent(
        Active: true,
        Kind: kind,
        ConceptKey: $"teaching.{category}.{NormalizeTeachingKey(resolvedLabel)}",
        Label: resolvedLabel,
        Category: category,
        Meaning: meaning,
        GoalKey: goalKey,
        ActionKey: actionKey,
        Reward: reward,
        Success: success,
        Threat: threat,
        Valence: valence,
        Salience: salience,
        Confidence: confidence,
        Evidence: $"A1/Wernicke language input classified as {kind}; PFC/Hippocampus/VTA/Habenula update requested.");
}

static string ExtractTeachingLabel(IReadOnlyList<string> tokens, EnglishGrammarAnalysis? grammar)
{
    if (!string.IsNullOrWhiteSpace(grammar?.Object))
    {
        return grammar.Object!;
    }

    if (!string.IsNullOrWhiteSpace(grammar?.Qualifier))
    {
        return grammar.Qualifier!;
    }

    var markerIndex = -1;
    for (var i = 0; i < tokens.Count; i++)
    {
        if (tokens[i] is "is" or "means" or "called" or "remember" or "learn" or "store" or "teach")
        {
            markerIndex = i;
            break;
        }
    }

    if (markerIndex < 0 || markerIndex >= tokens.Count - 1)
    {
        return string.Empty;
    }

    var labelTokens = tokens
        .Skip(markerIndex + 1)
        .Where(t => t is not ("a" or "an" or "the" or "to" or "this" or "that"))
        .Take(5)
        .ToArray();
    return labelTokens.Length == 0 ? string.Empty : string.Join(" ", labelTokens);
}

static string ClassifyTeachingCategory(string text)
{
    if (text.Contains("danger", StringComparison.Ordinal) ||
        text.Contains("threat", StringComparison.Ordinal) ||
        text.Contains("predator", StringComparison.Ordinal) ||
        text.Contains("unsafe", StringComparison.Ordinal))
    {
        return "threat";
    }

    if (text.Contains("food", StringComparison.Ordinal) ||
        text.Contains("eat", StringComparison.Ordinal) ||
        text.Contains("berry", StringComparison.Ordinal) ||
        text.Contains("apple", StringComparison.Ordinal) ||
        text.Contains("water", StringComparison.Ordinal))
    {
        return "food";
    }

    if (text.Contains("safe", StringComparison.Ordinal) ||
        text.Contains("shelter", StringComparison.Ordinal) ||
        text.Contains("home", StringComparison.Ordinal))
    {
        return "shelter";
    }

    if (text.Contains("tool", StringComparison.Ordinal) ||
        text.Contains("weapon", StringComparison.Ordinal))
    {
        return "weapon";
    }

    return "language";
}

static string ResolveTeachingGoal(string category) => category switch
{
    "food" => "FindFood",
    "shelter" => "FindShelter",
    "threat" => "AvoidThreat",
    "weapon" => "FindTool",
    _ => "RememberInstruction"
};

static string ResolveTeachingAction(string category) => category switch
{
    "food" => "approach_food",
    "shelter" => "approach_shelter",
    "threat" => "avoid_threat",
    "weapon" => "inspect_tool",
    _ => "encode_language_teaching"
};

static string NormalizeTeachingKey(string value)
{
    var normalized = Regex.Replace((value ?? string.Empty).Trim().ToLowerInvariant(), @"[^a-z0-9]+", ".");
    normalized = normalized.Trim('.');
    return string.IsNullOrWhiteSpace(normalized) ? "unknown" : normalized;
}

static string NormalizeLanguageMode(string? mode)
{
    if (string.IsNullOrWhiteSpace(mode))
    {
        return "repetition";
    }

    var normalized = mode.Trim().ToLowerInvariant();
    return normalized switch
    {
        "comprehension" or "comprehend" or "understand" => "comprehension",
        "production" or "produce" or "speech" => "production",
        "prosody" or "intonation" or "affect" or "melody" or "rhythm" => "prosody",
        "emergent" or "proto" or "novel" or "self" => "emergent",
        "english" or "en" or "natural" or "word" or "words" => "english",
        _ => "repetition"
    };
}

