    public void Configure(double tickDurationMs, Dictionary<StructureId, string> registry, Dictionary<StructureId, List<SynapticConnection>> connectivity)
    {
        lock (_gate)
        {
            TickDurationMs = tickDurationMs;
            ServiceRegistry.Clear();
            foreach (var pair in registry) ServiceRegistry[pair.Key] = pair.Value;
            ConnectivityMap.Clear();
            foreach (var pair in connectivity) ConnectivityMap[pair.Key] = pair.Value;
            RefreshCurriculumSnapshotLocked(Tick);
        }
    }

    public TickSignal AdvanceClockAndCreateTickSignal()
    {
        lock (_gate)
        {
            Tick++;
            SimulationClockMs += TickDurationMs;
            AdvancePhase(BrainRhythm.DELTA, 2.0);
            AdvancePhase(BrainRhythm.THETA, 6.0);
            AdvancePhase(BrainRhythm.ALPHA, 10.0);
            AdvancePhase(BrainRhythm.BETA, 20.0);
            AdvancePhase(BrainRhythm.GAMMA, 40.0);
            return new TickSignal(Tick, SimulationClockMs, TickDurationMs, GlobalNeuromodState, new Dictionary<BrainRhythm, double>(OscillationPhases), RewardPredictionError);
        }
    }

    public void UpdateNeuromod(NeuromodState neuromodState, float rewardPredictionError, AttentionVector attention)
    {
        lock (_gate)
        {
            var clamped = NeuromodState.Clamp(neuromodState);
            var memoryBiased = ApplyMemoryControl(clamped, MemoryControl);
            var dopamineBiased = ApplyDopamineLearningNeuromod(memoryBiased, DopamineLearning);
            GlobalNeuromodState = ApplySleepStateNeuromod(dopamineBiased, SleepMemory);
            RewardPredictionError = rewardPredictionError;
            GlobalAttentionBias = attention;
        }
    }

