    private object GetCachedInhabitanceSnapshotLocked()
    {
        if (_cachedInhabitanceSnapshot is not null && _cachedInhabitanceTick == Tick)
        {
            return _cachedInhabitanceSnapshot;
        }

        _cachedInhabitanceSnapshot = BuildInhabitanceSnapshotLocked();
        _cachedInhabitanceTick = Tick;
        return _cachedInhabitanceSnapshot;
    }

    private void InvalidateCompositeSnapshotCachesLocked()
    {
        _cachedInhabitanceTick = -1;
        _cachedInhabitanceSnapshot = null;
        _cachedCircuitAuditTick = -1;
        _cachedCircuitAuditWarningLimit = 0;
        _cachedCircuitAuditSnapshot = null;
        _cachedConsolidationTelemetryTick = -1;
        _cachedConsolidationTelemetrySnapshot = null;
        _cachedBrainBehaviorTick = -1;
        _cachedBrainBehaviorSnapshot = null;
        _cachedProsodyTelemetryTick = -1;
        _cachedProsodyTelemetrySnapshot = null;
        _cachedRelationalSchemasTick = -1;
        _cachedRelationalSchemas = null;
    }

    private object BuildInhabitanceSnapshotLocked()
    {
        var continuity = Clamp01(
            (AutobiographicalSelf.PfcSelfContinuity * 0.24f) +
            (AutobiographicalSelf.HippocampalIndex * 0.18f) +
            (NarrativeSelfModel.PfcSelfContinuity * 0.18f) +
            (GlobalWorkspace.Stability * 0.16f) +
            (CognitiveLanguageWorkspace.WorkingMemoryStability * 0.14f) +
            (BodySchema.BodyOwnership * 0.10f));
        var embodiment = Clamp01(
            (BodySchema.BodyOwnership * 0.24f) +
            (BodySchema.ProprioceptiveConfidence * 0.18f) +
            (InteroceptiveCore.InsulaBodyFeeling * 0.18f) +
            (PainProtection.Confidence * 0.14f) +
            ((1f - BodySchema.MotorConflict) * 0.14f) +
            (EmbodiedAttentionSpotlight.Confidence * 0.12f));
        var languagePresence = Clamp01(
            (CognitiveLanguageWorkspace.Confidence * 0.24f) +
            (InnerSpeechLoop.Confidence * 0.22f) +
            (NarrativeSelfModel.LanguageNarrativeBinding * 0.20f) +
            (AttentionState.Language * 0.16f) +
            (BrainNarration.Confidence * 0.10f) +
            (BiologicalTeachingLoop.Active ? 0.08f : 0f));
        var presence = Clamp01(
            (continuity * 0.30f) +
            (embodiment * 0.24f) +
            (GlobalWorkspace.BroadcastStrength * 0.18f) +
            (languagePresence * 0.16f) +
            (NarrativeSelfModel.Confidence * 0.12f));
        var place = PlaceMemory.ActivePlaceKey != "none"
            ? PlaceMemory.ActiveLabel
            : AutobiographicalSelf.PlaceContext.Equals("unknown", StringComparison.OrdinalIgnoreCase)
            ? GlobalWorkspace.BroadcastFocus
            : AutobiographicalSelf.PlaceContext;

        return new
        {
            Tick,
            SimulationClockMs,
            Presence = presence,
            Continuity = continuity,
            Embodiment = embodiment,
            LanguagePresence = languagePresence,
            CurrentThought = CognitiveLanguageWorkspace.CurrentThought,
            InnerVoice = InnerSpeechLoop.RehearsedPhrase,
            SelfStatement = NarrativeSelfModel.SelfStatement,
            IdentityThread = AutobiographicalSelf.IdentityThread,
            CurrentChapter = AutobiographicalSelf.CurrentChapter,
            AutobiographicalContinuity = new
            {
                AutobiographicalContinuity.ContinuityThread,
                AutobiographicalContinuity.RecentEpisode,
                AutobiographicalContinuity.DefiningMemory,
                AutobiographicalContinuity.NextRememberedNeed,
                AutobiographicalContinuity.IdentityCoherence,
                AutobiographicalContinuity.RecencyBinding,
                AutobiographicalContinuity.SemanticBridge,
                AutobiographicalContinuity.Confidence
            },
            IdentityBoundary = new
            {
                IdentityBoundary.SelfDescription,
                IdentityBoundary.Boundary,
                IdentityBoundary.Grounding,
                IdentityBoundary.Confidence,
                IdentityBoundary.BoundaryConfidence
            },
            Room = new
            {
                RoomState.Active,
                RoomState.ActiveRoom,
                RoomState.AttentionRestingOn,
                RoomState.CurrentConcern,
                RoomState.RecentUnresolvedThought,
                RoomState.ComfortState,
                RoomState.SafetyState,
                RoomState.RelationshipContext,
                RoomState.WhatIWasDoing,
                RoomState.BiologicalSource,
                RoomState.BiologicalRule,
                RoomState.Confidence
