    public PredictivePerceptionRuntime ObservePredictivePerception(
        string channel,
        string cue,
        float observation,
        float confidence,
        string inputSource)
    {
        lock (_gate)
        {
            return ObservePredictivePerceptionLocked(channel, cue, observation, confidence, inputSource, Tick);
        }
    }

    private PredictivePerceptionRuntime ObservePredictivePerceptionLocked(
        string channel,
        string cue,
        float observation,
        float confidence,
        string inputSource,
        long tick)
    {
        var normalizedChannel = NormalizePredictivePerceptionChannel(channel);
        var normalizedCue = NormalizePredictivePerceptionCue(cue);
        var normalizedSource = string.IsNullOrWhiteSpace(inputSource) ? "unknown" : inputSource.Trim();
        var clampedObservation = Clamp01(observation);
        var clampedConfidence = Clamp01(confidence);
        var previous = PredictivePerception;
        var expected = normalizedChannel switch
        {
            "visual" => previous.VisualPrediction,
            "auditory" => previous.AuditoryPrediction,
            "somatosensory" => previous.SomatosensoryPrediction,
            "interoceptive" => previous.InteroceptivePrediction,
            _ => previous.PredictionError
        };
        var cueChanged = !string.Equals(previous.LastCue, normalizedCue, StringComparison.OrdinalIgnoreCase) ||
                         !string.Equals(previous.LastChannel, normalizedChannel, StringComparison.OrdinalIgnoreCase);
        var mismatch = Math.Abs(clampedObservation - expected);
        var novelty = Clamp01((mismatch * 0.72f) + (cueChanged ? 0.28f : 0f));
        var surprise = Clamp01(((mismatch * 0.70f) + (novelty * 0.30f)) * (0.42f + (0.58f * clampedConfidence)));
        var alpha = 0.18f + (0.20f * clampedConfidence);
        var visualPrediction = previous.VisualPrediction;
        var auditoryPrediction = previous.AuditoryPrediction;
        var somatosensoryPrediction = previous.SomatosensoryPrediction;
        var interoceptivePrediction = previous.InteroceptivePrediction;
        switch (normalizedChannel)
        {
            case "visual":
                visualPrediction = Lerp01(visualPrediction, clampedObservation, alpha);
                break;
            case "auditory":
                auditoryPrediction = Lerp01(auditoryPrediction, clampedObservation, alpha);
                break;
            case "somatosensory":
                somatosensoryPrediction = Lerp01(somatosensoryPrediction, clampedObservation, alpha);
                break;
            case "interoceptive":
                interoceptivePrediction = Lerp01(interoceptivePrediction, clampedObservation, alpha);
                break;
        }

        var predictionError = Clamp01((previous.PredictionError * 0.72f) + (surprise * 0.28f));
        var salienceBias = Clamp01((previous.SalienceBias * 0.64f) + (surprise * 0.36f));
        var lcAlert = Clamp01((previous.LocusCoeruleusAlert * 0.62f) + (surprise * 0.38f));
        var hippocampalGate = Clamp01((previous.HippocampalEncodingGate * 0.66f) + (novelty * 0.34f));
        var accConflict = Clamp01((previous.AccConflictSignal * 0.64f) + (mismatch * clampedConfidence * 0.36f));
        var dopamineTeaching = ClampSigned01((previous.DopamineTeachingSignal * 0.70f) + ((clampedObservation - expected) * clampedConfidence * 0.30f));
        var sensoryBias = BuildPredictivePerceptionAttentionBias(normalizedChannel, surprise, previous.SensoryBias);
        var predictiveCircuitEvidence = ResolvePredictivePerceptionCircuitEvidenceLocked(tick, normalizedChannel);

        PredictivePerception = PredictivePerceptionRuntime.Normalize(new PredictivePerceptionRuntime(
            Active: predictiveCircuitEvidence > 0.10f,
            LastChannel: normalizedChannel,
            LastCue: normalizedCue,
            InputSource: normalizedSource,
            VisualPrediction: visualPrediction,
            VisualObservation: normalizedChannel == "visual" ? clampedObservation : previous.VisualObservation,
            AuditoryPrediction: auditoryPrediction,
            AuditoryObservation: normalizedChannel == "auditory" ? clampedObservation : previous.AuditoryObservation,
            SomatosensoryPrediction: somatosensoryPrediction,
            SomatosensoryObservation: normalizedChannel == "somatosensory" ? clampedObservation : previous.SomatosensoryObservation,
            InteroceptivePrediction: interoceptivePrediction,
            InteroceptiveObservation: normalizedChannel == "interoceptive" ? clampedObservation : previous.InteroceptiveObservation,
            PredictionError: ApplyCircuitGate(predictionError, predictiveCircuitEvidence),
            Surprise: ApplyCircuitGate(surprise, predictiveCircuitEvidence),
            Novelty: ApplyCircuitGate(novelty, predictiveCircuitEvidence),
            Confidence: ApplyCircuitGate(clampedConfidence, predictiveCircuitEvidence),
            SalienceBias: ApplyCircuitGate(salienceBias, predictiveCircuitEvidence),
            LocusCoeruleusAlert: ApplyCircuitGate(lcAlert, predictiveCircuitEvidence),
            HippocampalEncodingGate: ApplyCircuitGate(hippocampalGate, predictiveCircuitEvidence),
            AccConflictSignal: ApplyCircuitGate(accConflict, predictiveCircuitEvidence),
            DopamineTeachingSignal: dopamineTeaching,
            SensoryBias: sensoryBias,
            ExpectedChannel: previous.ExpectedChannel,
            ExpectedCue: previous.ExpectedCue,
            ExpectedAction: previous.ExpectedAction,
            ForwardModelConfidence: previous.ForwardModelConfidence,
            CerebellarForwardModel: previous.CerebellarForwardModel,
            HippocampalPatternCompletion: previous.HippocampalPatternCompletion,
            PfcTopDownExpectation: previous.PfcTopDownExpectation,
            SimulationEvidence: previous.SimulationEvidence,
            LastSimulationTick: previous.LastSimulationTick,
            LastUpdatedTick: tick));

        if (surprise >= 0.34f)
        {
            UpsertEpisodicEventLocked(
                tick,
                "predictive_perception",
                $"predictive:{normalizedChannel}:{normalizedCue}:{tick / 300}",
                $"Unexpected {normalizedChannel} cue: {normalizedCue}.",
                objectId: normalizedCue,
                label: normalizedCue,
                goalKey: GoalIntent.Active ? GoalIntent.GoalKey : "Observe",
                actionKey: PlanningWorkspace.SelectedActionKey,
                valence: dopamineTeaching,
                salience: Math.Max(salienceBias, surprise),
                novelty: novelty,
                confidence: clampedConfidence);
            RefreshEpisodicMemorySnapshotLocked(tick);
        }

        return PredictivePerception;
    }

    private void UpdatePredictiveSensorySimulationLocked(long tick)
    {
        var previous = PredictivePerception;
        var bodyFresh = BodyState.LastInputTick >= 0 && tick - BodyState.LastInputTick <= 1200;
        var environmentFresh = EnvironmentalState.LastInputTick >= 0 && tick - EnvironmentalState.LastInputTick <= 1800;
        var outcomeFresh = OutcomeState.LastInputTick >= 0 && tick - OutcomeState.LastInputTick <= 1600;
        var goalKey = GoalIntent.Active ? GoalIntent.GoalKey : PlanningWorkspace.Goal;
        var actionKey = string.IsNullOrWhiteSpace(PlanningWorkspace.SelectedActionKey)
            ? IntentionalActionLoop.ActionKey
            : PlanningWorkspace.SelectedActionKey;
        var rememberedObject = PersistentPercepts.ActiveCategory != "none" && PersistentPercepts.ObjectPermanence > 0.05f;
        var threatMemory = WorldLearningMap.ThreatSources > 0 && WorldLearningMap.MostDangerousKey != "none";
        var foodMemory = WorldLearningMap.FoodSources > 0 && WorldLearningMap.BestFoodKey != "none";
        var shelterMemory = WorldLearningMap.SafePlaces > 0 && WorldLearningMap.BestShelterKey != "none";
        var weaponMemory = WorldLearningMap.WeaponSources > 0 && WorldLearningMap.BestWeaponKey != "none";
        var visualTarget = Clamp01(
            0.12f +
            (AttentionState.Visual * 0.18f) +
            (VisualAttention.FocusConfidence * 0.14f) +
            (PersistentPercepts.ObjectPermanence * 0.22f) +
            (PersistentPercepts.SpatialIntention * 0.18f) +
            (GoalIntent.Active ? 0.08f : 0f) +
            (goalKey is "FindFood" && foodMemory ? 0.20f : 0f) +
            (goalKey is "FindShelter" && shelterMemory ? 0.16f : 0f) +
            (goalKey is "SeekWeapon" && weaponMemory ? 0.14f : 0f) +
            (goalKey is "AvoidThreat" && threatMemory ? 0.16f : 0f));
        var auditoryTarget = Clamp01(
            0.08f +
            (AttentionState.Auditory * 0.18f) +
            (environmentFresh ? EnvironmentalState.PredatorThreat * 0.34f : 0f) +
            (LimbicState.Threat * 0.24f) +
            (EmotionState.Anxiety * 0.10f) +
            (bodyFresh ? Math.Abs(BodyState.ForwardVelocity) * 0.10f : 0f) +
            (bodyFresh ? Math.Abs(BodyState.TurnRateDeg) / 180f * 0.08f : 0f) +
            (LanguageIntent.Active ? 0.12f : 0f));
        var somatosensoryTarget = Clamp01(
            0.10f +
            (AttentionState.Somatosensory * 0.16f) +
            (Cerebellum.TimingPrediction * 0.18f) +
            (bodyFresh ? Math.Abs(BodyState.ForwardVelocity) * 0.14f : 0f) +
            (bodyFresh ? Math.Abs(BodyState.TurnRateDeg) / 180f * 0.12f : 0f) +
            (bodyFresh ? BodyState.ContactLevel * 0.18f : 0f) +
            (bodyFresh ? BodyState.PainLevel * 0.12f : 0f) +
            (GoalIntent.MotorDirective.Contains("move", StringComparison.OrdinalIgnoreCase) ? 0.08f : 0f));
        var pressureNorm = Clamp01(SleepMemory.SleepPressure / Math.Max(0.0001f, SleepMemory.MaxSleepPressure));
        var interoceptiveTarget = Clamp01(
            0.10f +
            (AttentionState.Interoceptive * 0.16f) +
            (InteroceptiveCore.HungerDrive * 0.18f) +
            (InteroceptiveCore.FatigueDrive * 0.14f) +
            (InteroceptiveCore.PainDrive * 0.12f) +
            (pressureNorm * 0.12f) +
            (environmentFresh ? EnvironmentalState.Darkness * 0.08f : 0f) +
            (outcomeFresh ? OutcomeState.AversiveOutcome * 0.10f : 0f));
        var hippocampalCompletion = Clamp01(
            (EpisodicMemory.CA3PatternCompletion * 0.26f) +
            (EpisodicMemory.RecallConfidence * 0.18f) +
            (PersistentPercepts.ObjectPermanence * 0.18f) +
            (WorldLearningMap.Count > 0 ? 0.16f : 0f) +
            (SemanticMemory.SemanticConfidence * 0.12f) +
            (rememberedObject ? 0.10f : 0f));
        var pfcTopDown = Clamp01(
            (GoalIntent.Confidence * 0.24f) +
            (PrefrontalWorkingMemory.Confidence * 0.22f) +
            (IntentionalActionLoop.Confidence * 0.16f) +
            (MotivationArbitration.Confidence * 0.14f) +
            (PlanningWorkspace.SelectedConfidence > 0 ? (float)PlanningWorkspace.SelectedConfidence * 0.14f : 0f) +
            (LanguageIntent.Active ? 0.10f : 0f));
        var cerebellarForward = Clamp01(
            (Cerebellum.TimingPrediction * 0.36f) +
            (Cerebellum.MotorSmoothing * 0.18f) +
            (Cerebellum.DeepNucleiOutput * 0.14f) +
            (bodyFresh ? Math.Abs(BodyState.ForwardVelocity) * 0.14f : 0f) +
            (bodyFresh ? Math.Abs(BodyState.TurnRateDeg) / 180f * 0.12f : 0f) +
            (GoalIntent.Active ? 0.06f : 0f));
        var expected = SelectPredictiveExpectedChannel(visualTarget, auditoryTarget, somatosensoryTarget, interoceptiveTarget);
        var expectedCue = ResolvePredictiveExpectedCueLocked(goalKey, expected.Channel, rememberedObject, threatMemory, foodMemory, shelterMemory, weaponMemory);
        var channelEvidence = ResolvePredictivePerceptionCircuitEvidenceLocked(tick, expected.Channel);
        var circuitEvidence = Clamp01(
            (channelEvidence * 0.32f) +
            (ResolvePrefrontalCircuitEvidenceLocked(tick) * 0.18f) +
            (ResolveSemanticCircuitEvidenceLocked(tick) * 0.12f) +
            (ResolveCerebellarCircuitEvidenceLocked(
                tick,
                recentInputSpikes: 0,
                recentOutputSpikes: 0,
                bodyFresh,
                bodyFresh ? Math.Abs(BodyState.ForwardVelocity) : 0f,
                bodyFresh ? Math.Abs(BodyState.TurnRateDeg) / 180f : 0f,
                bodyFresh ? BodyState.ContactLevel : 0f) * 0.12f) +
            (hippocampalCompletion * 0.14f) +
            (ResolveGlobalCircuitFallback() * 0.12f));
        var forwardConfidence = ApplyCircuitGate(
            Clamp01((expected.Value * 0.26f) + (hippocampalCompletion * 0.22f) + (pfcTopDown * 0.22f) + (cerebellarForward * 0.14f) + (circuitEvidence * 0.16f)),
            circuitEvidence);
        var alpha = 0.06f + (forwardConfidence * 0.12f);
        var sensoryBias = BuildPredictiveSimulationAttentionBias(expected.Channel, forwardConfidence, previous.SensoryBias);
        var predictionError = Clamp01(previous.PredictionError * 0.92f);
        var surprise = Clamp01(previous.Surprise * 0.90f);
        var novelty = Clamp01(previous.Novelty * 0.93f);
        var accConflict = Clamp01((previous.AccConflictSignal * 0.84f) + (SelfMonitoringLoop.MonitorState is "stalled" or "unsafe" ? 0.12f : 0f));
        var lcAlert = Clamp01((previous.LocusCoeruleusAlert * 0.82f) + (expected.Channel == "auditory" && auditoryTarget > 0.45f ? 0.10f : 0f));

        PredictivePerception = PredictivePerceptionRuntime.Normalize(previous with
        {
            Active = circuitEvidence > 0.10f && forwardConfidence > 0.08f,
            ExpectedChannel = expected.Channel,
            ExpectedCue = expectedCue,
            ExpectedAction = string.IsNullOrWhiteSpace(actionKey) ? "observe" : actionKey,
            VisualPrediction = Lerp01(previous.VisualPrediction, visualTarget, alpha),
            AuditoryPrediction = Lerp01(previous.AuditoryPrediction, auditoryTarget, alpha),
            SomatosensoryPrediction = Lerp01(previous.SomatosensoryPrediction, somatosensoryTarget, alpha),
            InteroceptivePrediction = Lerp01(previous.InteroceptivePrediction, interoceptiveTarget, alpha),
            PredictionError = ApplyCircuitGate(predictionError, circuitEvidence),
            Surprise = ApplyCircuitGate(surprise, circuitEvidence),
            Novelty = ApplyCircuitGate(novelty, circuitEvidence),
            Confidence = Math.Max(previous.Confidence * 0.88f, forwardConfidence),
            SalienceBias = Clamp01((previous.SalienceBias * 0.76f) + (expected.Value * 0.14f) + (pfcTopDown * 0.10f)),
            LocusCoeruleusAlert = ApplyCircuitGate(lcAlert, circuitEvidence),
            HippocampalEncodingGate = ApplyCircuitGate(Clamp01((previous.HippocampalEncodingGate * 0.76f) + (hippocampalCompletion * 0.24f)), circuitEvidence),
            AccConflictSignal = ApplyCircuitGate(accConflict, circuitEvidence),
            SensoryBias = sensoryBias,
            ForwardModelConfidence = forwardConfidence,
            CerebellarForwardModel = ApplyCircuitGate(cerebellarForward, circuitEvidence),
            HippocampalPatternCompletion = ApplyCircuitGate(hippocampalCompletion, circuitEvidence),
            PfcTopDownExpectation = ApplyCircuitGate(pfcTopDown, circuitEvidence),
            LastSimulationTick = tick,
            SimulationEvidence = $"expect={expected.Channel}:{expectedCue}, goal={goalKey}, action={actionKey}, PFC={pfcTopDown:0.00}, CA3={hippocampalCompletion:0.00}, cerebellum={cerebellarForward:0.00}, circuit={circuitEvidence:0.00}",
            LastUpdatedTick = tick
        });
    }

    private static string NormalizePredictivePerceptionChannel(string channel)
    {
        var value = string.IsNullOrWhiteSpace(channel) ? "visual" : channel.Trim().ToLowerInvariant();
        return value switch
        {
            "vision" or "object" => "visual",
            "audio" or "language" => "auditory",
            "touch" or "collision" or "body" or "proprioception" => "somatosensory",
            "hunger" or "fatigue" or "pain" or "shelter" or "internal" => "interoceptive",
            _ => value
        };
    }

    private static string NormalizePredictivePerceptionCue(string cue)
    {
        if (string.IsNullOrWhiteSpace(cue))
        {
            return "unknown";
        }

        var normalized = cue.Trim();
        return normalized.Length <= 96 ? normalized : normalized[..96];
    }

    private static float Lerp01(float from, float to, float alpha)
        => Clamp01(from + ((to - from) * Math.Clamp(alpha, 0f, 1f)));

    private static AttentionVector BuildPredictivePerceptionAttentionBias(
        string channel,
        float surprise,
        AttentionVector previous)
    {
        var visual = previous.Visual * 0.72f;
        var auditory = previous.Auditory * 0.72f;
        var somatosensory = previous.Somatosensory * 0.72f;
        var interoceptive = previous.Interoceptive * 0.72f;
        var boost = 0.16f + (0.72f * Clamp01(surprise));
        switch (channel)
        {
            case "visual":
                visual += boost;
                break;
            case "auditory":
                auditory += boost;
                break;
            case "somatosensory":
                somatosensory += boost;
                break;
            case "interoceptive":
                interoceptive += boost;
                break;
            default:
                visual += boost * 0.25f;
                auditory += boost * 0.25f;
                somatosensory += boost * 0.25f;
                interoceptive += boost * 0.25f;
                break;
        }

        var total = Math.Max(0.0001f, visual + auditory + somatosensory + interoceptive);
        return new AttentionVector(visual / total, auditory / total, somatosensory / total, interoceptive / total);
    }

    private static AttentionVector BuildPredictiveSimulationAttentionBias(
        string channel,
        float confidence,
        AttentionVector previous)
    {
        var visual = previous.Visual * 0.86f;
        var auditory = previous.Auditory * 0.86f;
        var somatosensory = previous.Somatosensory * 0.86f;
        var interoceptive = previous.Interoceptive * 0.86f;
        var boost = 0.06f + (0.34f * Clamp01(confidence));
        switch (channel)
        {
            case "visual":
                visual += boost;
                break;
            case "auditory":
                auditory += boost;
                break;
            case "somatosensory":
                somatosensory += boost;
                break;
            case "interoceptive":
                interoceptive += boost;
                break;
        }

        var total = Math.Max(0.0001f, visual + auditory + somatosensory + interoceptive);
        return new AttentionVector(visual / total, auditory / total, somatosensory / total, interoceptive / total);
    }

    private static (string Channel, float Value) SelectPredictiveExpectedChannel(
        float visual,
        float auditory,
        float somatosensory,
        float interoceptive)
    {
        (string Channel, float Value) best = ("visual", visual);
        if (auditory > best.Value)
        {
            best = ("auditory", auditory);
        }

        if (somatosensory > best.Value)
        {
            best = ("somatosensory", somatosensory);
        }

        if (interoceptive > best.Value)
        {
            best = ("interoceptive", interoceptive);
        }

        return best;
    }

    private string ResolvePredictiveExpectedCueLocked(
        string goalKey,
        string channel,
        bool rememberedObject,
        bool threatMemory,
        bool foodMemory,
        bool shelterMemory,
        bool weaponMemory)
    {
        if (channel == "visual" && rememberedObject)
        {
            return $"object:{PersistentPercepts.ActiveLabel}";
        }

        if (goalKey == "FindFood" && foodMemory)
        {
            return $"object:{WorldLearningMap.BestFoodKey}";
        }

        if (goalKey == "FindShelter" && shelterMemory)
        {
            return $"place:{WorldLearningMap.BestShelterKey}";
        }

        if (goalKey == "SeekWeapon" && weaponMemory)
        {
            return $"object:{WorldLearningMap.BestWeaponKey}";
        }

        if (goalKey == "AvoidThreat" && threatMemory)
        {
            return $"threat:{WorldLearningMap.MostDangerousKey}";
        }

        return channel switch
        {
            "auditory" when LimbicState.Threat > 0.35f || EnvironmentalState.PredatorThreat > 0.35f => "threat:sound",
            "auditory" when Math.Abs(BodyState.ForwardVelocity) > 0.03f => "self:footstep",
            "somatosensory" when BodyState.ContactLevel > 0.10f => "body:contact",
            "somatosensory" when Math.Abs(BodyState.ForwardVelocity) > 0.03f => "body:movement",
            "interoceptive" when InteroceptiveCore.HungerDrive > 0.35f => "need:hunger",
            "interoceptive" when InteroceptiveCore.FatigueDrive > 0.35f => "need:fatigue",
            "interoceptive" when InteroceptiveCore.PainDrive > 0.15f => "need:pain",
            _ => $"expect:{channel}"
        };
    }

