    public ObjectMemoryTrace RegisterObjectObservation(
        string objectId,
        string label,
        string hemisphere,
        float salience,
        float confidence,
        float intensity,
        int deliveredSpikes)
    {
        lock (_gate)
        {
            var key = string.IsNullOrWhiteSpace(objectId) ? "object_unknown" : objectId.Trim();
            var sanitizedLabel = string.IsNullOrWhiteSpace(label) ? key : label.Trim();
            if (sanitizedLabel.Length > 96)
            {
                sanitizedLabel = sanitizedLabel[..96];
            }

            var hemi = string.IsNullOrWhiteSpace(hemisphere) ? "M" : hemisphere.Trim().ToUpperInvariant();
            if (hemi is not ("L" or "R" or "M"))
            {
                hemi = "M";
            }

            var clampedSalience = Math.Clamp(salience, 0f, 1f);
            var clampedConfidence = Math.Clamp(confidence, 0f, 1f);
            var clampedIntensity = Math.Clamp(intensity, 0f, 5f);
            var baseGain = 0.05f + (clampedSalience * 0.16f) + (clampedConfidence * 0.10f);
            var spikeGain = Math.Clamp(deliveredSpikes / 96f, 0f, 1.4f) * 0.05f;
            var familiarityGain = Math.Clamp(baseGain + spikeGain, 0.02f, 0.36f);

            if (!_objectMemory.TryGetValue(key, out var existing))
            {
                if (_objectMemory.Count >= MaxObjectMemoryEntries)
                {
                    var evictKey = _objectMemory
                        .OrderBy(p => p.Value.Familiarity)
                        .ThenBy(p => p.Value.LastSeenTick)
                        .Select(p => p.Key)
                        .FirstOrDefault();
                    if (!string.IsNullOrWhiteSpace(evictKey))
                    {
                        _objectMemory.Remove(evictKey);
                    }
                }

                existing = new ObjectMemoryTrace(
                    ObjectId: key,
                    Label: sanitizedLabel,
                    DominantHemisphere: hemi,
                    Familiarity: 0f,
                    SalienceEma: clampedSalience,
                    ConfidenceEma: clampedConfidence,
                    IntensityEma: clampedIntensity,
                    SeenCount: 0,
                    LeftEvidence: 0,
                    RightEvidence: 0,
                    MidEvidence: 0,
                    LastSeenTick: 0,
                    LastSeenSimulationMs: 0.0);
            }

            var familiarity = Math.Clamp(existing.Familiarity + (familiarityGain * (1f - existing.Familiarity)), 0f, 1f);
            const float emaAlpha = 0.28f;
            var salienceEma = ((1f - emaAlpha) * existing.SalienceEma) + (emaAlpha * clampedSalience);
            var confidenceEma = ((1f - emaAlpha) * existing.ConfidenceEma) + (emaAlpha * clampedConfidence);
            var intensityEma = ((1f - emaAlpha) * existing.IntensityEma) + (emaAlpha * clampedIntensity);

            var left = existing.LeftEvidence;
            var right = existing.RightEvidence;
            var mid = existing.MidEvidence;
            switch (hemi)
            {
                case "L":
                    left++;
                    break;
                case "R":
                    right++;
                    break;
                default:
                    mid++;
                    break;
            }

            var dominantHemisphere = "M";
            if (left > right && left >= mid)
            {
                dominantHemisphere = "L";
            }
            else if (right > left && right >= mid)
            {
                dominantHemisphere = "R";
            }

            var updated = existing with
            {
                Label = sanitizedLabel,
                DominantHemisphere = dominantHemisphere,
                Familiarity = familiarity,
                SalienceEma = Math.Clamp(salienceEma, 0f, 1f),
                ConfidenceEma = Math.Clamp(confidenceEma, 0f, 1f),
                IntensityEma = Math.Clamp(intensityEma, 0f, 5f),
                SeenCount = existing.SeenCount + 1,
                LeftEvidence = left,
                RightEvidence = right,
                MidEvidence = mid,
                LastSeenTick = Tick,
                LastSeenSimulationMs = SimulationClockMs
            };
            _objectMemory[key] = updated;
            UpsertWorldLearningMapFromObjectLocked(updated, Tick, replayReinforcement: false);
            UpsertEpisodicEventLocked(
                Tick,
                "object",
                $"object:{key}:{Tick / 180}",
                $"I saw {sanitizedLabel}.",
                objectId: key,
                label: sanitizedLabel,
                goalKey: GoalIntent.Active ? GoalIntent.GoalKey : "Observe",
                actionKey: string.IsNullOrWhiteSpace(PlanningWorkspace.SelectedActionKey) ? "perceive.object" : PlanningWorkspace.SelectedActionKey,
                valence: ClassifyWorldLearningCategory(sanitizedLabel) == "threat" ? -0.35f : 0.12f,
                salience: clampedSalience,
                novelty: 1.0f - existing.Familiarity,
                confidence: clampedConfidence);
            RefreshWorldLearningMapSnapshotLocked(Tick);
            RefreshPersistentPerceptsLocked(Tick);
            RefreshEpisodicMemorySnapshotLocked(Tick);
            UpdateSemanticMemoryLocked(Tick);
            return updated;
        }
    }

