    public void RecordDispatchedSpikes(
        long tick,
        double timestampMs,
        string sourceHemisphere,
        string targetHemisphere,
        string targetInstanceKey,
        IReadOnlyList<SpikeMessage> spikes,
        int deliveredCount)
    {
        if (deliveredCount <= 0 || spikes.Count == 0)
        {
            return;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var limit = Math.Min(deliveredCount, spikes.Count);
        if (limit <= 0)
        {
            return;
        }

        var hasConcreteNeuronIds = false;
        for (var i = 0; i < limit; i++)
        {
            var spike = spikes[i];
            if (spike is null)
            {
                continue;
            }

            var sourceNeuronId = NormalizeNeuronIdForHemisphere(spike.SourceNeuronId, sourceHemisphere);
            var targetNeuronId = NormalizeNeuronIdForHemisphere(spike.TargetNeuronId, targetHemisphere);
            if (string.IsNullOrWhiteSpace(sourceNeuronId) || string.IsNullOrWhiteSpace(targetNeuronId))
            {
                continue;
            }

            if (!sourceNeuronId.Contains("population-", StringComparison.OrdinalIgnoreCase) &&
                !targetNeuronId.Contains("population-", StringComparison.OrdinalIgnoreCase))
            {
                hasConcreteNeuronIds = true;
                break;
            }
        }

        var traces = new List<DispatchedSpikeTrace>(Math.Min(limit, hasConcreteNeuronIds ? limit : MaxPopulationDispatchTracePerBatch));
        var populationTracesRecorded = 0;
        for (var i = 0; i < limit; i++)
        {
            var spike = spikes[i];
            if (spike is null)
            {
                continue;
            }

            var sourceNeuronId = NormalizeNeuronIdForHemisphere(spike.SourceNeuronId, sourceHemisphere);
            var targetNeuronId = NormalizeNeuronIdForHemisphere(spike.TargetNeuronId, targetHemisphere);
            if (string.IsNullOrWhiteSpace(sourceNeuronId) || string.IsNullOrWhiteSpace(targetNeuronId))
            {
                continue;
            }

            var isPopulationTrace =
                sourceNeuronId.Contains("population-", StringComparison.OrdinalIgnoreCase) ||
                targetNeuronId.Contains("population-", StringComparison.OrdinalIgnoreCase);
            if (isPopulationTrace && hasConcreteNeuronIds)
            {
                continue;
            }

            if (isPopulationTrace && populationTracesRecorded >= MaxPopulationDispatchTracePerBatch)
            {
                continue;
            }

            if (isPopulationTrace)
            {
                populationTracesRecorded++;
            }

            traces.Add(new DispatchedSpikeTrace(
                tick,
                timestampMs,
                nowMs,
                spike.SourceStructure,
                sourceHemisphere,
                sourceNeuronId,
                spike.TargetStructure,
                targetHemisphere,
                targetNeuronId,
                spike.Neurotransmitter,
                targetInstanceKey));
        }

        if (traces.Count == 0)
        {
            return;
        }

        lock (_gate)
        {
            for (var i = 0; i < traces.Count; i++)
            {
                _dispatchSpikeTrace.Enqueue(traces[i]);
                RecordDispatchTraceStatsLocked(traces[i]);
            }

            while (_dispatchSpikeTrace.Count > MaxDispatchTraceEntries)
            {
                _dispatchSpikeTrace.Dequeue();
            }

            InvalidateCompositeSnapshotCachesLocked();
        }
    }

    public IReadOnlyList<DispatchedSpikeTrace> GetDispatchedSpikesSince(long wallClockUnixMsExclusive, int maxEntries = MaxDispatchTraceEntries)
    {
        lock (_gate)
        {
            return GetDispatchTraceTailSince(_dispatchSpikeTrace, wallClockUnixMsExclusive, maxEntries);
        }
    }

    public IReadOnlyList<DispatchedSpikeTrace> GetRecentDispatchedSpikes(int limit)
    {
        lock (_gate)
        {
            return GetDispatchTraceTailSince(_dispatchSpikeTrace, 0, limit);
        }
    }

    public IReadOnlyList<DispatchedSpikeTrace> GetRecentDispatchedSpikesForTick(long tick, int limit)
    {
        lock (_gate)
        {
            return GetDispatchTraceTailForTick(_dispatchSpikeTrace, tick, limit);
        }
    }

    private static IReadOnlyList<RuntimeLogEntry> GetRuntimeLogTailSince(
        Queue<RuntimeLogEntry> queue,
        long wallClockUnixMsExclusive,
        int maxEntries)
    {
        if (maxEntries <= 0 || queue.Count == 0)
        {
            return [];
        }

        var limit = Math.Min(maxEntries, queue.Count);
        var skip = queue.Count - limit;
        var result = new List<RuntimeLogEntry>(limit);
        var index = 0;
        foreach (var entry in queue)
        {
            if (index++ < skip)
            {
                continue;
            }

            if (wallClockUnixMsExclusive <= 0 || entry.WallClockUnixMs > wallClockUnixMsExclusive)
            {
                result.Add(entry);
            }
        }

        return result;
    }

    private static IReadOnlyList<DispatchedSpikeTrace> GetDispatchTraceTailSince(
        Queue<DispatchedSpikeTrace> queue,
        long wallClockUnixMsExclusive,
        int maxEntries)
    {
        if (maxEntries <= 0 || queue.Count == 0)
        {
            return [];
        }

        var limit = Math.Min(maxEntries, queue.Count);
        var skip = queue.Count - limit;
        var result = new List<DispatchedSpikeTrace>(limit);
        var index = 0;
        foreach (var trace in queue)
        {
            if (index++ < skip)
            {
                continue;
            }

            if (wallClockUnixMsExclusive <= 0 || trace.WallClockUnixMs > wallClockUnixMsExclusive)
            {
                result.Add(trace);
            }
        }

        return result;
    }

    private static IReadOnlyList<DispatchedSpikeTrace> GetDispatchTraceTailForTick(
        Queue<DispatchedSpikeTrace> queue,
        long tick,
        int maxEntries)
    {
        if (maxEntries <= 0 || queue.Count == 0)
        {
            return [];
        }

        var limit = Math.Min(maxEntries, queue.Count);
        var skip = queue.Count - limit;
        var result = new List<DispatchedSpikeTrace>(Math.Min(limit, 256));
        var index = 0;
        foreach (var trace in queue)
        {
            if (index++ < skip)
            {
                continue;
            }

            if (trace.Tick == tick)
            {
                result.Add(trace);
            }
        }

        return result;
    }

    private void AdvancePhase(BrainRhythm rhythm, double frequencyHz)
    {
        var phaseIncrement = 2.0 * Math.PI * frequencyHz * (TickDurationMs / 1000.0);
        var next = OscillationPhases[rhythm] + phaseIncrement;
        OscillationPhases[rhythm] = next % (2.0 * Math.PI);
    }

    private object BuildConsolidationTelemetrySnapshot()
    {
        lock (_gate)
        {
            return GetCachedConsolidationTelemetrySnapshotLocked();
        }
    }

    private void RecordDispatchTraceStatsLocked(DispatchedSpikeTrace trace)
    {
        _dispatchLifetimeOut[trace.SourceStructure] = _dispatchLifetimeOut.TryGetValue(trace.SourceStructure, out var outCount)
            ? outCount + 1
            : 1;
        _dispatchLifetimeIn[trace.TargetStructure] = _dispatchLifetimeIn.TryGetValue(trace.TargetStructure, out var inCount)
            ? inCount + 1
            : 1;
        UpdateLastTick(_dispatchLastOutTick, trace.SourceStructure, trace.Tick);
        UpdateLastTick(_dispatchLastInTick, trace.TargetStructure, trace.Tick);
    }

    private void RebuildDispatchTraceStatsLocked()
    {
        _dispatchLifetimeOut.Clear();
        _dispatchLifetimeIn.Clear();
        _dispatchLastOutTick.Clear();
        _dispatchLastInTick.Clear();
        foreach (var trace in _dispatchSpikeTrace)
        {
            RecordDispatchTraceStatsLocked(trace);
        }

        InvalidateCompositeSnapshotCachesLocked();
    }

    private object GetCachedConsolidationTelemetrySnapshotLocked()
    {
        if (_cachedConsolidationTelemetrySnapshot is not null && _cachedConsolidationTelemetryTick == Tick)
        {
            return _cachedConsolidationTelemetrySnapshot;
        }

        _cachedConsolidationTelemetrySnapshot = BuildConsolidationTelemetrySnapshotLocked();
        _cachedConsolidationTelemetryTick = Tick;
        return _cachedConsolidationTelemetrySnapshot;
    }

    private object BuildConsolidationTelemetrySnapshotLocked()
    {
        var protectedEngrams = 0;
        var replayReadyEngrams = 0;
        var hippocampalEngrams = 0;
        var corticalEngrams = 0;
        var cerebellarEngrams = 0;
        var motorSuppressedEngrams = 0;
        var replaySupportedEngrams = 0;
        var recentReplayWindowStart = Math.Max(0, Tick - 1200);
        var recentlyReplayedEngrams = 0;
        var totalReplayCount = 0;
        var salienceSum = 0.0;

        foreach (var engram in _engramBank)
        {
            var protectedBySalience = engram.Salience >= ConsolidationControl.ProtectedSalienceThreshold;
            var suppressedForReplay = IsSleepReplaySuppressedEngram(engram);
            if (protectedBySalience)
            {
                protectedEngrams++;
            }

            if (!suppressedForReplay && engram.Salience >= SleepMemory.SignificantSalienceThreshold)
            {
                replayReadyEngrams++;
            }

            if (suppressedForReplay)
            {
                motorSuppressedEngrams++;
            }

            if (IsHippocampalCircuit(engram.SourceStructure, engram.TargetStructure))
            {
                hippocampalEngrams++;
            }

            if (IsCorticalCircuit(engram.SourceStructure, engram.TargetStructure))
            {
                corticalEngrams++;
            }

            if (IsCerebellarStructure(engram.SourceStructure) || IsCerebellarStructure(engram.TargetStructure))
            {
                cerebellarEngrams++;
            }

            if (engram.ReplayCount > 0)
            {
                replaySupportedEngrams++;
                totalReplayCount += engram.ReplayCount;
            }

            if (engram.LastReplayTick >= recentReplayWindowStart)
            {
                recentlyReplayedEngrams++;
            }

            salienceSum += engram.Salience;
        }

        var activeSchemas = _schemaBank.Count(schema =>
            schema.Strength >= 1.0f ||
            schema.ReplaySupportCount > 0 ||
            schema.MeanSalience >= ConsolidationControl.ProtectedSalienceThreshold);
        var replaySupportedSchemas = _schemaBank.Count(schema => schema.ReplaySupportCount > 0);
        var generated = Math.Max(0, TransportStats.EngramReplayGenerated);
        var delivered = Math.Max(0, TransportStats.EngramReplayDelivered);
        var deliveryRatio = generated <= 0 ? 0.0 : delivered / (double)Math.Max(1, generated);

        return new
        {
            Enabled = ConsolidationControl.Enabled,
            Stage = SleepMemory.IsSleeping
                ? (SleepMemory.SleepTicks < (SleepMemory.MinSleepTicks / 2)
                    ? SleepReplayStage.EarlyHippocampal.ToString()
                    : SleepReplayStage.LateCorticalConsolidation.ToString())
                : "AwakeEncoding",
            IsSleeping = SleepMemory.IsSleeping,
            EngramCount = _engramBank.Count,
            ProtectedEngrams = protectedEngrams,
            ReplayReadyEngrams = replayReadyEngrams,
            ReplaySupportedEngrams = replaySupportedEngrams,
            RecentlyReplayedEngrams = recentlyReplayedEngrams,
            MotorSuppressedEngrams = motorSuppressedEngrams,
            HippocampalEngrams = hippocampalEngrams,
            CorticalEngrams = corticalEngrams,
            CerebellarEngrams = cerebellarEngrams,
            MeanSalience = _engramBank.Count == 0 ? 0.0 : salienceSum / _engramBank.Count,
            TotalReplayCount = totalReplayCount,
            SchemaCount = _schemaBank.Count,
            ActiveSchemas = activeSchemas,
            ReplaySupportedSchemas = replaySupportedSchemas,
            DeliveryRatio = deliveryRatio,
            ReplayGenerated = generated,
            ReplayDelivered = delivered,
            ConsolidationGain = ConsolidationControl.SchemaConsolidationGain,
            AntiForgetting = ConsolidationControl.AntiForgettingHomeostasis,
            EngramDecayPerTick = ConsolidationControl.EngramDecayPerTick,
            SchemaDecayPerTick = ConsolidationControl.SchemaDecayPerTick
        };
    }

    private object BuildBrainBehaviorSnapshot()
    {
        lock (_gate)
        {
            var sleep = SleepMemory;
            var limbic = LimbicState;
            var environment = EnvironmentalState;
            var outcome = OutcomeState;
            var body = BodyState;
            var actionCompletion = ActionCompletionFeedback;
            var language = LanguageIntent;
            var workspace = CognitiveLanguageWorkspace;
            var innerSpeech = InnerSpeechLoop;
            var prefrontal = PrefrontalWorkingMemory;
            var intentionalAction = IntentionalActionLoop;
            var selfMonitoring = SelfMonitoringLoop;
            var motivation = MotivationArbitration;
            var episodic = EpisodicMemory;
            var unifiedEventMemory = UnifiedEventMemory;
            var semantic = SemanticMemory;
            var dopamineLearning = DopamineLearning;
            var consciousness = ConsciousnessRhythm;
            var globalWorkspace = GlobalWorkspace;
            var autobiographicalSelf = AutobiographicalSelf;
            var selfModel = NarrativeSelfModel;
            var goal = GoalIntent;
            var emotion = EmotionState;
            var pressureNorm = Clamp01(sleep.SleepPressure / Math.Max(0.0001f, sleep.MaxSleepPressure));
            var cerebellarWindowStart = Math.Max(0, Tick - 1200);
            var cerebellarInputSpikes = 0;
            var cerebellarOutputSpikes = 0;
            var cerebellarLastSpikeTick = long.MinValue;
            foreach (var trace in _dispatchSpikeTrace)
            {
                if (!IsCerebellarAuditStructure(trace.SourceStructure) &&
                    !IsCerebellarAuditStructure(trace.TargetStructure))
                {
                    continue;
                }

                cerebellarLastSpikeTick = Math.Max(cerebellarLastSpikeTick, trace.Tick);
                if (trace.Tick < cerebellarWindowStart)
                {
                    continue;
                }

                if (IsCerebellarAuditStructure(trace.TargetStructure))
                {
                    cerebellarInputSpikes++;
                }

                if (IsCerebellarAuditStructure(trace.SourceStructure))
                {
                    cerebellarOutputSpikes++;
                }
            }

            var motorInhibition = sleep.IsSleeping
                ? 1.0f
                : sleep.WakeInertiaTicksRemaining > 0
                    ? Clamp01(sleep.WakeInertiaTicksRemaining / (float)Math.Max(1, sleep.MinWakeTicks))
                    : 0.0f;
            var anxiety = Math.Max(environment.Anxiety, limbic.AversiveDrive);
            var fightIntent = Clamp01((limbic.Threat * 0.55f) + (limbic.ExpectedReward * 0.25f) - (pressureNorm * 0.20f));
            var flightIntent = Clamp01((limbic.Threat * 0.65f) + (anxiety * 0.45f) - (limbic.ExpectedReward * 0.20f));
            var shelterSafety = Clamp01(Math.Max(environment.InShelter, environment.ShelterSafety));
            var exposure = 1.0f - shelterSafety;
            var predatorThreat = Clamp01(environment.PredatorThreat * exposure);
            var shelterIntent = Clamp01((environment.ShelterNeed * 0.55f) + (environment.Darkness * 0.30f * exposure) + (pressureNorm * 0.45f) + (anxiety * 0.15f) + (predatorThreat * 0.28f));

            return new
            {
                Tick,
                Sleep = new
                {
                    sleep.IsSleeping,
                    sleep.SleepPressure,
                    sleep.MaxSleepPressure,
                    PressureNormalized = pressureNorm,
                    sleep.SleepPressureEnterThreshold,
                    sleep.SleepPressureExitThreshold,
                    sleep.SleepTicks,
                    sleep.WakeTicks,
                    sleep.WakeInertiaTicksRemaining,
                    MotorInhibition = motorInhibition,
                    TiredDrive = Math.Max(pressureNorm, limbic.TiredDrive)
                },
                Drives = new
                {
                    limbic.Stage,
                    limbic.Salience,
                    limbic.Threat,
                    HungerThirstDrive = limbic.InteroceptiveDrive,
                    limbic.TiredDrive,
                    limbic.AversiveDrive,
                    limbic.ExpectedReward,
                    limbic.ObservedReward,
                    limbic.Valence,
                    EnvironmentAnxiety = environment.Anxiety,
                    environment.Darkness,
                    environment.ShelterNeed,
                    environment.Hunger,
                    environment.PredatorThreat,
                    environment.InShelter,
                    environment.Health,
                    environment.ShelterSafety,
                    OutcomeAppetitiveRelief = outcome.AppetitiveRelief,
                    OutcomeAversive = outcome.AversiveOutcome,
                    Exposure = exposure,
                    FightIntent = fightIntent,
                    FlightIntent = flightIntent,
                    ShelterIntent = shelterIntent
                },
                Body = new
                {
                    body.ForwardVelocity,
                    body.TurnRateDeg,
                    body.ContactLevel,
                    body.LeftMotorDrive,
                    body.RightMotorDrive,
                    body.MotorAsymmetry,
                    body.LastInputTick,
                    Schema = BodySchema,
                    InteroceptiveCore
                },
                Language = new
                {
                    language.Active,
