        var pag = (float)diagnostics.Average(d => d.PagDefensiveCommand);
        var raphe = (float)diagnostics.Average(d => d.RaphePainModulation);
        var medulla = (float)diagnostics.Average(d => d.MedullaryAutonomicSupport);
