    private static List<SpikeMessage> BuildLanguageStimulusSpikesForTarget(
        long tick,
        double timestampMs,
        LanguageStimulusTarget target,
        string hemisphere,
        string mode,
        IReadOnlyList<string> tokens,
        float intensity,
        int burstPerToken,
        NeuromodState neuromod)
    {
        var spikes = new List<SpikeMessage>(tokens.Count * burstPerToken);
        var modeGain = ComputeLanguageModeNeuromodGain(mode, neuromod);
        for (var tokenIndex = 0; tokenIndex < tokens.Count; tokenIndex++)
        {
            var token = tokens[tokenIndex];
            var tokenHash = Math.Abs(token.GetHashCode(StringComparison.Ordinal));
            for (var i = 0; i < burstPerToken; i++)
            {
                var channel = (tokenHash + (i * 17) + (tokenIndex * 7)) % 96;
                var syllableHint = (token.Length + i) % 8;
                var vesicle = Math.Clamp((0.52f + (token.Length * 0.03f) + (syllableHint * 0.015f)) * intensity * target.Gain * modeGain, 0.05f, 6.0f);
                var reuptake = ResolveLanguageReuptakeRate(mode, channel);
                var spikeType = ResolveLanguageSpikeType(mode, token, i);

                spikes.Add(new SpikeMessage
                {
                    MessageId = Guid.NewGuid(),
                    TimestampMs = timestampMs,
                    SourceStructure = target.SourceStructure,
                    TargetStructure = target.TargetStructure,
                    SourceNeuronId = $"{hemisphere}:lang_{mode}_{tick}_{tokenIndex}_{i}",
                    TargetNeuronId = BuildLanguageTargetNeuronId(hemisphere, target.TargetNeuronPrefix, mode, token, tokenIndex, channel),
                    SynapseId = Guid.NewGuid(),
                    Neurotransmitter = NTEnum.GLUTAMATE,
                    VesicleQuanta = vesicle,
                    ReuptakeRate = reuptake,
                    SpikeType = spikeType,
                    IsFeedback = false,
                    ModulationContext = NeuromodState.Clamp(neuromod)
                });
            }
        }

        return spikes;
    }

    private static float ComputeLanguageModeNeuromodGain(string mode, NeuromodState neuromod)
    {
        var m = string.IsNullOrWhiteSpace(mode) ? "repetition" : mode.Trim().ToLowerInvariant();
        var gain = m switch
        {
            "comprehension" => 0.85f + (0.35f * neuromod.AcetylcholineLevel) + (0.15f * neuromod.NorepinephrineLevel),
            "production" => 0.88f + (0.28f * neuromod.DopamineLevel) + (0.14f * neuromod.NorepinephrineLevel),
            "prosody" => 0.86f + (0.24f * neuromod.SerotoninLevel) + (0.18f * neuromod.NorepinephrineLevel) + (0.12f * neuromod.DopamineLevel),
            "emergent" => 0.84f + (0.26f * neuromod.DopamineLevel) + (0.20f * neuromod.AcetylcholineLevel) + (0.16f * neuromod.NorepinephrineLevel),
            "english" => 0.92f + (0.32f * neuromod.AcetylcholineLevel) + (0.12f * neuromod.NorepinephrineLevel) + (0.08f * neuromod.DopamineLevel),
            _ => 0.90f + (0.20f * neuromod.AcetylcholineLevel) + (0.12f * neuromod.DopamineLevel)
        };
        return Math.Clamp(gain, 0.55f, 1.75f);
    }

    private static SpikeTypeEnum ResolveLanguageSpikeType(string mode, string token, int burstIndex)
    {
        if (mode.Equals("prosody", StringComparison.OrdinalIgnoreCase))
        {
            return burstIndex % 3 == 0 ? SpikeTypeEnum.GRADED : SpikeTypeEnum.ACTION_POTENTIAL;
        }

        if (mode.Equals("english", StringComparison.OrdinalIgnoreCase))
        {
            return burstIndex % 4 == 0 || token.Length >= 7
                ? SpikeTypeEnum.BURST
                : SpikeTypeEnum.ACTION_POTENTIAL;
        }

        return mode.Equals("repetition", StringComparison.OrdinalIgnoreCase) || token.Length >= 8
            ? SpikeTypeEnum.BURST
            : SpikeTypeEnum.ACTION_POTENTIAL;
    }

    private static float ResolveLanguageReuptakeRate(string mode, int channel)
    {
        var baseRate = mode.Equals("prosody", StringComparison.OrdinalIgnoreCase)
            ? 3.2f
            : mode.Equals("english", StringComparison.OrdinalIgnoreCase) ? 2.6f : 2.8f;
        return Math.Clamp(baseRate + (channel * 0.05f), 1.4f, 10.0f);
    }

    private static string BuildLanguageTargetNeuronId(string hemisphere, string prefix, string mode, string token, int tokenIndex, int channel)
    {
        if (!mode.Equals("english", StringComparison.OrdinalIgnoreCase))
        {
            return $"{hemisphere}:{prefix}_tok_{tokenIndex}_cell_{channel}";
        }

        var classKey = EnglishLanguageLexicon.ResolveSemanticClassForTarget(token);
        return $"{hemisphere}:{prefix}_{classKey}_tok_{tokenIndex}_cell_{channel}";
    }

    private static double ComputePercentile(IReadOnlyList<double> values, double quantile)
    {
        if (values.Count == 0)
        {
            return 0.0;
        }

        var q = Math.Clamp(quantile, 0.0, 1.0);
        var position = (values.Count - 1) * q;
        var lower = (int)Math.Floor(position);
        var upper = (int)Math.Ceiling(position);
        if (lower == upper)
        {
            return values[lower];
        }

        var weight = position - lower;
        return (values[lower] * (1.0 - weight)) + (values[upper] * weight);
    }

    private async Task<SpontaneousInjectionStats> InjectSpontaneousSpikesAsync(
        TickSignal tickSignal,
        SimulationState state,
        IReadOnlyList<ServiceInstance> activeServices,
        SemaphoreSlim dispatchSemaphore,
        IReadOnlyDictionary<string, HttpClient> clients,
        IReadOnlyDictionary<string, IStructureSpikeTransport> grpcSpikeTransports,
        bool useHttpSpikeTransportFallback,
        IReadOnlyDictionary<StructureId, List<SynapticConnection>> connectivity,
        IReadOnlyDictionary<StructureId, List<ServiceInstance>> instancesByStructure,
        ConcurrentDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        IDictionary<StructureId, HashSet<string>> spontaneousNeuronIdsByStructure,
        double scale,
        int maxEventsPerTick,
        bool benchmarkMode,
        bool forceFallbackWhenSilent,
        AttentionVector attentionBias,
        VisualAttentionRuntime visualAttention,
        int tickIoTimeoutMs,
        int maxSpikesPerDispatchRequest,
        CancellationToken stoppingToken)
    {
        if (scale <= 0.0 || activeServices.Count == 0 || maxEventsPerTick <= 0)
        {
            return SpontaneousInjectionStats.Empty;
        }

        var tickDurationSeconds = Math.Max(0.0001, tickSignal.TickDurationMs / 1000.0);
        var dispatchQueue = new ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>>(StringComparer.OrdinalIgnoreCase);
        var dispatchQueueMetrics = new DispatchQueueMetrics();
        var previousTransport = state.TransportStats;
        var queuePressure = ComputeTransportQueuePressure(previousTransport);
        var (dispatchQueueMaxBatches, dispatchQueueMaxSpikes) = ComputeDispatchQueueLimits(
            Math.Max(64, activeServices.Count * 4),
            Math.Max(512, activeServices.Count * 24),
            previousTransport.AdaptivePressure,
            queuePressure,
            previousTransport.DispatchQueueDroppedBatches,
            previousTransport.DispatchQueueDroppedSpikes,
            activeServices.Count,
            maxGrowthScale: 2.80);

        var generated = QueueScheduledSpontaneousSpikes(
            tickSignal,
            activeServices,
            clients,
            connectivity,
            instancesByStructure,
            spontaneousNeuronIdsByStructure,
            scale,
            tickDurationSeconds,
            maxEventsPerTick,
            attentionBias,
            visualAttention,
            dispatchQueue,
            dispatchQueueMetrics,
            dispatchQueueMaxBatches,
            dispatchQueueMaxSpikes);

        if (generated == 0 && benchmarkMode && forceFallbackWhenSilent)
        {
            generated += QueueFallbackSpontaneousSpike(
                tickSignal,
                activeServices,
                clients,
                connectivity,
                instancesByStructure,
                spontaneousNeuronIdsByStructure,
                dispatchQueue,
                dispatchQueueMetrics,
                dispatchQueueMaxBatches,
                dispatchQueueMaxSpikes);
        }

        var flush = await FlushQueuedDispatchBatchesAsync(
            tickSignal,
            state,
            dispatchSemaphore,
            dispatchQueue,
            grpcSpikeTransports,
            clients,
                useHttpSpikeTransportFallback,
                activePathways,
                tickIoTimeoutMs,
                maxSpikesPerDispatchRequest,
                onReplayDelivered: null,
                stoppingToken);

        var dispatchErrors = flush.DispatchErrors + dispatchQueueMetrics.DroppedBatches;
        var lastError = flush.LastError;
        if (dispatchQueueMetrics.DroppedBatches > 0)
        {
            lastError ??= $"spontaneous queue saturated: dropped {dispatchQueueMetrics.DroppedBatches} batch(es) / {dispatchQueueMetrics.DroppedSpikes} spike(s)";
        }

        return new SpontaneousInjectionStats(generated, flush.DeliveredSpikes, dispatchErrors, lastError);
    }

    private int QueueScheduledSpontaneousSpikes(
        TickSignal tickSignal,
        IReadOnlyList<ServiceInstance> activeServices,
        IReadOnlyDictionary<string, HttpClient> clients,
        IReadOnlyDictionary<StructureId, List<SynapticConnection>> connectivity,
        IReadOnlyDictionary<StructureId, List<ServiceInstance>> instancesByStructure,
        IDictionary<StructureId, HashSet<string>> spontaneousNeuronIdsByStructure,
        double scale,
        double tickDurationSeconds,
        int maxEventsPerTick,
        AttentionVector attentionBias,
        VisualAttentionRuntime visualAttention,
        ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>> dispatchQueue,
        DispatchQueueMetrics dispatchQueueMetrics,
        int dispatchQueueMaxBatches,
        int dispatchQueueMaxSpikes)
    {
        var generated = 0;
        var remainingEventBudget = maxEventsPerTick;
        var orderedServices = activeServices
            .OrderBy(s => ComputeSpontaneousServiceOrder(s, tickSignal.Tick))
            .ToArray();
        var hasCerebellarSources = orderedServices.Any(s =>
            IsSpontaneousCerebellarStructure(s.StructureId) &&
            HasSpontaneousRoutes(connectivity, s.StructureId));
        var protectedCerebellarBudget = hasCerebellarSources
            ? Math.Clamp(maxEventsPerTick / 6, 2, 12)
            : 0;
        var generatedCerebellar = 0;

        foreach (var sourceInstance in orderedServices)
        {
            if (remainingEventBudget <= 0)
            {
                break;
            }

            var isCerebellarSource = IsSpontaneousCerebellarStructure(sourceInstance.StructureId);
            if (!isCerebellarSource && remainingEventBudget <= protectedCerebellarBudget)
            {
                continue;
            }

            if (!connectivity.TryGetValue(sourceInstance.StructureId, out var routes) || routes.Count == 0)
            {
                continue;
            }

            var profile = GetSpontaneousNoiseProfile(sourceInstance.StructureId);
            var probabilityPerTick = ComputeSpontaneousProbabilityPerTick(
                sourceInstance,
                profile,
                tickDurationSeconds,
                scale,
                attentionBias,
                visualAttention);
            if (NextDouble() >= probabilityPerTick)
            {
                continue;
            }

            var burstCount = NextInt(profile.MinBurstSpikes, profile.MaxBurstSpikes + 1);
            for (var burstIndex = 0; burstIndex < burstCount && remainingEventBudget > 0; burstIndex++)
            {
                var route = routes[NextInt(0, routes.Count)];
                var spike = BuildSpontaneousSpike(tickSignal, sourceInstance, route, profile, burstCount > 1);
                generated++;
                if (isCerebellarSource)
                {
                    generatedCerebellar++;
                }

                remainingEventBudget--;
                QueueSpontaneousSpikeForTargets(
                    tickSignal,
                    sourceInstance,
                    route,
                    spike,
                    clients,
                    instancesByStructure,
                    spontaneousNeuronIdsByStructure,
                    dispatchQueue,
                    dispatchQueueMetrics,
                    dispatchQueueMaxBatches,
                    dispatchQueueMaxSpikes,
                    "Spontaneous");
            }
        }

        if (hasCerebellarSources && generatedCerebellar == 0 && remainingEventBudget > 0)
        {
            generated += QueueFallbackSpontaneousSpike(
                tickSignal,
                orderedServices,
                clients,
                connectivity,
                instancesByStructure,
                spontaneousNeuronIdsByStructure,
                dispatchQueue,
                dispatchQueueMetrics,
                dispatchQueueMaxBatches,
                dispatchQueueMaxSpikes,
                IsCerebellarSpontaneousSource,
                "Cerebellar spontaneous");
        }

        return generated;
    }

    private int QueueFallbackSpontaneousSpike(
        TickSignal tickSignal,
        IReadOnlyList<ServiceInstance> activeServices,
        IReadOnlyDictionary<string, HttpClient> clients,
        IReadOnlyDictionary<StructureId, List<SynapticConnection>> connectivity,
        IReadOnlyDictionary<StructureId, List<ServiceInstance>> instancesByStructure,
        IDictionary<StructureId, HashSet<string>> spontaneousNeuronIdsByStructure,
        ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>> dispatchQueue,
        DispatchQueueMetrics dispatchQueueMetrics,
        int dispatchQueueMaxBatches,
        int dispatchQueueMaxSpikes,
        Func<ServiceInstance, bool>? sourcePredicate = null,
        string logPrefix = "Fallback spontaneous")
    {
        var fallbackSource = activeServices
            .Where(s =>
                (sourcePredicate is null || sourcePredicate(s)) &&
                connectivity.TryGetValue(s.StructureId, out var routes) &&
                routes.Count > 0)
            .OrderBy(_ => NextDouble())
            .FirstOrDefault();

        if (fallbackSource is null ||
            !connectivity.TryGetValue(fallbackSource.StructureId, out var fallbackRoutes) ||
            fallbackRoutes.Count == 0)
        {
            return 0;
        }

        var profile = GetSpontaneousNoiseProfile(fallbackSource.StructureId);
        var route = fallbackRoutes[NextInt(0, fallbackRoutes.Count)];
        var spike = BuildSpontaneousSpike(tickSignal, fallbackSource, route, profile, burstCluster: false);
        QueueSpontaneousSpikeForTargets(
            tickSignal,
            fallbackSource,
            route,
            spike,
            clients,
            instancesByStructure,
            spontaneousNeuronIdsByStructure,
            dispatchQueue,
            dispatchQueueMetrics,
            dispatchQueueMaxBatches,
            dispatchQueueMaxSpikes,
            logPrefix);
        return 1;
    }

    private static bool IsCerebellarSpontaneousSource(ServiceInstance sourceInstance)
        => IsSpontaneousCerebellarStructure(sourceInstance.StructureId);

    private static bool HasSpontaneousRoutes(
        IReadOnlyDictionary<StructureId, List<SynapticConnection>> connectivity,
        StructureId structureId)
        => connectivity.TryGetValue(structureId, out var routes) && routes.Count > 0;

    private static bool IsSpontaneousCerebellarStructure(StructureId structureId)
        => structureId is StructureId.CerebellarGranule
            or StructureId.CerebellarVermis
            or StructureId.CerebellarLobules
            or StructureId.PurkinjeCellLayer
            or StructureId.DeepCerebellarNuclei
            or StructureId.InferiorOlive;

    private static int ComputeSpontaneousServiceOrder(ServiceInstance sourceInstance, long tick)
    {
        unchecked
        {
            var hash = 2166136261u;
            foreach (var ch in sourceInstance.InstanceKey)
            {
                hash ^= ch;
                hash *= 16777619u;
            }

            hash ^= (uint)tick;
            hash *= 16777619u;
            hash ^= (uint)(tick >> 32);
            return (int)(hash & 0x7fffffffu);
        }
    }

    private double ComputeSpontaneousProbabilityPerTick(
        ServiceInstance sourceInstance,
        SpontaneousNoiseProfile profile,
        double tickDurationSeconds,
        double scale,
        AttentionVector attentionBias,
        VisualAttentionRuntime visualAttention)
    {
        var lateralizationWeight = GetHemisphereLateralizationWeight(sourceInstance.StructureId, sourceInstance.Hemisphere);
        var attentionWeight = GetAttentionWeightForStructure(sourceInstance.StructureId, attentionBias);
        var visualHemifieldWeight = GetVisualFieldHemisphereWeight(sourceInstance.StructureId, sourceInstance.Hemisphere, visualAttention);
        return Math.Clamp(profile.EventsPerSecond * tickDurationSeconds * scale * lateralizationWeight * attentionWeight * visualHemifieldWeight, 0.0, 1.0);
    }

    private void QueueSpontaneousSpikeForTargets(
        TickSignal tickSignal,
        ServiceInstance sourceInstance,
        SynapticConnection route,
        SpikeMessage spike,
        IReadOnlyDictionary<string, HttpClient> clients,
        IReadOnlyDictionary<StructureId, List<ServiceInstance>> instancesByStructure,
        IDictionary<StructureId, HashSet<string>> spontaneousNeuronIdsByStructure,
        ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>> dispatchQueue,
        DispatchQueueMetrics dispatchQueueMetrics,
        int dispatchQueueMaxBatches,
        int dispatchQueueMaxSpikes,
        string logPrefix)
    {
        foreach (var targetInstance in ResolveTargetInstances(
            route.Target,
            sourceInstance.Hemisphere,
            instancesByStructure,
            sourceInstance.StructureId,
            route.ProjectionType))
        {
            if (!clients.ContainsKey(targetInstance.InstanceKey))
            {
                continue;
            }

            var queued = TryQueueDispatchBatch(
                dispatchQueue,
                targetInstance.InstanceKey,
                new QueuedDispatchBatch(
                    sourceInstance.InstanceKey,
                    sourceInstance.Hemisphere,
                    targetInstance.Hemisphere,
                    [spike]),
                dispatchQueueMetrics,
                dispatchQueueMaxBatches,
                dispatchQueueMaxSpikes);
            if (!queued)
            {
                logger.LogDebug(
                    "{Prefix} queue saturated at tick {Tick}: dropped {SourceInstance}->{TargetInstance}",
                    logPrefix,
                    tickSignal.Tick,
                    sourceInstance.InstanceKey,
                    targetInstance.InstanceKey);
                continue;
            }

            RecordSpontaneousNeuron(spontaneousNeuronIdsByStructure, spike.SourceStructure, sourceInstance.Hemisphere, spike.SourceNeuronId);
            RecordSpontaneousNeuron(spontaneousNeuronIdsByStructure, spike.TargetStructure, targetInstance.Hemisphere, spike.TargetNeuronId);
        }
    }

    private static void RecordSpontaneousNeuron(
        IDictionary<StructureId, HashSet<string>> collector,
        StructureId structureId,
        string hemisphere,
        string? neuronId)
    {
        if (string.IsNullOrWhiteSpace(neuronId))
        {
            return;
        }

        var normalized = neuronId.Trim();
        if (normalized.IndexOf(':') < 0)
        {
            var hemi = string.IsNullOrWhiteSpace(hemisphere) ? "M" : hemisphere.Trim();
            normalized = $"{hemi}:{normalized}";
        }

        if (!collector.TryGetValue(structureId, out var ids))
        {
            ids = new HashSet<string>(StringComparer.Ordinal);
            collector[structureId] = ids;
        }

        ids.Add(normalized);
    }

    private SpikeMessage BuildSpontaneousSpike(
        TickSignal tickSignal,
        ServiceInstance sourceInstance,
        SynapticConnection route,
        SpontaneousNoiseProfile profile,
        bool burstCluster)
    {
        var vesicleRange = Math.Max(0.01f, profile.MaxVesicleQuanta - profile.MinVesicleQuanta);
        var vesicleQuanta = profile.MinVesicleQuanta + ((float)NextDouble() * vesicleRange);
        var isFeedback = (route.ProjectionType ?? string.Empty).Contains("feedback", StringComparison.OrdinalIgnoreCase);
        var spikeType = burstCluster || NextDouble() < profile.BurstProbability
            ? SpikeTypeEnum.BURST
            : SpikeTypeEnum.ACTION_POTENTIAL;

        return new SpikeMessage
        {
            MessageId = Guid.NewGuid(),
            TimestampMs = tickSignal.TimestampMs,
            SourceStructure = sourceInstance.StructureId,
            TargetStructure = route.Target,
            SourceNeuronId = $"spont-{sourceInstance.Hemisphere}-{sourceInstance.StructureId}-{NextInt(0, 4096):0000}",
            TargetNeuronId = $"auto-{route.Target}-{NextInt(0, 256):000}",
            SynapseId = route.SynapseId,
            Neurotransmitter = route.Neurotransmitter,
            VesicleQuanta = Math.Max(0.05f, vesicleQuanta),
            ReuptakeRate = GetReuptakeRateForNt(route.Neurotransmitter),
            SpikeType = spikeType,
            IsFeedback = isFeedback,
            ModulationContext = tickSignal.GlobalNeuromodState
        };
    }

    private static (float LeftTopDown, float RightTopDown, float TrnGate) ComputeVisualHemifieldTopDown(
        IReadOnlyList<InstanceStructureSnapshot> snapshots)
    {
        if (snapshots.Count == 0)
        {
            return (0.5f, 0.5f, 0f);
        }

        static float MeanRate(
            IReadOnlyList<InstanceStructureSnapshot> values,
            StructureId structureId,
            string hemisphere)
        {
            var selected = values
                .Where(s =>
                    s.StructureId == structureId &&
                    string.Equals((s.Instance.Hemisphere ?? string.Empty).Trim(), hemisphere, StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (selected.Count == 0)
            {
                return 0f;
            }

            return Math.Max(0f, selected.Average(s => s.MeanFiringRateHz));
        }

        static float NormalizeRate(float value)
            => Math.Clamp(value / 55f, 0f, 1f);

        var leftPpc = NormalizeRate(MeanRate(snapshots, StructureId.Ppc, "L"));
        var rightPpc = NormalizeRate(MeanRate(snapshots, StructureId.Ppc, "R"));
        var leftPfc = NormalizeRate(MeanRate(snapshots, StructureId.Pfc, "L"));
        var rightPfc = NormalizeRate(MeanRate(snapshots, StructureId.Pfc, "R"));
        var leftPulvinar = NormalizeRate(MeanRate(snapshots, StructureId.Pulvinar, "L"));
        var rightPulvinar = NormalizeRate(MeanRate(snapshots, StructureId.Pulvinar, "R"));

        // Contralateral retinotopy: right hemisphere control networks bias left visual hemifield, and vice versa.
        var leftFieldTopDown = Math.Clamp((0.46f * rightPpc) + (0.36f * rightPfc) + (0.18f * rightPulvinar), 0f, 1f);
        var rightFieldTopDown = Math.Clamp((0.46f * leftPpc) + (0.36f * leftPfc) + (0.18f * leftPulvinar), 0f, 1f);

        var trnSamples = snapshots
            .Where(s => s.StructureId == StructureId.Trn)
            .Select(s => s.MeanFiringRateHz)
            .ToList();
        var trnRate = trnSamples.Count == 0 ? 0f : Math.Max(0f, trnSamples.Average());
        var trnGate = Math.Clamp(trnRate / 35f, 0f, 1f);
        return (leftFieldTopDown, rightFieldTopDown, trnGate);
    }

    private static AttentionVector ComputeTrnDrivenAttentionBias(
        IReadOnlyList<InstanceStructureSnapshot> snapshots,
        IReadOnlyDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        AttentionVector previous)
    {
        if (snapshots.Count == 0)
        {
            return previous;
        }

        var firingByStructure = snapshots
            .GroupBy(s => s.StructureId)
            .ToDictionary(g => g.Key, g => g.Average(x => x.MeanFiringRateHz));

        static float GetRate(IReadOnlyDictionary<StructureId, float> rates, StructureId id)
            => rates.TryGetValue(id, out var value) ? Math.Clamp(value, 0f, 120f) : 0f;

        static float GetPathwayVolume(
            IReadOnlyDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> pathways,
            StructureId source,
            params StructureId[] targets)
        {
            var total = 0;
            foreach (var entry in pathways)
            {
                if (entry.Key.Source != source)
                {
                    continue;
                }

                for (var i = 0; i < targets.Length; i++)
                {
                    if (entry.Key.Target == targets[i])
                    {
                        total += entry.Value;
                        break;
                    }
                }
            }

            return total;
        }

        var visualDrive =
            (0.55f * (GetRate(firingByStructure, StructureId.V1) + GetRate(firingByStructure, StructureId.V2) + GetRate(firingByStructure, StructureId.V4) + GetRate(firingByStructure, StructureId.Mt))) +
            (0.08f * GetPathwayVolume(activePathways, StructureId.Thalamus, StructureId.V1, StructureId.V2, StructureId.V4, StructureId.Mt)) +
            (0.05f * GetPathwayVolume(activePathways, StructureId.Pulvinar, StructureId.V2, StructureId.V4, StructureId.Mt));

        var auditoryDrive =
            (0.62f * (GetRate(firingByStructure, StructureId.A1) + GetRate(firingByStructure, StructureId.WernickePstgPsts))) +
            (0.09f * GetPathwayVolume(activePathways, StructureId.Thalamus, StructureId.A1)) +
            (0.05f * GetPathwayVolume(activePathways, StructureId.MediodorsalThalamus, StructureId.WernickePstgPsts, StructureId.BrocaBa44Ba45));

        var somatosensoryDrive =
            (0.58f * (GetRate(firingByStructure, StructureId.S1) + GetRate(firingByStructure, StructureId.Ppc))) +
            (0.09f * GetPathwayVolume(activePathways, StructureId.Thalamus, StructureId.S1, StructureId.Ppc)) +
            (0.04f * GetPathwayVolume(activePathways, StructureId.MotorThalamus, StructureId.M1, StructureId.Sma));

        var interoceptiveDrive =
            (0.52f * (GetRate(firingByStructure, StructureId.Insula) + GetRate(firingByStructure, StructureId.Amygdala) + GetRate(firingByStructure, StructureId.Acc) + GetRate(firingByStructure, StructureId.Hypothalamus))) +
            (0.07f * GetPathwayVolume(activePathways, StructureId.MediodorsalThalamus, StructureId.Insula, StructureId.Acc, StructureId.Pfc)) +
            (0.04f * GetPathwayVolume(activePathways, StructureId.Thalamus, StructureId.Insula, StructureId.Acc));

        var drives = new[] { visualDrive, auditoryDrive, somatosensoryDrive, interoceptiveDrive };
        var trnActivity = GetRate(firingByStructure, StructureId.Trn);
        var trnGate = Math.Clamp(trnActivity / 35f, 0f, 1f);
        var dominantIndex = 0;
        var dominantValue = drives[0];
        for (var i = 1; i < drives.Length; i++)
        {
            if (drives[i] > dominantValue)
            {
                dominantValue = drives[i];
                dominantIndex = i;
            }
        }

        for (var i = 0; i < drives.Length; i++)
        {
            var gateScale = i == dominantIndex
                ? (1f + (0.45f * trnGate))
                : (1f - (0.24f * trnGate));
            drives[i] = Math.Max(0.05f, drives[i] * gateScale);
        }

        var sum = drives[0] + drives[1] + drives[2] + drives[3];
        if (sum <= 0.0001f)
        {
            return previous;
        }

        var targetVisual = drives[0] / sum;
        var targetAuditory = drives[1] / sum;
        var targetSomatosensory = drives[2] / sum;
        var targetInteroceptive = drives[3] / sum;

        const float alpha = 0.22f;
        var blendedVisual = ((1f - alpha) * previous.Visual) + (alpha * targetVisual);
        var blendedAuditory = ((1f - alpha) * previous.Auditory) + (alpha * targetAuditory);
        var blendedSomatosensory = ((1f - alpha) * previous.Somatosensory) + (alpha * targetSomatosensory);
        var blendedInteroceptive = ((1f - alpha) * previous.Interoceptive) + (alpha * targetInteroceptive);

        var blendedSum = blendedVisual + blendedAuditory + blendedSomatosensory + blendedInteroceptive;
        if (blendedSum <= 0.0001f)
        {
            return previous;
        }

        return new AttentionVector(
            blendedVisual / blendedSum,
            blendedAuditory / blendedSum,
            blendedSomatosensory / blendedSum,
            blendedInteroceptive / blendedSum);
    }

    internal static BiologicalAttentionRuntime ComputeBiologicalAttentionRuntime(
        long tick,
        IReadOnlyList<InstanceStructureSnapshot> snapshots,
        IReadOnlyDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        BiologicalAttentionRuntime previous,
        VisualAttentionRuntime visualAttention,
        PredictivePerceptionRuntime predictivePerception,
        LimbicRuntimeState limbic,
        SleepMemoryRuntime sleepRuntime,
        EnvironmentalStateRuntime environmental,
        BodyStateRuntime bodyState,
        LanguageIntentRuntime languageIntent,
        AttentionVector sensoryRelayBias)
    {
        static float Clamp01(float value) => Math.Clamp(value, 0f, 1f);
        static float HzToUnit(float hz, float scale = 60f) => Clamp01(hz / Math.Max(1f, scale));
        static float PathwayDrive(
            IReadOnlyDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> pathways,
            StructureId source,
            params StructureId[] targets)
        {
            if (pathways.Count == 0 || targets.Length == 0)
            {
                return 0f;
            }

            var targetSet = targets.ToHashSet();
            var total = 0;
            foreach (var entry in pathways)
            {
                if (entry.Key.Source == source && targetSet.Contains(entry.Key.Target))
                {
                    total += Math.Max(0, entry.Value);
                }
            }

            var maxVolume = Math.Max(1, pathways.Values.DefaultIfEmpty(0).Max());
            return Clamp01(total / (float)(maxVolume * Math.Max(1, targets.Length)));
        }

        if (snapshots.Count == 0)
        {
            return BiologicalAttentionRuntime.Normalize(previous);
        }

        var rates = snapshots
            .GroupBy(s => s.StructureId)
            .ToDictionary(g => g.Key, g => Math.Max(0f, g.Average(x => x.MeanFiringRateHz)));
        float Rate(StructureId structure) => rates.TryGetValue(structure, out var value) ? value : 0f;

        var basalForebrainGain = Clamp01(HzToUnit(Rate(StructureId.BasalForebrain), 45f) * 0.72f + limbic.NeuromodState.AcetylcholineLevel * 0.28f);
        var trnInhibition = Clamp01(HzToUnit(Rate(StructureId.Trn), 38f) * 0.72f + limbic.NeuromodState.NorepinephrineLevel * 0.28f);
        var thalamicRelayGain = Clamp01(
            (0.24f * HzToUnit(Rate(StructureId.Thalamus), 45f)) +
            (0.22f * HzToUnit(Rate(StructureId.Pulvinar), 45f)) +
            (0.22f * HzToUnit(Rate(StructureId.MediodorsalThalamus), 45f)) +
            (0.18f * HzToUnit(Rate(StructureId.IntralaminarThalamus), 45f)) +
            (0.14f * (1f - trnInhibition)));
        var salience = Clamp01(
            (0.36f * limbic.Salience) +
            (0.23f * limbic.Threat) +
            (0.18f * limbic.InteroceptiveDrive) +
            (0.13f * limbic.TiredDrive) +
            (0.10f * basalForebrainGain));

        var environmentalFresh = environmental.LastInputTick >= 0 && tick - environmental.LastInputTick <= 600;
        var darkness = environmentalFresh ? Clamp01(environmental.Darkness) : 0f;
        var shelterNeed = environmentalFresh ? Clamp01(environmental.ShelterNeed) : 0f;
        var anxiety = environmentalFresh ? Clamp01(environmental.Anxiety) : 0f;
        var hunger = environmentalFresh ? Clamp01(environmental.Hunger) : 0f;
        var predatorThreat = environmentalFresh ? Clamp01(environmental.PredatorThreat) : 0f;
        var bodyFresh = bodyState.LastInputTick >= 0 && tick - bodyState.LastInputTick <= 600;
        var movement = bodyFresh
            ? Clamp01((Math.Abs(bodyState.ForwardVelocity) / 2.0f) + (Math.Abs(bodyState.TurnRateDeg) / 180.0f))
            : 0f;
        var contact = bodyFresh ? Clamp01(bodyState.ContactLevel) : 0f;
        var pain = bodyFresh ? Clamp01(bodyState.PainLevel) : 0f;
        var activeLanguage = languageIntent.Active && languageIntent.ExpiresAtTick >= tick;
        var languageStrength = activeLanguage ? Clamp01(languageIntent.Strength / 2.35f) : 0f;
        var visualFocus = Clamp01(visualAttention.FocusConfidence);
        var predictiveFresh = predictivePerception.Active &&
                              predictivePerception.LastUpdatedTick > 0 &&
                              tick - predictivePerception.LastUpdatedTick <= 900;
        var predictiveSurprise = predictiveFresh ? Clamp01(predictivePerception.Surprise) : 0f;
        var predictiveBias = predictiveFresh
            ? predictivePerception.SensoryBias
            : new AttentionVector(0.25f, 0.25f, 0.25f, 0.25f);
        float PredictiveChannelDrive(string channel)
            => predictiveFresh && string.Equals(predictivePerception.LastChannel, channel, StringComparison.OrdinalIgnoreCase)
                ? predictiveSurprise
                : 0f;
        basalForebrainGain = Clamp01(basalForebrainGain + (predictiveFresh ? predictivePerception.LocusCoeruleusAlert * 0.10f : 0f));
        salience = Clamp01(salience + (0.14f * predictiveSurprise));

        var visualDrive =
            (0.28f * sensoryRelayBias.Visual) +
            (0.12f * predictiveBias.Visual) +
            (0.21f * HzToUnit(Rate(StructureId.V1) + Rate(StructureId.V2) + Rate(StructureId.V4) + Rate(StructureId.Mt), 130f)) +
            (0.15f * visualFocus) +
            (0.16f * PredictiveChannelDrive("visual")) +
            (0.12f * PathwayDrive(activePathways, StructureId.Pulvinar, StructureId.V2, StructureId.V4, StructureId.Mt)) +
            (0.10f * predatorThreat) +
            (0.08f * basalForebrainGain) +
            (0.06f * thalamicRelayGain);
        var auditoryDrive =
            (0.30f * sensoryRelayBias.Auditory) +
            (0.12f * predictiveBias.Auditory) +
            (0.24f * HzToUnit(Rate(StructureId.A1) + Rate(StructureId.WernickePstgPsts), 95f)) +
            (0.16f * languageStrength) +
            (0.16f * PredictiveChannelDrive("auditory")) +
            (0.12f * PathwayDrive(activePathways, StructureId.MediodorsalThalamus, StructureId.WernickePstgPsts, StructureId.BrocaBa44Ba45)) +
            (0.10f * basalForebrainGain) +
            (0.08f * thalamicRelayGain);
        var somatosensoryDrive =
            (0.26f * sensoryRelayBias.Somatosensory) +
            (0.12f * predictiveBias.Somatosensory) +
            (0.20f * HzToUnit(Rate(StructureId.S1) + Rate(StructureId.Ppc), 95f)) +
            (0.17f * movement) +
            (0.12f * contact) +
            (0.12f * pain) +
            (0.16f * PredictiveChannelDrive("somatosensory")) +
            (0.12f * PathwayDrive(activePathways, StructureId.Thalamus, StructureId.S1, StructureId.Ppc)) +
            (0.10f * thalamicRelayGain);
        var interoceptiveDrive =
            (0.23f * sensoryRelayBias.Interoceptive) +
            (0.12f * predictiveBias.Interoceptive) +
            (0.20f * limbic.InteroceptiveDrive) +
            (0.18f * limbic.TiredDrive) +
            (0.15f * hunger) +
            (0.10f * shelterNeed) +
            (0.08f * darkness) +
            (0.08f * pain) +
            (0.16f * PredictiveChannelDrive("interoceptive")) +
            (0.06f * HzToUnit(Rate(StructureId.Insula) + Rate(StructureId.Hypothalamus), 95f));
        var languageDrive =
            (0.38f * languageStrength) +
            (0.24f * HzToUnit(Rate(StructureId.BrocaBa44Ba45) + Rate(StructureId.WernickePstgPsts), 95f)) +
            (0.16f * PathwayDrive(activePathways, StructureId.ArcuateFasciculus, StructureId.BrocaBa44Ba45, StructureId.WernickePstgPsts)) +
            (0.12f * basalForebrainGain) +
            (0.10f * thalamicRelayGain);
        var memoryDrive =
            (0.30f * limbic.HippocampalContext) +
            (0.16f * (predictiveFresh ? predictivePerception.HippocampalEncodingGate : 0f)) +
            (0.24f * HzToUnit(Rate(StructureId.CA1) + Rate(StructureId.CA3) + Rate(StructureId.Subiculum) + Rate(StructureId.EntorhinalCortex), 120f)) +
            (0.18f * Math.Abs(limbic.RewardPredictionError)) +
            (0.07f * PathwayDrive(activePathways, StructureId.CA1, StructureId.Pfc, StructureId.RetrosplenialCortex, StructureId.Subiculum)) +
            (0.07f * PathwayDrive(activePathways, StructureId.Subiculum, StructureId.Pfc, StructureId.RetrosplenialCortex, StructureId.ParahippocampalCortex)) +
            (0.14f * basalForebrainGain);
        var motorDrive =
            (0.26f * HzToUnit(Rate(StructureId.M1) + Rate(StructureId.Sma) + Rate(StructureId.PremotorCortex), 120f)) +
            (0.22f * movement) +
            (0.18f * contact) +
            (0.14f * PathwayDrive(activePathways, StructureId.MotorThalamus, StructureId.M1, StructureId.Sma)) +
            (0.12f * languageStrength) +
            (0.08f * thalamicRelayGain);

        var sleepSensoryDamping = sleepRuntime.IsSleeping ? 0.42f : 1f;
        visualDrive *= sleepSensoryDamping;
        auditoryDrive *= sleepSensoryDamping;
        somatosensoryDrive *= sleepSensoryDamping;
        motorDrive *= sleepRuntime.IsSleeping ? 0.18f : 1f;
        memoryDrive *= sleepRuntime.IsSleeping ? 1.35f : 1f;
        interoceptiveDrive *= sleepRuntime.IsSleeping ? 0.82f : 1f;
        languageDrive *= sleepRuntime.IsSleeping ? 0.35f : 1f;

        var rawDrives = new Dictionary<string, float>(StringComparer.OrdinalIgnoreCase)
        {
            ["visual"] = Math.Max(0.01f, visualDrive),
            ["auditory"] = Math.Max(0.01f, auditoryDrive),
            ["somatosensory"] = Math.Max(0.01f, somatosensoryDrive),
            ["interoceptive"] = Math.Max(0.01f, interoceptiveDrive),
            ["language"] = Math.Max(0.01f, languageDrive),
            ["memory"] = Math.Max(0.01f, memoryDrive),
            ["motor"] = Math.Max(0.01f, motorDrive)
        };

        var dominant = rawDrives.OrderByDescending(p => p.Value).First();
        var currentDominant = string.IsNullOrWhiteSpace(previous.DominantChannel) ? dominant.Key : previous.DominantChannel;
        var holdTicks = Math.Max(0, previous.HoldTicksRemaining - 1);
        var currentValue = rawDrives.TryGetValue(currentDominant, out var heldValue) ? heldValue : 0f;
        var switchMargin = 0.035f + (0.075f * trnInhibition);
        var nextDominant = currentDominant;
        var switched = false;
        if (holdTicks <= 0 || dominant.Value > currentValue + switchMargin)
        {
            nextDominant = dominant.Key;
            switched = !string.Equals(nextDominant, currentDominant, StringComparison.OrdinalIgnoreCase);
        }

        var trnSelectivity = 0.18f + (0.48f * trnInhibition);
        foreach (var key in rawDrives.Keys.ToArray())
        {
            var relay = 0.72f + (0.48f * thalamicRelayGain);
            var cholinergic = 0.86f + (0.30f * basalForebrainGain);
            var gate = string.Equals(key, nextDominant, StringComparison.OrdinalIgnoreCase)
                ? relay * cholinergic * (1.0f + (0.30f * salience))
                : relay * (1.0f - trnSelectivity);
            rawDrives[key] = Math.Max(0.005f, rawDrives[key] * gate);
        }

        var total = rawDrives.Values.Sum();
        if (total <= 0.0001f)
        {
            return BiologicalAttentionRuntime.Normalize(previous);
        }

        var targetVisual = rawDrives["visual"] / total;
        var targetAuditory = rawDrives["auditory"] / total;
        var targetSomato = rawDrives["somatosensory"] / total;
        var targetIntero = rawDrives["interoceptive"] / total;
        var targetLanguage = rawDrives["language"] / total;
        var targetMemory = rawDrives["memory"] / total;
        var targetMotor = rawDrives["motor"] / total;
        var alpha = sleepRuntime.IsSleeping ? 0.11f : 0.24f + (0.10f * basalForebrainGain);

        float Blend(float oldValue, float target) => Clamp01((oldValue * (1f - alpha)) + (target * alpha));
        var visual = Blend(previous.Visual, targetVisual);
        var auditory = Blend(previous.Auditory, targetAuditory);
        var somatosensory = Blend(previous.Somatosensory, targetSomato);
        var interoceptive = Blend(previous.Interoceptive, targetIntero);
        var language = Blend(previous.Language, targetLanguage);
        var memory = Blend(previous.Memory, targetMemory);
        var motor = Blend(previous.Motor, targetMotor);
        var blendedTotal = visual + auditory + somatosensory + interoceptive + language + memory + motor;
        if (blendedTotal <= 0.0001f)
        {
            return BiologicalAttentionRuntime.Normalize(previous);
        }

        visual /= blendedTotal;
        auditory /= blendedTotal;
        somatosensory /= blendedTotal;
        interoceptive /= blendedTotal;
        language /= blendedTotal;
        memory /= blendedTotal;
        motor /= blendedTotal;

        var sorted = new[] { visual, auditory, somatosensory, interoceptive, language, memory, motor }
            .OrderByDescending(v => v)
            .ToArray();
        var confidence = sorted.Length < 2
            ? sorted[0]
            : Clamp01((sorted[0] - sorted[1]) * (2.2f + (1.6f * trnInhibition)) + (salience * 0.12f));
        var lastSwitchTick = switched ? tick : previous.LastSwitchTick;
        var nextHold = switched
            ? 8 + (int)Math.Round(16.0 * trnInhibition)
            : holdTicks;

        var sensoryVisual = visual + (0.22f * memory) + (0.14f * language);
        var sensoryAuditory = auditory + (0.24f * language);
        var sensorySomato = somatosensory + (0.24f * motor);
        var sensoryIntero = interoceptive + (0.18f * memory);
        var sensoryTotal = sensoryVisual + sensoryAuditory + sensorySomato + sensoryIntero;
        var sensoryBias = sensoryTotal <= 0.0001f
            ? previous.SensoryBias
            : new AttentionVector(
                sensoryVisual / sensoryTotal,
                sensoryAuditory / sensoryTotal,
                sensorySomato / sensoryTotal,
                sensoryIntero / sensoryTotal);

        return BiologicalAttentionRuntime.Normalize(new BiologicalAttentionRuntime(
            visual,
            auditory,
            somatosensory,
            interoceptive,
            language,
            memory,
            motor,
            nextDominant,
            confidence,
            salience,
            thalamicRelayGain,
            trnInhibition,
            basalForebrainGain,
            sensoryBias,
            lastSwitchTick,
            nextHold));
    }

    private static LimbicRuntimeState ComputeLimbicRuntimeState(
        TickSignal tickSignal,
        IReadOnlyList<InstanceStructureSnapshot> snapshots,
        IReadOnlyDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        LimbicRuntimeState previous,
        SleepMemoryRuntime sleepRuntime,
        EnvironmentalStateRuntime environmental,
        OutcomeStateRuntime outcome)
    {
        static float Clamp01(float value) => Math.Clamp(value, 0f, 1f);
        static float ClampSigned(float value) => Math.Clamp(value, -1f, 1f);
        static float HzToUnit(float hz, float scale = 65f) => Clamp01(hz / Math.Max(1f, scale));

        var firingByStructure = snapshots
            .GroupBy(s => s.StructureId)
            .ToDictionary(g => g.Key, g => Math.Max(0f, g.Average(x => x.MeanFiringRateHz)));

        float GetRate(StructureId id) => firingByStructure.TryGetValue(id, out var value) ? value : 0f;

        var maxPathVolume = activePathways.Count == 0 ? 1 : Math.Max(1, activePathways.Values.Max());
        float GetPathwayDrive(StructureId source, NTEnum? nt, params StructureId[] targets)
        {
            if (targets.Length == 0)
            {
                return 0f;
            }

            var targetSet = new HashSet<StructureId>(targets);
            var total = 0;
            foreach (var pathway in activePathways)
            {
                if (pathway.Key.Source != source)
                {
                    continue;
                }

                if (nt.HasValue && pathway.Key.Nt != nt.Value)
                {
                    continue;
                }

                if (!targetSet.Contains(pathway.Key.Target))
                {
                    continue;
                }

                total += pathway.Value;
            }

            var denom = (float)(maxPathVolume * Math.Max(1, targets.Length));
            return Clamp01(total / Math.Max(1f, denom));
        }

        var amygdala = HzToUnit(GetRate(StructureId.Amygdala));
        var acc = HzToUnit(GetRate(StructureId.Acc));
        var insula = HzToUnit(GetRate(StructureId.Insula));
        var hypothalamus = HzToUnit(GetRate(StructureId.Hypothalamus));
        var ofc = HzToUnit(GetRate(StructureId.OrbitofrontalCortex));
        var pfc = HzToUnit(GetRate(StructureId.Pfc));
        var na = HzToUnit(GetRate(StructureId.NucleusAccumbens));
        var vp = HzToUnit(GetRate(StructureId.VentralPallidum));
        var vta = HzToUnit(GetRate(StructureId.Vta));
        var snc = HzToUnit(GetRate(StructureId.Snc));
        var habenula = HzToUnit(GetRate(StructureId.Habenula));
        var raphe = HzToUnit(GetRate(StructureId.RapheNuclei));
        var lc = HzToUnit(GetRate(StructureId.LocusCoeruleus));
        var basalForebrain = HzToUnit(GetRate(StructureId.BasalForebrain));
        var ca1 = HzToUnit(GetRate(StructureId.CA1));
        var subiculum = HzToUnit(GetRate(StructureId.Subiculum));
        var ec = HzToUnit(GetRate(StructureId.EntorhinalCortex));

        var amygdalaSalienceFlow = GetPathwayDrive(
            StructureId.Amygdala,
            NTEnum.GLUTAMATE,
            StructureId.Acc,
            StructureId.Insula,
            StructureId.Hypothalamus);
        var habenulaAversiveFlow = GetPathwayDrive(
            StructureId.Habenula,
            NTEnum.GABA,
            StructureId.Vta,
            StructureId.Snc);
        var rewardFlow = GetPathwayDrive(
            StructureId.Vta,
            NTEnum.DOPAMINE,
            StructureId.NucleusAccumbens,
            StructureId.Pfc,
            StructureId.OrbitofrontalCortex);
        var accErrorFlow = GetPathwayDrive(
            StructureId.Acc,
            null,
            StructureId.Pfc,
            StructureId.OrbitofrontalCortex,
            StructureId.Hypothalamus);
        var environmentalFresh = environmental.LastInputTick >= 0 && tickSignal.Tick - environmental.LastInputTick <= 240;
        var environmentalDarkness = environmentalFresh ? Clamp01(environmental.Darkness) : 0f;
        var environmentalShelterNeed = environmentalFresh ? Clamp01(environmental.ShelterNeed) : 0f;
        var environmentalAnxiety = environmentalFresh ? Clamp01(environmental.Anxiety) : 0f;
        var environmentalHunger = environmentalFresh ? Clamp01(environmental.Hunger) : 0f;
        var environmentalPredatorThreat = environmentalFresh ? Clamp01(environmental.PredatorThreat) : 0f;
        var environmentalInShelter = environmentalFresh ? Clamp01(environmental.InShelter) : 0f;
        var environmentalHealth = environmentalFresh ? Clamp01(environmental.Health) : 1f;
        var environmentalShelterSafety = environmentalFresh ? Clamp01(environmental.ShelterSafety) : 0f;
        var environmentalSafety = Clamp01(Math.Max(environmentalInShelter, environmentalShelterSafety));
        var environmentalExposure = Clamp01(1f - environmentalSafety);
        var environmentalHealthDeficit = Clamp01(1f - environmentalHealth);
        var worldThreatSignal = Clamp01((0.72f * environmentalPredatorThreat * environmentalExposure) + (0.28f * environmentalAnxiety));
        var worldShelterDrive = Clamp01((0.55f * environmentalShelterNeed) + (0.30f * environmentalDarkness * environmentalExposure) + (0.15f * worldThreatSignal));
        var outcomeFresh = outcome.LastInputTick >= 0 && tickSignal.Tick - outcome.LastInputTick <= 240;
        var satietyRelief = outcomeFresh ? Clamp01(outcome.SatietyRelief) : 0f;
        var safetyRelief = outcomeFresh ? Clamp01(outcome.SafetyRelief) : 0f;
        var painOutcome = outcomeFresh ? Clamp01(outcome.PainLevel) : 0f;
        var damageOutcome = outcomeFresh ? Clamp01(outcome.DamageLevel) : 0f;
        var shelterComfort = outcomeFresh ? Clamp01(outcome.ShelterComfort) : 0f;
        var progressOutcome = outcomeFresh ? Clamp01(outcome.Progress) : 0f;
        var effortCost = outcomeFresh ? Clamp01(outcome.EffortCost) : 0f;
        var noveltyOutcome = outcomeFresh ? Clamp01(outcome.Novelty) : 0f;
        var socialApproval = outcomeFresh ? Clamp01(outcome.SocialApproval) : 0f;
        var appetitiveOutcome = outcomeFresh ? Clamp01(outcome.AppetitiveRelief) : 0f;
        var aversiveOutcome = outcomeFresh ? Clamp01(outcome.AversiveOutcome) : 0f;

        var salience = Clamp01(
            (0.30f * amygdala) +
            (0.22f * acc) +
            (0.18f * insula) +
            (0.14f * lc) +
            (0.10f * basalForebrain) +
            (0.06f * amygdalaSalienceFlow) +
            (0.10f * worldThreatSignal) +
            (0.05f * environmentalHunger));

        var rawThreat = Clamp01(
            (0.43f * amygdala) +
            (0.21f * hypothalamus) +
            (0.14f * insula) +
            (0.11f * habenula) +
            (0.07f * accErrorFlow) +
            (0.04f * amygdalaSalienceFlow) +
            (0.12f * environmentalAnxiety) +
            (0.05f * environmentalDarkness * environmentalExposure) +
            (0.28f * worldThreatSignal) +
            (0.08f * environmentalHealthDeficit) +
            (0.12f * aversiveOutcome));

        var interoceptiveDrive = Clamp01(
            (0.44f * insula) +
            (0.36f * hypothalamus) +
            (0.14f * acc) +
            (0.06f * raphe) +
            (0.08f * environmentalShelterNeed) +
            (0.28f * environmentalHunger) +
            (0.16f * environmentalHealthDeficit) +
            (0.10f * worldShelterDrive) +
            (0.12f * painOutcome) +
            (0.08f * damageOutcome));

        var hippocampalContext = Clamp01((ca1 + subiculum + ec) / 3f);

        var expectedReward = Clamp01(
            (0.40f * ofc) +
            (0.22f * pfc) +
            (0.21f * na) +
            (0.10f * vp) +
            (0.07f * hippocampalContext) +
            (0.08f * environmentalSafety) +
            (0.04f * (1f - environmentalHunger)) +
            (0.08f * progressOutcome));

        var observedReward = Clamp01(
            (0.38f * vta) +
            (0.32f * snc) +
            (0.18f * na) +
            (0.12f * rewardFlow) +
            (0.10f * environmentalSafety) +
            (0.04f * (1f - environmentalHunger)) +
            (0.24f * satietyRelief) +
            (0.22f * safetyRelief) +
            (0.15f * shelterComfort) +
            (0.13f * progressOutcome) +
            (0.07f * noveltyOutcome) +
            (0.05f * socialApproval));

        var rawAversiveDrive = Clamp01(
            (0.44f * habenula) +
            (0.27f * amygdala) +
            (0.13f * acc) +
            (0.16f * habenulaAversiveFlow) +
            (0.13f * environmentalAnxiety) +
            (0.05f * environmentalDarkness * environmentalExposure) +
            (0.22f * worldThreatSignal) +
            (0.14f * environmentalHunger) +
            (0.14f * environmentalHealthDeficit) +
            (0.24f * painOutcome) +
            (0.20f * damageOutcome) +
            (0.12f * effortCost) +
            (0.10f * aversiveOutcome));

        // Fight-or-flight dynamics use asymmetric kinetics:
        // engage quickly when threat rises, recover gradually to avoid jittery stage flips.
        var previousThreat = Clamp01(previous.Threat);
        var previousAversive = Clamp01(previous.AversiveDrive);
        var threatRiseAlpha = sleepRuntime.IsSleeping ? 0.05f : 0.24f;
        var threatFallAlpha = sleepRuntime.IsSleeping ? 0.02f : 0.08f;
        var aversiveRiseAlpha = sleepRuntime.IsSleeping ? 0.05f : 0.20f;
        var aversiveFallAlpha = sleepRuntime.IsSleeping ? 0.02f : 0.07f;
        var threatRecoveryGate = Clamp01(0.30f + (0.50f * (1f - rawAversiveDrive)) + (0.20f * Math.Max(0f, previous.Valence)));
        var aversiveRecoveryGate = Clamp01(0.28f + (0.44f * (1f - rawThreat)) + (0.28f * Math.Max(0f, previous.Valence)));
        var threat = rawThreat >= previousThreat
            ? previousThreat + (threatRiseAlpha * (rawThreat - previousThreat))
            : previousThreat + ((threatFallAlpha * threatRecoveryGate) * (rawThreat - previousThreat));
        var aversiveDrive = rawAversiveDrive >= previousAversive
            ? previousAversive + (aversiveRiseAlpha * (rawAversiveDrive - previousAversive))
            : previousAversive + ((aversiveFallAlpha * aversiveRecoveryGate) * (rawAversiveDrive - previousAversive));
        threat = Clamp01(threat);
        aversiveDrive = Clamp01(aversiveDrive);

        var sleepPressureNorm = Clamp01(sleepRuntime.SleepPressure / Math.Max(0.0001f, sleepRuntime.MaxSleepPressure));
        var atpNorm = Clamp01(sleepRuntime.AtpBudget / Math.Max(0.0001f, sleepRuntime.MaxAtpBudget));
        var atpDeficit = Clamp01(1f - atpNorm);
        var tiredDriveRaw = Clamp01(
            (0.48f * sleepPressureNorm) +
            (0.30f * atpDeficit) +
            (0.12f * interoceptiveDrive) +
            (0.06f * (1f - expectedReward)) +
            (0.04f * aversiveDrive) +
            (0.14f * environmentalDarkness) +
            (0.08f * environmentalShelterNeed) +
            (0.07f * worldShelterDrive));
        var previousTired = Clamp01(previous.TiredDrive);
        var tiredRiseAlpha = sleepRuntime.IsSleeping ? 0.04f : 0.13f;
        var tiredFallAlpha = sleepRuntime.IsSleeping ? 0.02f : 0.08f;
        var tiredDrive = tiredDriveRaw >= previousTired
            ? previousTired + (tiredRiseAlpha * (tiredDriveRaw - previousTired))
            : previousTired + (tiredFallAlpha * (tiredDriveRaw - previousTired));
        tiredDrive = Clamp01(tiredDrive);

        var valenceRaw = (0.62f * observedReward) + (0.18f * expectedReward) + (0.16f * appetitiveOutcome) - (0.55f * threat) - (0.45f * aversiveDrive) - (0.12f * aversiveOutcome);
        var valence = ClampSigned(valenceRaw);
        var rpeRaw = (observedReward - expectedReward) + (0.28f * appetitiveOutcome) - (0.42f * aversiveDrive) - (0.30f * aversiveOutcome) + (0.12f * hippocampalContext);
        var rewardPredictionError = ClampSigned((0.68f * previous.RewardPredictionError) + (0.32f * rpeRaw));

        // Wake drives phasic neuromodulation; sleep dampens noradrenergic/cholinergic tone.
        var sleepDamping = sleepRuntime.IsSleeping ? 0.70f : 1.0f;
        var fightOrFlightDrive = Clamp01(
            (0.60f * threat) +
            (0.24f * aversiveDrive) +
            (0.16f * salience));
        var highThreatQuadratic = fightOrFlightDrive * fightOrFlightDrive;
        var dopamineTarget = Clamp01(
            0.18f +
            (0.36f * observedReward) +
            (0.24f * Math.Max(0f, rewardPredictionError)) +
            (0.10f * expectedReward) -
            (0.24f * aversiveDrive) -
            (0.12f * threat) -
            (0.22f * highThreatQuadratic) -
            (0.18f * tiredDrive));
        var serotoninTarget = Clamp01(
            0.22f +
            (0.30f * interoceptiveDrive) +
            (0.18f * (1f - Math.Max(0f, valence))) +
            (0.14f * aversiveDrive) +
            (0.14f * raphe) +
            (0.10f * tiredDrive) +
            (sleepRuntime.IsSleeping ? 0.08f : 0f));
        var acetylcholineTarget = Clamp01(
            (0.10f + (0.40f * salience) + (0.23f * hippocampalContext) + (0.15f * basalForebrain) - (0.12f * tiredDrive)) * sleepDamping);
        var norepinephrineTarget = Clamp01(
            (0.10f + (0.48f * threat) + (0.24f * salience) + (0.16f * lc) + (0.14f * highThreatQuadratic) + (0.08f * tiredDrive * (1f - threat))) * sleepDamping);

        var kinetics = sleepRuntime.IsSleeping ? 0.06f : 0.14f;
        var previousNeuromod = previous.NeuromodState ?? new NeuromodState();
        var neuromod = NeuromodState.Clamp(new NeuromodState
        {
            DopamineLevel = ((1f - kinetics) * previousNeuromod.DopamineLevel) + (kinetics * dopamineTarget),
            SerotoninLevel = ((1f - kinetics) * previousNeuromod.SerotoninLevel) + (kinetics * serotoninTarget),
            AcetylcholineLevel = ((1f - kinetics) * previousNeuromod.AcetylcholineLevel) + (kinetics * acetylcholineTarget),
            NorepinephrineLevel = ((1f - kinetics) * previousNeuromod.NorepinephrineLevel) + (kinetics * norepinephrineTarget)
        });

        var wasTired = string.Equals(previous.Stage, "tired", StringComparison.OrdinalIgnoreCase);
        var tiredEnterThreshold = 0.68f;
        var tiredExitThreshold = 0.54f;
        var tiredQualified = wasTired
            ? tiredDrive >= tiredExitThreshold
            : tiredDrive >= tiredEnterThreshold;
        var shelterTiredQualified = worldShelterDrive >= 0.58f &&
            environmentalSafety < 0.40f &&
            tiredDrive >= 0.50f;

        var stage = sleepRuntime.IsSleeping
            ? "sleep"
            : fightOrFlightDrive >= 0.72f
                ? "fight_or_flight"
                : tiredQualified || shelterTiredQualified
                    ? "tired"
                    : (threat >= 0.38f || salience >= 0.44f)
                        ? "alert"
                        : "awake";

        return new LimbicRuntimeState(
            Stage: stage,
            Salience: salience,
            Threat: threat,
            TiredDrive: tiredDrive,
            InteroceptiveDrive: interoceptiveDrive,
            AversiveDrive: aversiveDrive,
            ExpectedReward: expectedReward,
            ObservedReward: observedReward,
            HippocampalContext: hippocampalContext,
            Valence: valence,
            RewardPredictionError: rewardPredictionError,
            DopamineTarget: dopamineTarget,
            SerotoninTarget: serotoninTarget,
            AcetylcholineTarget: acetylcholineTarget,
            NorepinephrineTarget: norepinephrineTarget,
            NeuromodState: neuromod,
            LastUpdatedTick: tickSignal.Tick);
    }

    private static double GetAttentionWeightForStructure(StructureId structureId, AttentionVector attention)
    {
        var a = structureId switch
        {
            StructureId.V1 or StructureId.V2 or StructureId.V4 or StructureId.Mt => attention.Visual,
            StructureId.A1 or StructureId.WernickePstgPsts => attention.Auditory,
            StructureId.S1 or StructureId.Ppc or StructureId.M1 or StructureId.Sma => attention.Somatosensory,
            StructureId.Insula or StructureId.Amygdala or StructureId.Acc or StructureId.Hypothalamus => attention.Interoceptive,
            _ => 0.25f
        };

        return Math.Clamp(0.65 + (a * 1.70), 0.35, 2.10);
    }

    private static double GetHemisphereLateralizationWeight(StructureId structureId, string hemisphere)
    {
        var hemi = string.IsNullOrWhiteSpace(hemisphere)
            ? "M"
            : hemisphere.Trim().ToUpperInvariant();
        if (hemi is not "L" and not "R")
        {
            return 1.0;
        }

        var isLeft = hemi == "L";
        return structureId switch
        {
            StructureId.BrocaBa44Ba45 or StructureId.WernickePstgPsts or StructureId.ArcuateFasciculus or StructureId.SupramarginalAngular
                => isLeft ? 1.30 : 0.75,
            StructureId.Pfc or StructureId.TemporalAssociation
                => isLeft ? 1.15 : 0.90,
            StructureId.Ppc or StructureId.Insula or StructureId.Amygdala
                => isLeft ? 0.88 : 1.18,
            _ => 1.0
        };
    }

    private static double GetVisualFieldHemisphereWeight(
        StructureId structureId,
        string hemisphere,
        VisualAttentionRuntime visualAttention)
    {
        if (!IsVisualAttentionDrivenStructure(structureId))
        {
            return 1.0;
        }

        var hemi = string.IsNullOrWhiteSpace(hemisphere)
            ? "M"
            : hemisphere.Trim().ToUpperInvariant();
        if (hemi is not "L" and not "R")
        {
            return 1.0;
        }

        if (visualAttention.FocusedHemisphere is not "L" and not "R")
        {
            return 1.0;
        }

        var confidence = Math.Clamp(visualAttention.FocusConfidence, 0f, 1f);
        var boost = 1.10 + (0.55 * confidence);
        var suppress = 0.88 - (0.30 * confidence);
        return string.Equals(hemi, visualAttention.FocusedHemisphere, StringComparison.OrdinalIgnoreCase)
            ? boost
            : Math.Max(0.45, suppress);
    }

    private static bool IsVisualAttentionDrivenStructure(StructureId structureId) => structureId switch
    {
        StructureId.V1 or
        StructureId.V2 or
        StructureId.V4 or
        StructureId.Mt or
        StructureId.Thalamus or
        StructureId.Pulvinar or
        StructureId.Ppc or
        StructureId.Pfc => true,
        _ => false
    };

    private static SpontaneousNoiseProfile GetSpontaneousNoiseProfile(StructureId structureId) => structureId switch
    {
        StructureId.Pfc or StructureId.BrocaBa44Ba45 or StructureId.WernickePstgPsts or StructureId.SupramarginalAngular or StructureId.OrbitofrontalCortex or StructureId.Insula or StructureId.Ppc or StructureId.TemporalAssociation or StructureId.PremotorCortex or StructureId.ParahippocampalCortex or StructureId.PerirhinalCortex or StructureId.PosteriorCingulate or StructureId.RetrosplenialCortex or StructureId.Acc or StructureId.M1 or StructureId.Sma
            => new SpontaneousNoiseProfile(8.5, 2, 5, 1.80f, 4.20f, 0.55),
        StructureId.V1 or StructureId.V2 or StructureId.V4 or StructureId.Mt or StructureId.A1 or StructureId.S1 or StructureId.EntorhinalCortex or StructureId.CorpusCallosum
            => new SpontaneousNoiseProfile(6.8, 1, 4, 1.40f, 3.60f, 0.42),
        StructureId.Thalamus or StructureId.MotorThalamus or StructureId.Trn or StructureId.Pulvinar or StructureId.MediodorsalThalamus or StructureId.IntralaminarThalamus
            => new SpontaneousNoiseProfile(5.4, 1, 3, 1.20f, 3.10f, 0.35),
        StructureId.CerebellarGranule
            => new SpontaneousNoiseProfile(6.2, 1, 4, 1.20f, 3.20f, 0.36),
        StructureId.CerebellarVermis or StructureId.CerebellarLobules
            => new SpontaneousNoiseProfile(5.8, 1, 3, 1.15f, 3.00f, 0.34),
        StructureId.PurkinjeCellLayer
            => new SpontaneousNoiseProfile(6.4, 1, 4, 1.05f, 2.70f, 0.30),
        StructureId.DeepCerebellarNuclei
            => new SpontaneousNoiseProfile(5.6, 1, 3, 1.25f, 3.20f, 0.34),
        StructureId.InferiorOlive or StructureId.Pons
            => new SpontaneousNoiseProfile(5.2, 1, 3, 1.10f, 2.90f, 0.32),
        StructureId.Retina
            => new SpontaneousNoiseProfile(4.4, 1, 2, 1.00f, 2.40f, 0.22),
        StructureId.Cochlea or StructureId.CochlearNucleus or StructureId.SuperiorOlive or StructureId.InferiorColliculus
            => new SpontaneousNoiseProfile(4.8, 1, 3, 1.05f, 2.70f, 0.28),
        StructureId.VestibularNuclei or StructureId.NucleusTractusSolitarius or StructureId.OlfactoryBulb
            => new SpontaneousNoiseProfile(4.6, 1, 3, 1.05f, 2.60f, 0.28),
        StructureId.ArcuateFasciculus
            => new SpontaneousNoiseProfile(4.8, 1, 2, 1.00f, 2.50f, 0.24),
        StructureId.Striatum or StructureId.GlobusPallidus or StructureId.GPe or StructureId.GPi or StructureId.Stn or StructureId.Snr
            => new SpontaneousNoiseProfile(5.0, 1, 3, 1.00f, 2.70f, 0.30),
        StructureId.Snc or StructureId.Vta or StructureId.LocusCoeruleus or StructureId.RapheNuclei or StructureId.BasalForebrain
            => new SpontaneousNoiseProfile(4.4, 1, 2, 0.95f, 2.40f, 0.24),
        StructureId.Hypothalamus or StructureId.Amygdala or StructureId.NucleusAccumbens or StructureId.VentralPallidum
            => new SpontaneousNoiseProfile(4.7, 1, 3, 1.05f, 2.70f, 0.30),
        StructureId.ReticularFormation or StructureId.PeriaqueductalGray or StructureId.Medulla
            => new SpontaneousNoiseProfile(4.5, 1, 3, 1.00f, 2.60f, 0.28),
        StructureId.SpinalCordMotor
            => new SpontaneousNoiseProfile(3.8, 1, 2, 0.90f, 2.10f, 0.20),
        StructureId.CA1 or StructureId.CA2 or StructureId.CA3 or StructureId.DentateGyrus or StructureId.Subiculum or StructureId.Presubiculum or StructureId.Parasubiculum or StructureId.Habenula or StructureId.SuperiorColliculus
            => new SpontaneousNoiseProfile(4.6, 1, 3, 1.10f, 2.80f, 0.30),
        _ => new SpontaneousNoiseProfile(3.2, 1, 3, 0.95f, 2.40f, 0.25)
    };

    private static float GetReuptakeRateForNt(NTEnum neurotransmitter) => neurotransmitter switch
    {
        NTEnum.DOPAMINE => 40f,
        NTEnum.SEROTONIN => 50f,
        NTEnum.ACETYLCHOLINE => 20f,
        NTEnum.NOREPINEPHRINE => 30f,
        NTEnum.GABA => 12f,
        _ => 8f
    };

    private double NextDouble()
    {
        lock (_noiseGate)
        {
            return _noiseRandom.NextDouble();
        }
    }

    private int NextInt(int minInclusive, int maxExclusive)
    {
        lock (_noiseGate)
        {
            return _noiseRandom.Next(minInclusive, maxExclusive);
        }
    }

    private static string ClassifyFailure(Exception ex)
    {
        if (ex is TaskCanceledException)
        {
            return "timeout (no TickAck within timeout window)";
        }

        if (ex is HttpRequestException httpEx)
        {
            if (!string.IsNullOrWhiteSpace(httpEx.Message) &&
                httpEx.Message.Contains("Synchronous operations are disallowed", StringComparison.OrdinalIgnoreCase))
            {
                return "target service is running a stale protocol build (restart/rebuild structure services to pick up async spike decoding)";
            }

            return string.IsNullOrWhiteSpace(httpEx.Message)
                ? "http request failure"
                : $"http request failure ({httpEx.Message})";
        }

        var root = ex.GetBaseException();
        if (root is System.Net.Sockets.SocketException sock)
        {
            return $"socket error ({sock.SocketErrorCode})";
        }

        return string.IsNullOrWhiteSpace(ex.Message)
            ? ex.GetType().Name
            : $"{ex.GetType().Name}: {ex.Message}";
    }

    private static int ComputeDispatchBatchChunkSize(
        int configuredChunkSize,
        int effectivePerServiceBudget,
        int effectivePerTickBudget)
    {
        var baseline = Math.Max(32, effectivePerServiceBudget * 2);
        var cappedByTickBudget = Math.Max(32, effectivePerTickBudget / 4);
        return Math.Clamp(Math.Min(configuredChunkSize, Math.Min(2048, Math.Max(baseline, cappedByTickBudget))), 32, 4096);
    }

    private static double ComputeTransportQueuePressure(TransportRuntimeStats transport)
    {
        var queuePressureSignal = transport.DispatchQueueDroppedSpikes
                                  + (transport.DispatchQueueDispatchErrors * 24.0)
                                  + (transport.SpontaneousDispatchErrors * 6.0);
        var queuePressureDenominator = Math.Max(32.0, transport.DispatchQueueQueuedSpikes + transport.DispatchedSpikes + 1.0);
        return Math.Clamp(queuePressureSignal / queuePressureDenominator, 0.0, 1.0);
    }

    private static (int MaxQueueBatches, int MaxQueueSpikes) ComputeDispatchQueueLimits(
        int baseMaxBatches,
        int baseMaxSpikes,
        double adaptivePressure,
        double queuePressure,
        int previousDroppedBatches,
        int previousDroppedSpikes,
        int activityCount,
        double maxGrowthScale)
    {
        var pressureScale = 1.0 + Math.Clamp((adaptivePressure * 0.55) + (queuePressure * 0.95), 0.0, 1.75);
        var dropScale = previousDroppedBatches > 0 || previousDroppedSpikes > 0 ? 1.35 : 1.0;
        var activityScale = activityCount <= 0
            ? 1.0
            : Math.Clamp(1.0 + (activityCount / 96.0), 1.0, 1.40);
        var combinedScale = Math.Clamp(pressureScale * dropScale * activityScale, 1.0, Math.Max(1.0, maxGrowthScale));

        var scaledMaxBatches = Math.Max(baseMaxBatches, (int)Math.Round(baseMaxBatches * combinedScale));
        var scaledMaxSpikes = Math.Max(baseMaxSpikes, (int)Math.Round(baseMaxSpikes * combinedScale));
        return (scaledMaxBatches, scaledMaxSpikes);
    }

    private static void UpdatePeak(ref int peakField, int candidate)
    {
        while (true)
        {
            var current = Volatile.Read(ref peakField);
            if (candidate <= current)
            {
                return;
            }

            if (Interlocked.CompareExchange(ref peakField, candidate, current) == current)
            {
                return;
            }
        }
    }

    private static bool TryQueueDispatchBatch(
        ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>> dispatchQueueByTarget,
        string targetInstanceKey,
        QueuedDispatchBatch batch,
        DispatchQueueMetrics metrics,
        int maxQueueBatches,
        int maxQueueSpikes)
    {
        if (batch.Spikes.Count == 0)
        {
            return false;
        }

        var queuedBatches = Interlocked.Increment(ref metrics.QueuedBatches);
        UpdatePeak(ref metrics.PeakQueuedBatches, queuedBatches);
        var queuedSpikes = Interlocked.Add(ref metrics.QueuedSpikes, batch.Spikes.Count);
        UpdatePeak(ref metrics.PeakQueuedSpikes, queuedSpikes);
        if (queuedBatches > maxQueueBatches || queuedSpikes > maxQueueSpikes)
        {
            Interlocked.Decrement(ref metrics.QueuedBatches);
            Interlocked.Add(ref metrics.QueuedSpikes, -batch.Spikes.Count);
            Interlocked.Increment(ref metrics.DroppedBatches);
            Interlocked.Add(ref metrics.DroppedSpikes, batch.Spikes.Count);
            return false;
        }

        var queue = dispatchQueueByTarget.GetOrAdd(targetInstanceKey, _ => new ConcurrentQueue<QueuedDispatchBatch>());
        queue.Enqueue(batch);
        return true;
    }

    private async Task<DispatchFlushResult> FlushQueuedDispatchBatchesAsync(
        TickSignal tickSignal,
        SimulationState state,
        SemaphoreSlim dispatchSemaphore,
        ConcurrentDictionary<string, ConcurrentQueue<QueuedDispatchBatch>> dispatchQueueByTarget,
        IReadOnlyDictionary<string, IStructureSpikeTransport> grpcSpikeTransports,
        IReadOnlyDictionary<string, HttpClient> httpClients,
        bool useHttpSpikeTransportFallback,
        ConcurrentDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        int tickIoTimeoutMs,
        int maxSpikesPerDispatchRequest,
        Action<string>? onReplayDelivered,
        CancellationToken stoppingToken)
    {
        if (dispatchQueueByTarget.IsEmpty)
        {
            return DispatchFlushResult.Empty;
        }

        var deliveredSpikes = 0;
        var dispatchErrors = 0;
        var flushedBatches = 0;
        string? lastError = null;
        var errorGate = new object();
        var flushTargets = new List<DispatchFlushTarget>(dispatchQueueByTarget.Count);

        foreach (var targetEntry in dispatchQueueByTarget)
        {
            var batches = ListPool<QueuedDispatchBatch>.Rent();
            var mergedCapacity = 0;
            while (targetEntry.Value.TryDequeue(out var item))
            {
                if (item.Spikes.Count > 0)
                {
                    batches.Add(item);
                    mergedCapacity += item.Spikes.Count;
                }
            }

            if (batches.Count == 0 || mergedCapacity <= 0)
            {
                ListPool<QueuedDispatchBatch>.Return(batches);
                continue;
            }

            flushedBatches += batches.Count;
            var mergedSpikes = ListPool<SpikeMessage>.Rent(mergedCapacity);
            foreach (var batch in batches)
            {
                mergedSpikes.AddRange(batch.Spikes);
            }

            if (mergedSpikes.Count == 0)
            {
                ListPool<QueuedDispatchBatch>.Return(batches);
                ListPool<SpikeMessage>.Return(mergedSpikes);
                continue;
            }

            flushTargets.Add(new DispatchFlushTarget(targetEntry.Key, batches, mergedSpikes));
        }

        if (flushTargets.Count == 0)
        {
            return DispatchFlushResult.Empty;
        }

        flushTargets.Sort((a, b) => b.MergedSpikes.Count.CompareTo(a.MergedSpikes.Count));
        var activeTargets = flushTargets.Count;
        var maxTargetBurstSpikes = flushTargets[0].MergedSpikes.Count;
        var flushTasks = new Task[flushTargets.Count];

        for (var flushIndex = 0; flushIndex < flushTargets.Count; flushIndex++)
        {
            var flushTarget = flushTargets[flushIndex];
            flushTasks[flushIndex] = FlushTargetBatchAsync(
                flushTarget.TargetInstanceKey,
                flushTarget.SourceBatches,
                flushTarget.MergedSpikes,
                tickSignal,
                state,
                dispatchSemaphore,
                grpcSpikeTransports,
                httpClients,
                useHttpSpikeTransportFallback,
                activePathways,
                tickIoTimeoutMs,
                maxSpikesPerDispatchRequest,
                onReplayDelivered,
                stoppingToken,
                delivered =>
                {
                    if (delivered > 0)
                    {
                        Interlocked.Add(ref deliveredSpikes, delivered);
                    }
                },
                ex =>
                {
                    Interlocked.Increment(ref dispatchErrors);
                    lock (errorGate)
                    {
                        lastError ??= ex;
                    }
                });
        }

        try
        {
            await Task.WhenAll(flushTasks);
        }
        finally
        {
            for (var i = 0; i < flushTargets.Count; i++)
            {
                if (flushTargets[i].SourceBatches is List<QueuedDispatchBatch> sourceBatches)
                {
                    ListPool<QueuedDispatchBatch>.Return(sourceBatches);
                }

                if (flushTargets[i].MergedSpikes is List<SpikeMessage> mergedSpikes)
                {
                    ListPool<SpikeMessage>.Return(mergedSpikes);
                }
            }
        }

        return new DispatchFlushResult(
            flushedBatches,
            deliveredSpikes,
            dispatchErrors,
            lastError,
            activeTargets,
            maxTargetBurstSpikes);
    }

    private async Task FlushTargetBatchAsync(
        string targetInstanceKey,
        IReadOnlyList<QueuedDispatchBatch> sourceBatches,
        IReadOnlyList<SpikeMessage> mergedSpikes,
        TickSignal tickSignal,
        SimulationState state,
        SemaphoreSlim dispatchSemaphore,
        IReadOnlyDictionary<string, IStructureSpikeTransport> grpcSpikeTransports,
        IReadOnlyDictionary<string, HttpClient> httpClients,
        bool useHttpSpikeTransportFallback,
        ConcurrentDictionary<(StructureId Source, StructureId Target, NTEnum Nt), int> activePathways,
        int tickIoTimeoutMs,
        int maxSpikesPerDispatchRequest,
        Action<string>? onReplayDelivered,
        CancellationToken stoppingToken,
        Action<int> onDelivered,
        Action<string> onDispatchError)
    {
        await dispatchSemaphore.WaitAsync(stoppingToken);
        try
        {
            using var ctsIo = CancellationTokenSource.CreateLinkedTokenSource(stoppingToken);
            ctsIo.CancelAfter(TimeSpan.FromMilliseconds(tickIoTimeoutMs));
            var chunkSize = Math.Clamp(maxSpikesPerDispatchRequest, 1, 4096);
            var deliveredTotal = 0;
            for (var offset = 0; offset < mergedSpikes.Count; offset += chunkSize)
            {
                var count = Math.Min(chunkSize, mergedSpikes.Count - offset);
                if (count <= 0)
                {
                    continue;
                }

                var chunk = ListPool<SpikeMessage>.Rent(count);
                for (var i = 0; i < count; i++)
                {
                    chunk.Add(mergedSpikes[offset + i]);
                }
                try
                {
                    var deliveredChunk = await SendSpikeBatchToTargetAsync(
                        targetInstanceKey,
                        chunk,
                        grpcSpikeTransports,
                        httpClients,
                        useHttpSpikeTransportFallback,
                        ctsIo.Token);
                    if (deliveredChunk <= 0)
                    {
                        break;
                    }

                    var acceptedChunk = Math.Min(deliveredChunk, chunk.Count);
                    for (var i = 0; i < acceptedChunk; i++)
                    {
                        var key = (chunk[i].SourceStructure, chunk[i].TargetStructure, chunk[i].Neurotransmitter);
                        activePathways.AddOrUpdate(key, 1, (_, countValue) => countValue + 1);
                    }

                    deliveredTotal += acceptedChunk;
                    if (acceptedChunk < chunk.Count)
                    {
                        break;
                    }
                }
                finally
                {
                    ListPool<SpikeMessage>.Return(chunk);
                }
            }

            if (deliveredTotal <= 0)
            {
                return;
            }

            var remaining = Math.Min(deliveredTotal, mergedSpikes.Count);
            foreach (var batch in sourceBatches)
            {
                if (remaining <= 0)
                {
                    break;
                }

                var acceptedForBatch = Math.Min(batch.Spikes.Count, remaining);
                state.RecordDispatchedSpikes(
                    tickSignal.Tick,
                    tickSignal.TimestampMs,
                    batch.SourceHemisphere,
                    batch.TargetHemisphere,
                    targetInstanceKey,
                    batch.Spikes,
                    acceptedForBatch);
                if (acceptedForBatch > 0 &&
                    onReplayDelivered is not null &&
                    !string.IsNullOrWhiteSpace(batch.ReplayEngramKey))
                {
                    onReplayDelivered(batch.ReplayEngramKey);
                }
                remaining -= acceptedForBatch;
            }

            onDelivered(deliveredTotal);
        }
        catch (Exception dispatchEx)
        {
            logger.LogDebug(
                dispatchEx,
                "Batched dispatch failed for {TargetInstance} ({Count} spikes across {BatchCount} source batches)",
                targetInstanceKey,
                mergedSpikes.Count,
                sourceBatches.Count);
            onDispatchError($"{targetInstanceKey}: {ClassifyFailure(dispatchEx)}");
        }
        finally
        {
            dispatchSemaphore.Release();
        }
    }

    private async Task<int> SendSpikeBatchToTargetAsync(
        string targetInstanceKey,
        IReadOnlyList<SpikeMessage> spikes,
        IReadOnlyDictionary<string, IStructureSpikeTransport> grpcSpikeTransports,
        IReadOnlyDictionary<string, HttpClient> httpClients,
        bool useHttpSpikeTransportFallback,
        CancellationToken cancellationToken)
    {
        if (spikes.Count == 0)
        {
            return 0;
        }

        // Streaming path (opt-in via NRE_USE_GRPC_BIDI_STREAM). Enqueue success is
        // treated as "delivered" since the pump task is responsible for actual
        // transmission. On enqueue failure or absence of a session, fall through
        // to the existing unary gRPC / HTTP chain.
        if (_streamSessions.TryGetValue(targetInstanceKey, out var streamSession))
        {
            try
            {
                var spikeList = spikes as List<SpikeMessage> ?? spikes.ToList();
                var enqueued = await streamSession.TryEnqueueAsync(
                    new SpikeBatchEnvelope { Spikes = spikeList },
                    cancellationToken);
                if (enqueued)
                {
                    return spikes.Count;
                }
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                throw;
            }
            catch (Exception streamEx)
            {
                logger.LogDebug(streamEx, "Spike stream enqueue failed for {TargetInstance}; falling back to unary/HTTP", targetInstanceKey);
            }
        }

        if (_grpcDisabledTargets.TryGetValue(targetInstanceKey, out var disabled) && disabled)
        {
            if (!useHttpSpikeTransportFallback)
            {
                throw new HttpRequestException($"gRPC transport is disabled for {targetInstanceKey} and HTTP fallback is disabled.");
            }
        }
        else if (grpcSpikeTransports.TryGetValue(targetInstanceKey, out var grpcSpikeTransport))
        {
            try
            {
                var spikeList = spikes as List<SpikeMessage> ?? spikes.ToList();
                var grpcAck = await grpcSpikeTransport.PushSpikeBatchAsync(
                    new SpikeBatchEnvelope
                    {
                        Spikes = spikeList
                    });
                if (grpcAck.Accepted >= spikes.Count)
                {
                    _grpcFailureCounts.TryRemove(targetInstanceKey, out _);
                    _grpcDisabledTargets.TryRemove(targetInstanceKey, out _);
                    return spikes.Count;
                }

                if (!useHttpSpikeTransportFallback)
                {
                    throw new HttpRequestException(
                        $"gRPC transport accepted {grpcAck.Accepted}/{spikes.Count} spikes for {targetInstanceKey}. {grpcAck.Error}");
                }
            }
            catch (Exception grpcEx)
            {
                var immediateDisable = ShouldDisableGrpcTransportImmediately(grpcEx);
                var failures = immediateDisable
                    ? 6
                    : _grpcFailureCounts.AddOrUpdate(targetInstanceKey, 1, (_, count) => count + 1);
                if (failures >= 6)
                {
                    _grpcDisabledTargets[targetInstanceKey] = true;
                    logger.LogWarning(
                        "Disabling gRPC spike transport for {TargetInstance} after {FailureCount} failures. Falling back to HTTP.",
                        targetInstanceKey,
                        failures);
                }
                else
                {
                    logger.LogDebug(
                        grpcEx,
                        "gRPC spike transport failed for {TargetInstance}; fallback to HTTP (failure {FailureCount}).",
                        targetInstanceKey,
                        failures);
                }

                if (!useHttpSpikeTransportFallback)
                {
                    throw;
                }
            }
        }

        if (!useHttpSpikeTransportFallback)
        {
            throw new HttpRequestException($"No gRPC transport registered for {targetInstanceKey} and HTTP fallback is disabled.");
        }

        if (!httpClients.TryGetValue(targetInstanceKey, out var targetClient))
        {
            throw new HttpRequestException($"No HTTP client registered for {targetInstanceKey}.");
        }

        var batchEndpointUnavailable = _httpBatchEndpointUnavailableTargets.TryGetValue(targetInstanceKey, out var unavailable) && unavailable;
        var preferJsonBatch = _httpPreferJsonBatchTargets.TryGetValue(targetInstanceKey, out var preferJson) && preferJson;

        if (batchEndpointUnavailable)
        {
            var fallbackMode = preferJsonBatch ? HttpSingleFallbackMode.Json : HttpSingleFallbackMode.Binary;
            return await SendSpikesIndividuallyAsync(targetInstanceKey, targetClient, spikes, fallbackMode, cancellationToken);
        }

        if (!preferJsonBatch)
        {
            byte[] payload;
            await using (var envelope = new MemoryStream(Math.Max(256, spikes.Count * 128)))
            {
                foreach (var spike in spikes)
                {
                    await SpikeProtocol.send_spike(spike, envelope, cancellationToken);
                }

                payload = envelope.ToArray();
            }

            try
            {
                using var body = new ByteArrayContent(payload);
                body.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");
                using var dispatch = await targetClient.PostAsync("/api/v1/structure/spike-batch", body, cancellationToken);
                if (dispatch.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.MethodNotAllowed)
                {
                    _httpBatchEndpointUnavailableTargets[targetInstanceKey] = true;
                    return await SendSpikesIndividuallyAsync(targetInstanceKey, targetClient, spikes, HttpSingleFallbackMode.Binary, cancellationToken);
                }

                if (dispatch.StatusCode == HttpStatusCode.UnsupportedMediaType)
                {
                    _httpPreferJsonBatchTargets[targetInstanceKey] = true;
                }
                else
                {
                    await EnsureSuccessWithDetailsAsync(dispatch, cancellationToken);
                    _httpBatchEndpointUnavailableTargets.TryRemove(targetInstanceKey, out _);
                    _httpPreferJsonBatchTargets.TryRemove(targetInstanceKey, out _);
                    return spikes.Count;
                }
            }
            catch (Exception binaryDispatchEx) when (!cancellationToken.IsCancellationRequested)
            {
                if (ShouldPreferJsonBatch(binaryDispatchEx))
                {
                    _httpPreferJsonBatchTargets[targetInstanceKey] = true;
                }

                logger.LogDebug(
                    binaryDispatchEx,
                    "Binary spike dispatch failed for {TargetInstance}; retrying JSON compatibility path.",
                    targetInstanceKey);
            }
        }

        using var jsonBody = JsonContent.Create(spikes, DnneJsonContext.Default.ListSpikeMessage);
        using var jsonDispatch = await targetClient.PostAsync("/api/v1/structure/spike-batch", jsonBody, cancellationToken);
        if (jsonDispatch.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.MethodNotAllowed)
        {
            _httpBatchEndpointUnavailableTargets[targetInstanceKey] = true;
            return await SendSpikesIndividuallyAsync(targetInstanceKey, targetClient, spikes, HttpSingleFallbackMode.Json, cancellationToken);
        }

        await EnsureSuccessWithDetailsAsync(jsonDispatch, cancellationToken);
        _httpBatchEndpointUnavailableTargets.TryRemove(targetInstanceKey, out _);
        _httpPreferJsonBatchTargets[targetInstanceKey] = true;
        return spikes.Count;
    }

    private async Task<int> SendSpikesIndividuallyAsync(
        string targetInstanceKey,
        HttpClient targetClient,
        IReadOnlyList<SpikeMessage> spikes,
        HttpSingleFallbackMode fallbackMode,
        CancellationToken cancellationToken)
    {
        var delivered = 0;
        var mode = fallbackMode;
        for (var i = 0; i < spikes.Count; i++)
        {
            if (mode == HttpSingleFallbackMode.Binary)
            {
                try
                {
                    byte[] spikePayload;
                    await using (var singleEnvelope = new MemoryStream(256))
                    {
                        await SpikeProtocol.send_spike(spikes[i], singleEnvelope, cancellationToken);
                        spikePayload = singleEnvelope.ToArray();
                    }

                    using var singleBody = new ByteArrayContent(spikePayload);
                    singleBody.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");
                    using var singleDispatch = await targetClient.PostAsync("/api/v1/structure/spike", singleBody, cancellationToken);
                    await EnsureSuccessWithDetailsAsync(singleDispatch, cancellationToken);
                    delivered++;
                    continue;
                }
                catch (Exception singleBinaryEx) when (!cancellationToken.IsCancellationRequested && ShouldPreferJsonBatch(singleBinaryEx))
                {
                    mode = HttpSingleFallbackMode.Json;
                    _httpPreferJsonBatchTargets[targetInstanceKey] = true;
                }
            }

            using var singleJsonBody = JsonContent.Create(spikes[i], DnneJsonContext.Default.SpikeMessage);
            using var singleJsonDispatch = await targetClient.PostAsync("/api/v1/structure/spike", singleJsonBody, cancellationToken);
            await EnsureSuccessWithDetailsAsync(singleJsonDispatch, cancellationToken);
            delivered++;
        }

        return delivered;
    }

    private static bool ShouldPreferJsonBatch(Exception ex)
    {
        var message = ex.GetBaseException().Message ?? ex.Message ?? string.Empty;
        return message.Contains("Synchronous operations are disallowed", StringComparison.OrdinalIgnoreCase)
               || message.Contains("Unsupported Media Type", StringComparison.OrdinalIgnoreCase)
               || message.Contains("UnsupportedMediaType", StringComparison.OrdinalIgnoreCase)
               || message.Contains("415", StringComparison.OrdinalIgnoreCase);
    }

    private static bool ShouldDisableGrpcTransportImmediately(Exception ex)
    {
        foreach (var current in EnumerateExceptionChain(ex))
        {
            if (current is NotSupportedException)
            {
                return true;
            }

            var message = current.Message ?? string.Empty;
            if (message.Length == 0)
            {
                continue;
            }

            if (message.Contains("ResponseEnded", StringComparison.OrdinalIgnoreCase)
                || message.Contains("response ended prematurely", StringComparison.OrdinalIgnoreCase)
                || message.Contains("HTTP/2", StringComparison.OrdinalIgnoreCase)
                || message.Contains("HTTP2", StringComparison.OrdinalIgnoreCase)
                || message.Contains("content-type", StringComparison.OrdinalIgnoreCase)
                || message.Contains("grpc-status", StringComparison.OrdinalIgnoreCase)
                || message.Contains("gRPC call", StringComparison.OrdinalIgnoreCase)
                || message.Contains("Bad gRPC response", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private static IEnumerable<Exception> EnumerateExceptionChain(Exception ex)
    {
        for (var current = ex; current is not null; current = current.InnerException)
        {
            yield return current;
        }
    }

    private static async Task EnsureSuccessWithDetailsAsync(HttpResponseMessage response, CancellationToken cancellationToken)
    {
        if (response.IsSuccessStatusCode)
        {
            return;
        }

        string details;
        try
        {
            details = (await response.Content.ReadAsStringAsync(cancellationToken)).Trim();
        }
        catch
        {
            details = string.Empty;
        }

        if (string.IsNullOrWhiteSpace(details))
        {
            details = response.ReasonPhrase ?? "request failed";
        }

        if (details.Length > 320)
        {
            details = $"{details[..320]}...";
        }

        throw new HttpRequestException($"Response status code {(int)response.StatusCode} ({response.StatusCode}). {details}");
    }

    private sealed record SpontaneousNoiseProfile(
        double EventsPerSecond,
        int MinBurstSpikes,
        int MaxBurstSpikes,
        float MinVesicleQuanta,
        float MaxVesicleQuanta,
        double BurstProbability);

    private sealed class ServiceHealth
    {
        private readonly object _gate = new();
        private int _failureCount;
        private int _attemptCount;
        private int _successCount;
        private int _timeoutFailureCount;
        private double _lastAckLatencyMs;
        private double _ackLatencyEwmaMs;
        private int _latencyLt100MsCount;
        private int _latency100To250MsCount;
        private int _latency250To500MsCount;
        private int _latency500To1000MsCount;
        private int _latencyGte1000MsCount;
        private string _lastStatus = "INIT";
        private string _lastError = string.Empty;
        private long _lastTickProcessed;
        private double _lastUpdateTimestampMs;
        private long _lastDegradedLogTick = long.MinValue;

        public double NextRetryTimestampMs { get; private set; }

        public bool CanAttempt(double nowMs)
        {
            lock (_gate)
            {
                return nowMs >= NextRetryTimestampMs;
            }
        }

        public void MarkSuccess(double nowMs, double ackLatencyMs, long tick)
        {
            lock (_gate)
            {
                _failureCount = 0;
                _attemptCount++;
                _successCount++;
                NextRetryTimestampMs = 0;
                _lastAckLatencyMs = ackLatencyMs;
                _ackLatencyEwmaMs = _ackLatencyEwmaMs <= 0.001
                    ? ackLatencyMs
                    : ((_ackLatencyEwmaMs * 0.78) + (ackLatencyMs * 0.22));
                if (ackLatencyMs < 100)
                {
                    _latencyLt100MsCount++;
                }
                else if (ackLatencyMs < 250)
                {
                    _latency100To250MsCount++;
                }
                else if (ackLatencyMs < 500)
                {
                    _latency250To500MsCount++;
                }
                else if (ackLatencyMs < 1000)
                {
                    _latency500To1000MsCount++;
                }
                else
                {
                    _latencyGte1000MsCount++;
                }
                _lastStatus = "OK";
                _lastError = string.Empty;
                _lastTickProcessed = tick;
                _lastUpdateTimestampMs = nowMs;
            }
        }

        public void MarkFailure(double nowMs, long tick, string error)
        {
            lock (_gate)
            {
                _failureCount = Math.Min(_failureCount + 1, 8);
                _attemptCount++;
                if (error.Contains("timeout", StringComparison.OrdinalIgnoreCase))
                {
                    _timeoutFailureCount++;
                }
                var backoffMs = Math.Min(5000, 100 * Math.Pow(2, _failureCount));
                NextRetryTimestampMs = nowMs + backoffMs;
                _lastStatus = "DEGRADED";
                _lastError = error;
                _lastTickProcessed = tick;
                _lastUpdateTimestampMs = nowMs;
            }
        }

        public void Reset()
        {
            lock (_gate)
            {
                _failureCount = 0;
                _attemptCount = 0;
                _successCount = 0;
                _timeoutFailureCount = 0;
                NextRetryTimestampMs = 0;
                _lastAckLatencyMs = 0;
                _ackLatencyEwmaMs = 0;
                _latencyLt100MsCount = 0;
                _latency100To250MsCount = 0;
                _latency250To500MsCount = 0;
                _latency500To1000MsCount = 0;
                _latencyGte1000MsCount = 0;
                _lastStatus = "INIT";
                _lastError = string.Empty;
                _lastTickProcessed = 0;
                _lastUpdateTimestampMs = 0;
                _lastDegradedLogTick = long.MinValue;
            }
        }

        public ServiceRuntimeTelemetry CreateTelemetry(double nowMs)
        {
            lock (_gate)
            {
                var status = nowMs >= NextRetryTimestampMs ? _lastStatus : "BACKOFF";
                return new ServiceRuntimeTelemetry(
                    _lastAckLatencyMs,
                    _ackLatencyEwmaMs,
                    _failureCount,
                    _attemptCount,
                    _successCount,
                    _timeoutFailureCount,
                    NextRetryTimestampMs,
                    status,
                    _lastError,
                    _lastTickProcessed,
                    _lastUpdateTimestampMs,
                    _latencyLt100MsCount,
                    _latency100To250MsCount,
                    _latency250To500MsCount,
                    _latency500To1000MsCount,
                    _latencyGte1000MsCount);
            }
        }

        public bool ShouldEmitDegradedLog(long tick, int everyTicks)
        {
            lock (_gate)
            {
                if (tick - _lastDegradedLogTick < everyTicks)
                {
                    return false;
                }

                _lastDegradedLogTick = tick;
                return true;
            }
        }
    }
}

